    [39] = {n="Механічна білка", d="Логічний центр механічної білки велить їй збирати й запасати на зиму і горіхи, і болти."},
    [40] = {n="Бомбейська кішка", d="Донні Антанія планує, щоб після її смерті цю бомбейську кішку поховали разом з нею. Та мудрий мандрівник зможе знайти її талантам куди краще застосування."},
    [41] = {n="Корніш-рекс", d="Донні Антанія запрошує цих котів на свої чаювання. Та ніколи не подає їм улюбленого напою: сліз їхніх ворогів."},
    [42] = {n="Чорна смугаста кішка", d="Старе альтеракське прислів'я: «У кішки дев'ять життів, та потрібне їй лише одне.»"},
    [43] = {n="Руда смугаста кішка", d="Останній, хто намагався привчити цю кішку до порядку, швидко зрозумів: забруднений килим кращий за пошматоване геть усе інше."},
    [44] = {n="Сіамська кішка", d="Відома своїми блакитними очима. А ще вважається делікатесом серед велетенських мурлоків."},
    [45] = {n="Срібляста смугаста кішка", d="Спати — друге улюблене заняття цієї кішки. Перше — позіхати."},
    [46] = {n="Біле кошеня", d="«У королеви було троє кошенят. Перше принесло їй соковитого щура. Друге — смачного зайця. А біле, її улюблене, піднесло їй голову суперниці.»"},
    [47] = {n="Корела", d="Дехто каже, що цього кмітливого птаха можна навчити говорити — але він достатньо розумний, щоб тримати дзьоба стуленим."},
    [49] = {n="Гіацинтовий ара", d="Тролі джунглів навчають цих птахів імітувати заклики про допомогу, щоб заманювати безтурботних подорожніх у пастки."},
    [50] = {n="Зеленокрилий ара", d="Улюбленець піратів Дефаес, цей барвистий птах стає у пригоді, щоб запам'ятовувати паролі, списки покупок і рецепти крекерів."},
    [51] = {n="Сенегальський папуга", d="Улюбленець ґоблінів Затоки Здобичі, цей барвистий птах славиться вмінням лічити монети, зводити бюджети й брехати про умови угод."},
    [52] = {n="Анконська курка", d="Вона теж вважає, що ти на смак як курятина."},
    [55] = {n="Тарган Андерсіті", d="Тарган — це зазвичай імпульсивна покупка. Та згодом власникам надзвичайно важко з ним розлучитися, хай скільки разів вони пробують."},
