    [57] = {n="Лазурове драконятко", d="Як і решта зграї синіх драконів, ці грайливі малі створіння мають хист до арканної магії."},
    [58] = {n="Багряне драконятко", d="Цей юний дракон родом із Драговин лише вчиться полювати, дихати вогнем і мило сіяти руйнацію на своєму шляху."},
    [59] = {n="Смарагдове драконятко", d="Цю унікальну позграї драконів колись вивів і виростив зелений дракон Ітаріус, а нині вона оселилася в джунглях Фераласу."},
    [64] = {n="Лісова жаба", d="Торговці на Ярмарку Сповненого Місяця пропонують дивовижні й екзотичні чудеса. А ще вони продають лісових жаб."},
