    [75] = {n="Чорна королівська змія", d="Ксан'тіш безстрашно вистежує, ловить і навчає цих шляхетних змій, щоб вони допомагали побратимам у бою."},
    [77] = {n="Бура змія", d="Бура змія мешкає на землях, підвладних Орді. Вона здається непримітною, доки жертва не опиниться поряд."},
    [78] = {n="Багряна змія", d="Тролі Даркспір цінують багряну змію не лише за люту вдачу, а й за непохитну вірність."},
    [83] = {n="Механічна курка", d="Не хвилюйтеся: бойові механізми й системи самонаведення на цьому пристрої вимкнено. Здається. — Оґлторп Обнотікус"},
