    [85] = {n="Бомбочка-улюбленець", d="Можливо, вибухова, та безперечно чарівна. Тримати подалі від відкритого вогню."},
    [86] = {n="Малюк Димко", d="Цього крихітного охоронного робота-миротворця часто оснащують найновішими арканними нейтралізаторами й розганячами натовпу. Не для тих, хто дбає про довкілля."},
    [87] = {n="Пташеня феї-стрілодзьоба", d="Ці чарівні створіння люблять притулитися до своїх господарів після довгого дня жорстоких, кривавих битв."},
