    [92] = {n="Панденя", d="Це крихітне панденя дуже бажане для шукачів пригод по всьому Азероту — попри свою сонливу вдачу."},
    [93] = {n="Міні-Діабло", d="І ЗДРИГНУТЬСЯ НЕБЕСА, І ЗАПЛАЧЕ ЛЮДСТВО, І НАСТАНЕ КІНЕЦЬ УСІХ ДНІВ... стривай, а чому ти такий високий?"},
    [94] = {n="Зерґлінг", d="Малий і лютий представник рою Зергів, зерґлінг — не та істота, з якою варто жартувати. Дуже небезпечний у великій кількості."},
    [95] = {n="Реалістична жаба", d="Талановиті інженери створили точну копію лісової жаби — усього лише вдесятеро дорожчу за справжню."},
    [106] = {n="Джублінг", d="Легендарну пивну жабу вважали вимерлою, аж доки дивні варива Ярмарку Місяцесутіні не виманили її зі схованки."},
    [107] = {n="Муркі", d="Поява цього улюбленого й вкрай відлюдькуватого мурлока неодмінно збирає натовп."},
    [111] = {n="Луркі", d="Чарівна вдача Луркі та його жваві витівки гарантовано розвіюють роздратування й піднімають настрій навіть у найпохмуріші хвилини."},
    [114] = {n="Огидний слизняк", d="Увага: працюючи з огидним слизняком, вдягайте рукавиці й захисні окуляри. НЕ МИТИ. Залишає плями на більшості обладунків."},
    [115] = {n="Сухопутна акула", d="Щойно народившись, акуленята швидко тікають від своїх голодних матерів. Рання самостійність робить їх небезпечними навіть замолоду."},
    [116] = {n="Спокійний механічний єті", d="Ця хитромудра іграшка має таємний перемикач, що вимикає режим «спокою». На щастя, навіть інженери, які її змайстрували, не знають, де його шукати."},
    [117] = {n="Крихітний сніговик", d="Він обожнює танцювати, махати й гратися з тобою! Після Свята Зимової Заслони він тане, але не хвилюйся — колись він повернеться знову!"},
