    [119] = {n="Помічник Батька Зими", d="Ці позасезонні союзники невпинно працюють, готуючись до Свята Зимової Заслони, тож були б вдячні, якби решту року їх не турбували."},
    [120] = {n="Маленька помічниця Зими", d="Під час величного свята Зимової Заслони ці вірні супутники сіють радість по всьому краю. А решту року вони зайняті."},
    [121] = {n="Ґуркі", d="Ґуркі — артистка від народження, та все ж тримається осторонь і виходить на люди лише в найрідкісніших випадках."},
    [122] = {n="Педлфіт", d="Сила любові буває небезпечною штукою, надто коли нею орудує летючий гоблін лихої вдачі."},
    [124] = {n="Полі", d="Це ведмежа має чимало спільного зі своєю ріднею, але в умінні співати йому немає рівних."},
    [125] = {n="Швидкий", d="Тихше їдеш — далі будеш."},
    [126] = {n="Пан Вертун", d="Багато хто гадає, ніби «Вертун» — це про те, як крутиться зад цієї свині. Справжнє значення вони пізнають, коли побачать власні нутрощі."},
    [127] = {n="Вусань-щур", d="Кмітливий тактик, Вусань прикинеться мертвим, щоб обдурити хижаків і збирачів боргів."},
    [128] = {n="Дух Літа", d="Цей маленький шматочок літа пахне теплими вечорами і грозовими бурями. Якщо придивитися, можна навіть розгледіти обличчя."},
    [130] = {n="Гіпогрифеня", d="Після нальоту гарпій у Фераласі кілька гніздовищ гіпогрифів зазнали нападу. Сотні малят лишилися сиротами, і їх віддали під опіку друїдів на острові Сардор."},
    [131] = {n="Нетердраконя", d="Нащадок нетердраконів Аутленду, цей юний дракон ще тільки вростає у свою роль мисливця, захисника й чарівного жаху небес."},
    [132] = {n="Магічний річковий рак", d="Лише магічні бажання творять магічних річкових раків. Хочеш рибки — лови бажання, хочеш бажання — лови рибку."},
    [136] = {n="Манавирменя", d="Ефіріал Рашаад почав розводити цих загадкових створінь, дізнавшись про їхню здатність живитися арканною енергією."},
    [137] = {n="Бурий кролик", d="Це кроленя — наймиліше, що його супротивник колись побачить. А ще й останнє."},
    [138] = {n="Синій нічний метелик", d="Тендітний мешканець острова Лазурної Імли. Подейкують, що ця чарівна комаха наділена цілющою силою."},
    [139] = {n="Червоний нічний метелик", d="Наслідок дії дикої магічної енергії: ця комаха стала несподівано барвистим витвором того, що азеротських нічних метеликів випустили в екокуполи Нетерсторму."},
    [140] = {n="Жовтий нічний метелик", d="Найбільше любить літати під час грози, що часто буває на острові Лазурної Імли."},
    [141] = {n="Білий нічний метелик", d="Найбільше любить літати туманними ночами, що часто бувають на острові Лазурної Імли."},
    [142] = {n="Золоте драконояструбеня", d="Колись його високо цінували розводчики драконояструбів у Сільвермуні. Уночі добре помітне для хижаків, тож пильність доводиться розвивати змалку."},
    [143] = {n="Червоне драконояструбеня", d="Смертельний ворог срібних драконояструбів, а от із золотими ладнає цілком пристойно."},
    [144] = {n="Срібне драконояструбеня", d="Лютий різновид драконояструба: його часто можна побачити, коли воно стрімко пікірує на здобич із піднебесся."},
    [145] = {n="Синє драконояструбеня", d="Виплекане тими нечисленними торговцями, які ще наважуються вести справи в Нетерстормі."},
    [146] = {n="Світлячок", d="Цю світлу комаху споролінги часто беруть за джерело світла, коли мандрують водними шляхами Зангармаршу. Вона допомагає їм уникати небезпечних болотних жалунів Багнопалу."},
    [149] = {n="Мінікрил", d="Магічна енергія, що вивільнилася під час перетворення Скайвінга назад на його справжню подобу араккоа, звільнила це бідолашне створіння — пташеня, яке Луанга ув'язнив, щоб живити своє пташине прокляття."},
    [153] = {n="Вольпертінґер", d="Чимало захмелілих гостей Свята Броварів розповідали про цю загадкову істоту, та мало хто згадає ту розповідь уранці."},
    [155] = {n="Щасливчик", d="Щасливчик верещить, коли сердиться або коли їсть. У будь-якому разі краще його не турбувати."},
    [156] = {n="Бананас", d="Хоч Ландро й не хотів розлучатися з Бананасом, він розумів, що буде безпечніше, якщо улюбленець опиниться подалі від Затоки Здобичі, коли його батько, король Мукла, виявить пропажу."},
    [157] = {n="Віллі", d="Він трохи лиховісний, зате страшенно сонливий. Тримай його подалі від дрібноти!"},
    [158] = {n="Еґберт", d="Сін'дорей їздять верхи на яструбоступах, та це маля визнали непридатним після того, як у нього виявили безліч тривожних розладів."},
    [159] = {n="Горішок", d="Приручених елекків дренеї навчають як їздових тварин. У дикій природі на них полюють заради бивнів зі слонової кістки."},
    [160] = {n="Смердючка", d="Смердючка користується своїм ароматом, щоб відлякувати хижаків і приваблювати котів. З першим у нього виходить значно краще, ніж із другим."},
    [162] = {n="Зловісний гарбузик", d="Цей пустотливий гарбуз полюбляє вистрибувати із землі й лякати тебе до нестями. Хвала гарбузовій пісні!"},
    [163] = {n="Зубастик", d="Шкуру та м'ясо крокіліска високо цінують мисливці, але звір лютий і його рідко вдається застати зненацька."},
    [164] = {n="Багнодих", d="Багнодих такий самий, як інші крокіліски, тільки має чудове почуття гумору."},
    [165] = {n="Моджо", d="Знахарі амані перетворили на жаб чимало своїх жертв. Декотрі так і не оговталися."},
    [166] = {n="Малесенький рожевий товстошкір", d="Рожевий елекк — істота сором'язлива. Він покажеться лише тим, з ким заприязнився, або ж тому, хто надто сп'янів, щоб завдати йому шкоди."},
    [167] = {n="Крихітний споролітун", d="Дикі споролітуни — лютющі створіння, але якщо приручити їх змалку, вони стають вірними супутниками."},
    [168] = {n="Курка-ракета", d="Коли Палаючий Легіон вторгся в Аутленд, Ландро Лонгшот запропонував цей задум для воєнних потреб. Та ні Альянс, ні Орда не взялися його втілювати."},
    [169] = {n="Повітряний змій-дракон", d="Куди тихіший за справжнього дракона."},
    [170] = {n="Золоте порося", d="Це золоте порося шанує своїх предків, даруючи спільникам удачу."},
    [171] = {n="Срібне порося", d="Друїди вважають, що срібні поросята мають особливий зв'язок із золотими, адже обидві породи з'явилися в Азероті одночасно."},
    [172] = {n="Палаючий вогник", d="Старійшини-шамани попереджають, що вогники Рагнароса, віддані слуги Володаря Вогню, оселилися на Розплавленому Фронті. Радимо бути пильними."},
    [173] = {n="Гарчун", d="Крокіліски — шестилапі хижаки-амфібії, що мешкають у прибережних водах. Археологи припускають, що вони походять від диметродонів кратера Ун'Ґоро."},
    [174] = {n="Чак", d="Кілька років вивчаючи крокілісків, славетний рибалка Нат Паґл дійшов висновку, що малі крокіліски здебільшого безпечні."},
    [175] = {n="Пташеня фенікса", d="Дитя бога-фенікса Ал'ара, це пташеня злітає в небо одразу після народження."},
    [179] = {n="Дух змагань", d="Ці дивовижні створіння, що їх вручають героям за перемогу в бою, уособлюють відвагу й силу."},
    [180] = {n="Сутність змагань", d="Лише герої, що довели свою доблесть великими діяннями, отримують у дар одну з цих містичних зміїстих істот."},
    [183] = {n="Ефірний торговець душами", d="Ефірні торговці душами подорожують із тими, хто здатен звільнити потрібні їм есенції від норовливих носіїв."},
    [186] = {n="Личинка нетерового ската", d="Нетерові скати, рідні для лісу Терокар, з'являються на світ під час сезону дощів. Із сотень нащадків одного виводка до дорослого віку доживають лічені одиниці."},
    [187] = {n="Вампірське кажаненя", d="Вампірських кажанів Знедолені з Андерсіті й тролі-амані із Зул'Амана привчили служити розвідниками та їздовими тваринами."},
    [188] = {n="Морозко", d="Випадково з'явився на світ, коли смертоносна сила Короля-Ліча підняла Памороззя з небуття."},
    [189] = {n="Міні-Тираель", d="«Я — сама Справедливість!»"},
    [190] = {n="Примарний череп", d="Відчувши близьку смерть створіння поруч, череп заходиться пронизливим вищанням."},
    [191] = {n="Механічний бот-ракета", d="Цей механічний воїн — улюблений подарунок на Свято Зимового Покрову. Батарейки не додаються, а от ракети — однозначно так!"},
    [192] = {n="Пан Мерзлик", d="Образ пана Мерзлика навіює спогади про витонченіші часи, коли дуелянти билися у фраках."},
    [193] = {n="Велетенський каналізаційний щур", d="З цим щуром не хотілося б зустрітися в темному провулку. Та й деінде, як по правді, теж."},
    [194] = {n="Пташеня волопаса", d="На відміну від більшості «таємничих яєць» Ґіна-ґорлока, у цьому й справді була жива істота."},
    [195] = {n="Біле пташеня волопаса", d="Рідкісного білого волопаса шанують серед Оракулів. Його поява вважається ознакою рясних злив, доброго врожаю личинок і зимового сну волварів."},
    [196] = {n="Дитинча протодракона", d="Ці ненажерливі дитинчата ростуть із неймовірною швидкістю й можуть за день поглинути сирого м'яса майже удвічі більше за власну вагу."},
    [197] = {n="Кобреня", d="Кобри Азероту славляться своєю швидкодійною отрутою та блискавичними укусами."},
    [198] = {n="Пенґу", d="Вирізняється великими очима та зухвалим ковзанням."},
    [199] = {n="Фамільяр Кірін-Тора", d="Щоб учні нишком не використовували фамільяра для виконання своїх обов'язків, архімаги розпорошили ритуал його прикликання сторінками кількох книг заклинань, схованих по всьому Даларану."},
    [200] = {n="Весняний кролик", d="Весняні кролики символізують плодючість і залюбки показують, чому саме."},
    [201] = {n="Гладка індичка", d="Вона скромна, наділена ясновидінням і неперевершена з журавлиним соусом."},
    [202] = {n="Ведмежатко Близзард", d="Цього рідкісного ведмедя виводять заради його малих розмірів і вічно юного вигляду."},
    [203] = {n="Оленятко", d="Любить товариство друзів. Сімдесяти п'яти, якщо бути точним."},
    [204] = {n="Паросток Тельдрасілу", d="Воно завжди прокидається в танці. Яке щасливе деревце!"},
    [205] = {n="Вовченя з Дун-Морогу", d="Ведмедів Дун-Морогу цінують за витривалість, відданість і бойову вправність. Час, проведений серед дворфів, аж ніяк не вгамовує їхню лють."},
    [206] = {n="Кажанчик з Тірісфалу", d="Здатний відчувати серцебиття супротивника завдяки ехолокації."},
    [207] = {n="Скорпіон з Дуротару", d="Норовливий скорпіон із Дуротару — лютий хижак пустелі. Відомий тим, що лише вряди-годи жалить власного господаря."},
    [209] = {n="Ягня з Елвінну", d="На відміну від тих, що з'явилися через перетворення, справжні вівці бувають доволі моторошними."},
    [210] = {n="Пташеня з Малгору", d="Швидкості довгоступа на відкритій місцевості немає рівних, тож хижаки покладаються на скрадання й зграйну тактику, коли полюють на нього."},
    [211] = {n="Береговий повзун", d="Береговий повзун пристосувався до північного холоду, впадаючи в сплячку під острівними пляжами."},
    [212] = {n="Батожник з долини Аммен", d="Довгострокові наслідки забруднення, спричиненого Екзодаром, досі перебувають під наглядом."},
    [213] = {n="Зачарована мітла", d="Цю мітлу створив учень-ельф крові. Вона була б надзвичайно корисною, якби хтось додумався, як її зупинити."},
    [214] = {n="Зброєносець Срібного Авангарду", d="Чимало стормвіндської молоді вступило до Срібного Авангарду зброєносцями, сподіваючись колись послужити Святому Світлу в бою."},
    [215] = {n="Механопищик", d="Механопищика використовують як навчальну їздову тварину для юних гномів. Швидкості старших братів у нього немає, зате є вся їхня чарівність."},
    [216] = {n="Піхотинець Срібного Авангарду", d="Ці юні орки прагнуть утілювати чесноти Срібного Авангарду: відвагу, силу і доброчесність."},
    [217] = {n="Муркімус Гладіатор", d="Муркімус — найгрізніший з усіх мурлоків-бійців арени. А якийсь час був і єдиним."},
    [218] = {n="Фетиш із Сенджину", d="Насправді це три улюбленці в одному. Поки не прикличеш, не знатимеш, кого отримаєш!"},
    [220] = {n="В'ялий", d="Скорботне нагадування про те, що було втрачено, коли Світоруйнівник змінив обличчя Азероту."},
    [224] = {n="Триколірна кішка", d="Багато хто кепкував з цієї кішки перед боєм. Їхніми останніми словами зазвичай були: «Кицю, кицю, кицю»."},
    [225] = {n="Допитливе пуголовко оракулів", d="Стрибучий ґурлок — далекий родич мурлока."},
    [226] = {n="Допитливе вовченя вольварів", d="Попри менший зріст, вольвари — одні з найагресивніших створінь Нортренду. Через це їхня допитлива вдача нерідко видається загрозливою."},
    [227] = {n="Бойовий бот", d="Бойовий робот, що працює на смачних червоних чи синіх електролітах."},
    [228] = {n="Ґрунті", d="Лише найрідкісніші з мурлоків здатні успішно долати межі вимірів. Ще менше повертається з таким досконалим обладунком і зброєю, які має Ґрунті."},
    [229] = {n="Мерехтливий вірмлінг", d="Цей надзвичайно рідкісний різновид манавирма цінують за неповторне забарвлення й лагідну вдачу."},
    [231] = {n="Нефритовий тигр", d="Тигрів, вирізьблених із нефриту, вважають за щасливий знак і дуже цінують, та приборкати справжнього нефритового тигра — нагорода ще більша."},
    [232] = {n="Прудке маля", d="Рідко покидає гніздо, доки не подорослішає. Полюбляє влаштовувати витівки в сусідньому гнізді гостроіклів."},
    [233] = {n="Маля девіанта", d="Попит на цей лілошкірий різновид різко скоротив популяцію рапторів поблизу Печер Лементу."},
    [234] = {n="Маля з Гундраку", d="Цей хитрий раптор народився в крижаних пустках Нортренду. Сувора молодість дає йому силу там, де багато інших загинули б."},
    [235] = {n="Стрибуче маля", d="Це нащадок Такка Стрибуна — неймовірно спритне й легко долає важку місцевість."},
    [236] = {n="Обсидіанове маля", d="Це маля жадають за неповторне забарвлення. Попри дбайливу турботу Бреанні, дику вдачу раптора не вгамувати."},
    [237] = {n="Маля равазавра", d="Більші за інших малят рапторів, ці малята виростають у велетенських ящероподібних звірів, здатних чинити жахливі руйнування."},
    [238] = {n="Гостроіклове маля", d="Яйця гостроіклів матері захищають люто. Їхня миловидність приховує успадковану лютість."},
    [239] = {n="Маля разаші", d="Раптори разаші — одні з найкмітливіших хижаків джунглів, тому їх так полюбляють тролі ґурубаші."},
    [240] = {n="Оніксова пантера", d="Оніксова пантера невидима вночі, мов скрадлива тінь, і зникає з настанням світанку."},
    [241] = {n="Повітряний змій тускарів", d="Якщо побачиш цих зміїв, що ширяють над берегами Нортренду, — це певна ознака того, що тускари десь поряд."},
    [242] = {n="Спектральне тигреня", d="Ласкаві й допитливі, ці тигренята примудряються знаходити найдивовижніші схованки."},
    [243] = {n="Дитинча Оніксії", d="Породження Оніксії, цей юний дракон вирішив, що не хоче йти катаклізмічними слідами свого діда."},
    [244] = {n="Цуценя пекельного пса", d="Пекельні пси, яких можна зустріти у Вогняних Землях і Розплавленому Ядрі, ведуть свій родовід від ватажка зграї — Маґмадара."},
    [245] = {n="Грифоненя", d="Дарунок дворфів Дикомолотів героям Альянсу, ці грифоненята — нащадки тих самих грифонів, на яких Фалстад зі своїм почтом увірвалися до Ґрім Батолу."},
    [246] = {n="Маля наїзника на вітрі", d="Старий Торг Безногий ніколи не зважав на давню орчу мудрість: «Не тягни віверну за хвіст»."},
    [247] = {n="Тигр зіпао", d="Цю рідкісну родину тигрів бачили лише вряди-годи, тож багато хто вважає (можливо, помилково), що за їхнє неповторне забарвлення відповідальні рештки магії чи якась інша подія."},
    [248] = {n="Пандаренський монах", d="Пандаренський монах — безстрашний супутник у мандрах, що невпинно вдосконалює свою майстерність... доки ти не запропонуєш йому випити. Відмовитися він вважає за неввічливість."},
    [249] = {n="Малий К.Т.", d="За життя Кель'Тузад зрадив Кірін Тор і створив Культ Проклятих. По смерті він служить Погибелі як архіліч, володар Наксрамасу."},
    [250] = {n="Жвавий мопс", d="Попри малий зріст, мопси дуже небезпечні, коли їх роздратувати."},
    [251] = {n="Токсичний відходник", d="Це, гм, «чарівне» мале створіння полюбляє бавитися з дрібними звірятами. Тільки не давай їм підходити надто близько."},
    [253] = {n="Холодний морозлик", d="Хоч він і близько не такий руйнівний, як його первісний господар, Крижаний Володар Агуне, морозлик відомий тим, що жбурляє холодні сніжки в необачних шукачів пригод."},
    [254] = {n="Синій механічний ракетобот", d="Найкраще розкуплена іграшка Джепетто цього сезону: через новий синій корпус діти по всьому Азероту наввипередки полюють за цим завзятим бойовим ботом."},
    [255] = {n="Небесний дракон", d="Бреанні з Даларана, одна з найвідоміших у світі збирачок екзотичних улюбленців, дарує містичного небесного дракона лише тим колекціонерам, чия одержимість не поступається її власній."},
    [256] = {n="Малий XT", d="Створений за подобою велетенського титанічного прототипу в Улдуарі, цей вибуховий малий конструкт грається своїми іграшками без жодної пощади."},
    [258] = {n="Міні-Тор", d="Потужна артилерія армії теранів. Тор завжди першим кидається в бій і останнім його полишає!"},
    [259] = {n="Синій міні-турнірник", d="На відміну від свого золотого побратима, синій міні-турнірник не поспішає, коли штрикає противника в очі."},
    [260] = {n="Золотий міні-турнірник", d="Це створіння сумнозвісне своїм умінням швидко й люто штрикати в очі."},
    [261] = {n="Особистий руйнівник світу", d="Гоблінська інженерія у своєму найкращому вияві. Креслення створено за зразком велетенського спустошувача Скверни з півострова Пекельного Вогню."},
    [262] = {n="Роззброєний механічний супутник", d="Взірець міцного ґномського дизайну: цей механічний звір — ідеальний супутник для самотнього мандрівного інженера."},
    [264] = {n="Повзуча кліщня", d="На перший погляд це не більш ніж лапа невеликого примата. Та придивившись, бачиш, що рука висохла за століття під пісками Улдуму."},
    [265] = {n="Камінчик", d="Допитливий малий елементаль Камінчик утік від голодних вирворобів у Крихких Глибинах, здолав порожнечу Викривленої Порожнечі й зрештою був урятований зі звичайної поштової скриньки."},
    [266] = {n="Скам'яніле малятко", d="Ти дивишся на неї, а вона дивиться просто на тебе у відповідь. Така кмітлива — інколи здається, наче вона міркує, як відчинити двері."},
    [267] = {n="Зачарований ліхтар", d="Зменшує ймовірність бути зжертим монстрами, коли заходиш у непроглядно темні місця."},
    [268] = {n="Малий Дезвінг", d="Цілі народи тремтять під його тінню — Руйнівник, колишній Аспект Землі, чудовисько, що розкололо Азерот навпіл. Тепер у зручному дорожньому форматі!"},
    [270] = {n="Малятко темного фенікса", d="Вогняні малята народжуються з попелу фенікса. Темні малята постають із його тіней."},
    [271] = {n="Чайка Іржавих Гір", d="Цей птах — бувалий ветеран нескінченних морських битв довкола Тол Бараду. Ветеран, що добряче розгладшав, длубаючись у недоїдках, певна річ."},
    [272] = {n="Армадилове малятко", d="Згортається в захисний клубок, коли почувається в небезпеці. Або коли його кличе мати."},
    [277] = {n="Механічний гном", d="Уважають, що механічний гном був первісним витвором титанів. Деякі його шестерні менші, ніж може розгледіти око."},
    [278] = {n="Лисеня", d="Через бої на Тол Бараді цих лисенят стало важко знайти, тож юрба охочих завести улюбленця добряче прорідила тамтешню лисячу популяцію."},
    [279] = {n="Крихітний сланцевий павук", d="Сланцевий павук — елементаль, а не справжній павукоподібний. Та його витривалість і лютість наганяють страх навіть у Глибокотверді."},
    [280] = {n="Гільдійський паж", d="Гільдійські пажі мусять бути безстрашними, адже саме їм випадає звіщати про перемоги своєї гільдії над Ордою в бою."},
    [283] = {n="Гільдійський герольд", d="Заможні гільдії привертають увагу солдатів, готових нести їхні штандарти в бій."},
    [285] = {n="Малий XT Ландро", d="Завжди «готовий гратися», малий XT Ландро майже не відрізняється від оригіналу. Схильний до нападів люті й нарколепсії."},
    [286] = {n="Пан Ґраббс", d="Личинки Чумних Земель — побічний наслідок некромантської скверни й величезної кількості трупів там. Пан Ґраббс походить із особливо акробатичного роду."},
    [287] = {n="Крихітна вогнемушка", d="Удень ці дивні комахи рояться над відкритими лавовими ямами, а вночі випромінюють вогнисте сяйво."},
    [289] = {n="Скутер-равлик", d="Шукай його в мушлі — саме там, де й має бути равлик!"},
    [291] = {n="Співучий соняшник", d="Ця мила квітка скрасить твій день теплою усмішкою та веселою піснею! А ще дуже сильна проти нежиті."},
    [292] = {n="Чарівна лампа", d="Гігітус фіґі- гокіті покі- абракадаб- престидиґі--ох, чорт забирай!"},
    [293] = {n="Елементієва жеода", d="Шахтарі часто плутають жеоду з рідкісним самоцвітом. Про свою присутність вона повідомляє мелодійними відлуннями."},
    [294] = {n="Смертик", d="Поява Дезвінга змінила весь Азерот; навіть мурлоки, що живуть в океані, не вберіглися від його згубного впливу."},
    [296] = {n="Малятко місячного жерця", d="Місячні жерці благословенні Елуною й несуть благодать природи всюди, куди прямують. Ці святкові птахи завжди не проти потанцювати."},
    [297] = {n="Малий Раґнарос", d="Ніколи не зарано прикликати це крихітне втілення грізного Володаря Вогню."},
    [301] = {n="Пантереня", d="Воно поглянуло на тебе цими великими чорними очима, ніби питаючи: «Ти моя мама?»"},
    [302] = {n="Лічик Ландро", d="Як ґоблін Ландро Лонгшот спершу заволодів цим лічиком, лишається загадкою, та він надто радо поставив його на кін у грі в карти."},
    [303] = {n="Малятко нічного шаблезуба", d="Елуна зробила нічних шаблезубів сріблясто-чорними, щоб вони могли зливатися з тінями місячної ночі."},
    [306] = {n="Зимове ведмежатко", d="Зимові ведмежата найщасливіші, коли пустують у свіжому снігу."},
    [307] = {n="Малятко хльосткохвоста", d="У джунглях Каменотерну невдатних малят-рапторів часто ловлять ґурубаші й тягнуть до тролячого міста Зул'Ґуруб."},
    [308] = {n="Ніжки", d="Дикі болотні бродяги небезпечно агресивні, та якщо вдасться приручити такого, він стане відданим і лагідним другом."},
    [309] = {n="Малятко птеродакса", d="Яйця птеродаксів висиджують під скам'янілими рештками їхніх предків, тож малята вбирають у себе лють і кмітливість пращурів."},
    [310] = {n="Вудуйська статуетка", d="Вудуйські статуетки часто наповнювали силою за допомогою флаконів моджо, тролячого поту й плоті ворогів племені."},
    [311] = {n="Дитинча-охоронець", d="Цей крихітний крилатий лев іще трохи незграбний, але вчиться стати найкращою їздовою твариною, на яку тільки здатен!"},
    [316] = {n="Кенарійське маля", d="Кенарійські малята ще не ті грізні створіння, якими стануть дорослими, тож їхній майже безневинний вигляд не раз заставав зненацька недосвідчених наставників Кенарійського Кола."},
    [317] = {n="Ведмежа Гіджалу", d="Ведмежата Гіджалу багато натерпілися під час Катаклізму. Та є й світлий бік: руйнація зрештою пробудила в них любов до висоти й відчайдушних трюків."},
    [318] = {n="Багряний батожник", d="Батожник родом із попелястих ґрунтів Вогняних Земель, а на Азерот його перенесли з допомогою Вартових Гіджалу."},
    [319] = {n="Котячий фамільяр", d="Лети крізь ніч під місяцем (разом із цією пухнастою вусатою відьмою) у найглупішу пору!"},
    [320] = {n="Малятко Тарекґоса", d="Легендарний представник синьої зграї драконів."},
    [321] = {n="Моторошна скриня", d="Колишні власники скрині розповідали про зникнення інших улюбленців з їхньої колекції."},
    [323] = {n="Горішок", d="Більшість білок запасають жолуді на прожиток. А от Горішок збирає жолуді, щоб поповнити запас боєприпасів."},
    [325] = {n="Осяйний каліри", d="Одне з найрідкісніших створінь, цей каліри вирізняється серед інших осяйним оперенням та тим, на що ладні піти мисливці, аби його впіймати."},
    [328] = {n="Фіолетова риба-куля", d="Ти можеш подумати, що ця риба без води — слабкий супротивник... поки не побачиш, яка лють криється в її захисній бульбашці."},
    [329] = {n="Муркабло", d="Коли стаєш проти Муркабло чи будь-кого з Прадавніх мурлоків, мати при собі камінь душі вкрай бажано."},
    [330] = {n="Похмуромісячна мавпа", d="Мавпи Азероту — горезвісні витівники, а ці улюблені супутники Ярмарку Похмурого Місяця піднесли вроджену хитрість на цілком новий рівень."},
    [331] = {n="Кулька Альянсу", d="Створені, щоб розважати дітей на Ярмарку Похмурого Місяця, ці чарівні кульки ніколи не втрачають своєї легкості."},
    [332] = {n="Кулька Орди", d="Справжнє диво магії: ці кульки ніколи не здуваються, а традиційно їх виготовляють партіями по дев'яносто дев'ять."},
    [333] = {n="Товариський ґрелл", d="Ґрелли — це втілення дикої сторони природи. Приручені трапляються дуже рідко."},
    [335] = {n="Похмуромісячна черепаха", d="Ця панцирна рептилія хоробро захищає домівку на своїй спині з незмінно радісною вдачею."},
    [336] = {n="Похмуромісячна кулька", d="Просто пливе собі за вітром..."},
    [337] = {n="Грудко", d="Безквитковий мандрівник із майстерні Діда Зими, цей крихітний елементаль опинився ув'язненим у подарунку, який викрав Бридкий Грінч."},
    [338] = {n="Похмуромісячний танк", d="Улюбленець дітей по всьому Азероту, ця міцна іграшка витримає навіть найбуйнішу уяву."},
    [339] = {n="Похмуромісячний цепелін", d="Без мін і ракет свого попередника цей безпечний для дітей ярмарковий приз став новим улюбленцем серед дітлахів Азероту."},
    [340] = {n="Морський поні", d="Попри свій крихітний розмір, морського поні годі не помітити, коли він прорізає воду."},
    [341] = {n="Місячний ліхтар", d="Ці чарівні ліхтарі добувають на Місячному святі, що відзначає перемогу над Палаючим Легіоном, яку здобули вільні народи Азероту."},
    [342] = {n="Святковий ліхтар", d="Світло кожного ліхтаря вшановує душу духа-предка. Під час Місячного свята ці примарні старійшини передають свою мудрість нинішньому поколінню."},
    [343] = {n="Похмуромісячне левеня", d="Це лагідне кошеня обожнює пустувати, та інколи здається, ніби воно ганяється за тим, чого насправді й немає."},
    [346] = {n="Шаман-фетиш", d="Шамани-фетиші черпають силу з духів полеглих предків. Ці лихі духи прив'язані до племінного списа шамана. Опануй цей спис — і ти опануєш шамана."},
    [347] = {n="Душа Аспектів", d="Подейкують, ніби Душа Аспектів має примхливу вдачу — від стриманої та розважливої до непередбачуваної й мінливої, а то й до ніжної та глибоко задумливої."},
    [348] = {n="Око Легіону", d="Завжди стежить. Завжди судить."},
    [374] = {n="Чорне ягня", d="Нащадок чорної вівці, чорне ягня водиться лише в лісах Елвіну."},
    [378] = {n="Кролик", d="Коли в тебе два кролики, незабаром нерідко стане троє."},
    [379] = {n="Білка", d="Більшість людей не бачать різниці між білкою та бурундуком. Більшості до того й байдуже."},
    [380] = {n="Зубата плавунка", d="Важко сказати, що небезпечніше: зуби чи хвіст."},
    [381] = {n="Їжаченя", d="Попри назву, ти в жодному разі, ніколи й нізащо не повинен його гладити."},
    [382] = {n="Сонячна фея-малятко", d="Цей унікальний вид драконів-фей зазвичай не зустрічається на Азероті."},
    [383] = {n="Вічний бігунець", d="Здається, що це лише обман зору, та вічний бігунець справді вміє ходити по воді, і його маленькі лапки ніколи не порушують її гладінь."},
    [385] = {n="Миша", d="Схоже, миші геть не здатні встояти перед сиром навіть під загрозою полону, каліцтва чи смерті."},
    [386] = {n="Луговий собачка", d="На відміну від своїх деревних родичів, ці земляні білки облаштовують домівки на рівнинах Азерота й поза його межами."},
    [387] = {n="Змія", d="Через нещодавні пригоди гоблінські картелі суворо заборонили будь-кому проносити змій на борт цепеліна."},
    [388] = {n="Береговий краб", d="Ці членистоногі заповнюють чимало берегів Азерота й прагнуть здійснити своє єдине справжнє бажання: ущипнути."},
    [389] = {n="Крихітний жнець", d="Крихітний жнець збирає бур'яни та дрібні зернинки, які могли проґавити більші женці."},
    [391] = {n="Гірський кролик", d="Гірські кролики здатні застрибувати на круті схили з неймовірною швидкістю."},
    [392] = {n="Червоногірський щур", d="Щури у Червоногір'ї добряче гладшають, бенкетуючи на запасах із сільських комор."},
    [393] = {n="Тарган", d="Вони були тут задовго до нас і лишатимуться тут ще довго по тому, як нас не стане."},
    [395] = {n="Канюченя", d="У Червоногірських горах завжди носи шолом. Канюки вважають волосся гуманоїдів чудовим матеріалом для гнізд."},
    [396] = {n="Сутінкове павучатко", d="Родом із Сутінкового лісу, ці восьминогі дрібнюки часто слугують складником алхімічних зілль."},
    [397] = {n="Скунс", d="Скунси відомі як самітники з причин, які, сподіваємося, очевидні."},
    [398] = {n="Чорний щур", d="Хоча багато хто вважає, що чорні коти приносять нещастя, до чорних щурів ставлення краще."},
    [399] = {n="Лазяча змія", d="Багато років тому люди завезли цих плазунів у Сутінковий ліс, щоб приборкати місцеву популяцію щурів."},
    [400] = {n="Павучатко-вдова", d="Павучатка-вдови мають вдосталь часу досліджувати Сутінковий ліс, щойно владнають свої набридливі родинні обов'язки."},
    [401] = {n="Прибережний краб", d="Відплив відкриває колонії прибережних крабів і звук їхнього клацливого танцю, поки вони живляться дрібними створіннями, схованими в піску."},
    [402] = {n="Болотяний метелик", d="Полюбляє селитися у вологих, багнистих місцях і живитися нектаром журбомоху."},
    [403] = {n="Папуга", d="Папуги вміють наслідувати мову, але до змістовної бесіди їм далеко."},
    [404] = {n="Довгохвостий кріт", d="Багато хто вважає, що довгохвостий кріт - лише герой дитячих віршиків, та насправді він цілком справжній."},
    [405] = {n="Деревний пітон", d="Тролі Ґурубаші зі Сплетеного Терня часто ловлять цих могутніх звірів, щоб тримати як улюбленців... або зварити на обід."},
    [406] = {n="Жук", d="Витривала комаха, здатна жити майже в будь-якому кліматі, цей жук добре почувається на полях битв, коли бій уже скінчився."},
    [407] = {n="Лісове павучатко", d="Цей лютий вид плете вигадливе павутиння по всіх густих джунглях Долини Сплетеного Терня."},
    [408] = {n="Ящірка-малятко", d="Якщо самиця ящірки не відкладе свою кладку в добре замаскованому місці, її яйця, найпевніше, пожеруть раптори-батогохвости."},
    [409] = {n="Поллі", d="Папуги просто обожнюють свіжу рибу, якою харчуються тролі Кривавого Скальпу. А ось до черствих коржів вони геть байдужі."},
    [410] = {n="Портовий щур", d="Як і грубі та буйні моряки, що живуть біля доків, портові щури — дикі та люті створіння."},
    [411] = {n="Мавпеня", d="Молоді мавпи швидко вчаться чіплятися ногами за гілки, тож обидві руки лишаються вільними, щоб жбурляти різні предмети в непроханих гостей."},
    [412] = {n="Павук", d="Найпоширеніший представник родини павукоподібних — ці малюки плетуть свої тенета чи не в кожному закутку Азероту."},
    [414] = {n="Скорпід", d="Його отрута здатна вбити істоту, яка важить у сто разів більше за нього самого."},
    [415] = {n="Вогняний жук", d="Вогняного жука вабить жар і запах диму, тож і живиться він попелом."},
    [416] = {n="Скорпіонча", d="Попри клешні, що клацають, і хвіст, з якого скрапує отрута, найбільшу загрозу становить саме укус крихітного скорпіончати."},
    [417] = {n="Пацюк", d="Безстрашний археолог Гаррісон Джонс славиться своїм страхом перед пацюками."},
    [418] = {n="Водяна змія", d="Ці недовговічні плазуни потрапили до Оґриммара на торгових кораблях. Мешканці міста вважають їх справжньою напастю."},
    [419] = {n="Маленька жаба", d="Це маленька жаба."},
    [420] = {n="Ропуха", d="Пісня пізніх літніх ночей — це пісня ропух."},
    [421] = {n="Багряний метелик", d="Полюбляє селитися у вологих тропічних місцинах і живиться нектаром королівської крові."},
    [422] = {n="Мокасинова змія", d="Полюючи або тікаючи від хижаків, ця змія здатна короткими відрізками рухатися поверхнею води."},
    [423] = {n="Лавовий краб", d="Товстий зовнішній панцир цього невибагливого членистоногого дає йому змогу виживати навіть у суворих умовах."},
    [424] = {n="Тарган", d="Для більшості вони лише докука, але неймовірна живучість таргана вирізняє його серед інших видів."},
    [425] = {n="Попеляста гадюка", d="Цей лютий вид змій оселяється довкола вогняних розплавлених ям Палаючого Степу."},
    [427] = {n="Попелясте павученя", d="Тверді, мов камінь, панцири цих павуків дають їм змогу виживати в нестерпній спеці Випаленої Ущелини."},
    [428] = {n="Розплавлене лоша", d="Ці розпечені до жару павуки маскуються, зливаючись із текучою магмою."},
    [429] = {n="Лавовий жук", d="Жуки Палаючого Степу скочують магму в крихітні кульки і поїдають їх, коли ті охолонуть."},
    [430] = {n="Золотий жук", d="Крихітні самостійні машини, створені Титанами, щоб чистити їхні могутні споруди й доглядати за ними."},
    [431] = {n="Гримуча змія", d="Дворфи клану Дикий Молот привчають молодих грифонів до полювання, посилаючи їх ловити гримучих змій у Сутінковому Високогір'ї."},
    [432] = {n="Смугастохвостий скорпід", d="Менш отруйний, але агресивніший за інші види скорпіонів."},
    [433] = {n="Колюча ящірка", d="Забарвлення колючої ящірки дає їй змогу цілком зливатися з пустельними пісками Силітуса."},
    [437] = {n="Маленький чорний баран", d="Ці барани вигострюють бойові навички, буцаючи гілочки й молоді деревця поблизу Лох Модана."},
    [438] = {n="Королівська змія", d="Цю змію часто можна побачити, як вона гріється на сонці на голих скелях високо в Безплідних землях."},
    [439] = {n="Неспокійний сутінник", d="Ці створіння мовчазні, лише зрідка з них виривається зітхання потойбічного відчаю."},
    [440] = {n="Сніжне дитинча", d="Густий сніг біля Дун Мороґу слугує маскуванням для сніжних дитинчат, які вчаться полювати."},
    [441] = {n="Альпійський заєць", d="Альпійський заєць може зариватися у вічну мерзлоту й впадати в сплячку на тижні, а то й місяці."},
    [442] = {n="Опромінений тарган", d="Більшість істот не витримала б і частки тих суворих умов, у яких таргани почуваються чудово."},
    [443] = {n="Луговий кролик", d="Попри ідилічне довкілля, лугові кролики стрибають із дивовижною швидкістю, тікаючи від переслідувачів."},
    [445] = {n="Крихітний вихор", d="Вихори обожнюють підкрадатися до створінь, які нічого не підозрюють, і дивувати їх поривами вітру просто в ніздрі."},
    [446] = {n="Нефритовий слизняк", d="Нефритові слизняки світяться в темряві, тож вони — приємне видовище для робітників у чорних, як смола, шахтах."},
    [447] = {n="Оленятко", d="Зважай на оленячі переходи. Навіть оленятко вщент розіб'є ґоблінський триколісник."},
    [448] = {n="Заєць", d="Морквина, коробка, паличка й трохи мотузки. Зачекай кілька годин — і матимеш зайця."},
    [449] = {n="Бурий бабак", d="На відміну від своїх азеротських родичів, ці звірята з Аутленду живуть у горах Леза Клинка."},
    [450] = {n="Личинка", d="Цьому створінню найбільше до вподоби лісисті місцини, де воно може безпечно завершити своє перетворення."},
    [452] = {n="Червонохвостий бурундук", d="За переказами нічних ельфів, перший червонохвостий бурундук набув такого забарвлення після того, як украв і з'їв священне яблуко."},
    [453] = {n="Заражене ведмежа", d="Заражені ведмежата досі прислухаються до зрадливого дзижчання бджіл, хоча вже й не відчувають смаку меду."},
    [454] = {n="Щур Андерсіті", d="Навіть щури Лордерона стали жертвами чуми аптекарів, гризучи отруєну плоть мертвих."},
    [455] = {n="Чумна білка", d="Мертві білки призвичаїлися до дивних ягід і грибів, що нині ростуть у Срібнолісі."},
    [456] = {n="Чумний яструб", d="Дивно, але цей яструб гострими, мов лезо, кігтями здирає кору з дерев у пошуках комах, хоча зовсім не потребує їжі."},
    [457] = {n="Гнійна личинка", d="Може поглинути втричі більше крові, ніж важить сама."},
    [458] = {n="Загублений з Лордерона", d="Ці маленькі духи вважають своїх сусідів-мерців кепською компанією, тож зазвичай блукають Тірісфальськими галявинами на самоті."},
    [459] = {n="Кіт", d="Після століть приручення ці пухнасті створіння живуть майже в кожному людському краю Східних Королівств."},
    [460] = {n="Рубіновий саджанець", d="Маленькі стихійні саджанці виростають у трентів — лютих захисників лісів і гаїв."},
    [461] = {n="Личинка", d="Цей новоприбулець до Азероту з'явився зовсім нещодавно. Він прагне рости й міцніти, чекаючи на наступний щабель свого розвитку."},
    [463] = {n="Краб-привид", d="Душі вбитих крабів прагнуть помсти мурлокам, які їх з'їли."},
    [464] = {n="Сірий міль", d="Молей легко знайти, якщо вдягти дороге вбрання поблизу Долини Аммен. Вони не можуть встояти перед смаком високої моди."},
    [465] = {n="Спустошувача дитинча", d="Ці ненажерливі хижаки вперше потрапили до Азероту на борту вимірної фортеці дренеїв — Екзодара."},
    [466] = {n="Колюча ящірка", d="Діти Оґриммара часто ловлять цих ящірок собі за улюбленців. А дорослі Оґриммара часто на них наступають."},
    [467] = {n="Гнойовий жук", d="Пустельний збирач, якого вабить туди, де вдосталь гною."},
    [468] = {n="Повзучий жук", d="Ці жуки часто оселяються в каменоломнях, що їх покинула воєнна машина Орди в Дуроталі."},
    [469] = {n="Сутінковий жук", d="Загадковий вид, який, кажуть, живиться хаотичними енергіями Прадавніх Богів."},
    [470] = {n="Сутінковий павук", d="Спотворені темною магією культу Сутінкового Молота, ці зловісні створіння, як відомо, пожирають власне потомство."},
    [471] = {n="Робо-курча", d="Спершу його змайстрував розлючений ґоблін, щоб дратувати сусідів пробудженням на світанку."},
    [472] = {n="Скажений горіхошкідник 5000", d="Більшість вважає його суттєвим поліпшенням порівняно із серією 4000, та все ж лишалися серйозні занепокоєння щодо кількості тепла, яке він виділяє."},
    [473] = {n="Бірюзова черепаха", d="Нага бояться черепах, вважають їх лихим знаком і обходять десятою дорогою на берегах Азшари."},
    [474] = {n="Гепарденя", d="Ці грайливі котячі малята відточують свої мисливські навички, скрадаючись одне за одним Степами."},
    [475] = {n="Жирафеня", d="Дикі кентаври десятиліттями нещадно полювали на жирафів, але саме таурени врятували цей вид від вимирання."},
    [477] = {n="Газеленя", d="Молоді газелі швидко вчаться тікати, зачувши бойові поклики мисливців-тауренів у Малґорі. На жаль, добрих мисливців вони не чують."},
    [478] = {n="Лісовий міль", d="Полюбляє селитися в прохолодних лісистих місцинах і живиться нектаром королівської трави."},
    [479] = {n="Ельфійський кролик", d="Близькість до ельфійської магії наділила декого з них неприродно довгим життям. А з деякими ельфійськими кроликами... траплялися ще дивніші речі."},
    [480] = {n="Топазове сланцеве дитинча", d="Неушкоджений панцир топазового дитинчати високо цінують ювеліри: з нього виходять приголомшливі оздоби для перснів і браслетів."},
    [482] = {n="Скельна гадюка", d="Давним-давно друїди гори Гіджал привчили цей вид мирно жити поруч з іншими істотами краю."},
    [483] = {n="Рогата жаба", d="Багато вчених сперечаються, чи це справді жаба, чи ні."},
    [484] = {n="Пустельний павук", d="Цей хитрий вид риє тунелі під Ульдумом і вихоплюється з-під землі, щоб обплутати свою здобич."},
    [485] = {n="Кам'яний броненосець", d="Коли ці сонливі створіння не дрімають, вони своїми могутніми кігтями викопують смачних комах на перекус."},
    [487] = {n="Альпійський бурундук", d="Не один дослідник був зачарований милою вдачею альпійського бурундука й не помічав його дрібних зубів на своїх відморожених пальцях."},
    [488] = {n="Кораловий змій", d="Відважні вбивці інколи ловлять цих створінь, щоб їхньою вкрай токсичною отрутою отруювати зброю."},
    [489] = {n="Поріддя Оніксії", d="Ці люті вогнедишні драконята втекли з лігва Оніксії й розбіглися по навколишньому краю. Поводься з ними вкрай обережно."},
    [491] = {n="Піщане котеня", d="Виведені колись тролями Піщаної Люті як улюбленці, ці здичавілі та люті коти никають пустелями Танарісу."},
    [492] = {n="Смердючка", d="Пустельна комаха, що боронить свої яйця, розбризкуючи огидний, схожий на огрячий, сморід."},
    [493] = {n="Равлик-мерехтливець", d="Шукає поживу трохи нижче поверхні води на узбережжі Темне Узбережжя."},
    [494] = {n="Дитинча силітида", d="Ці малюки розважаються, клацаючи щелепами у дедалі складніших ритмах."},
    [495] = {n="Жаба", d="На кожну жабу десь чекає свій принц чи принцеса."},
    [496] = {n="Іржавий равлик", d="Хай тебе не вводить в оману те, що в них немає обличчя: ці слизькі створіння злі й тільки й прагнуть бійки."},
    [497] = {n="Опоганений тарган", d="Навіть таргани виявилися недостатньо живучими, щоб устояти перед мерзенним напливом демонічного псування."},
    [498] = {n="Опоганена міль", d="Полюбляє селитися в опоганених лісах і живитися нектаром багряного лотоса."},
    [499] = {n="Опоганений пацюк", d="Є речі, надто брудні навіть для пацюків."},
    [500] = {n="Мінфернал", d="Ці злостиві створіння з вогню й люті часом постають із решток більших інферналів, що полягли в бою."},
    [502] = {n="Плямиста квакша", d="Дворфійська дослідниця, яка першою відкрила плямисту квакшу, не могла вирішити, назвати її за неповторним візерунком плям чи за звуком шлюбного поклику жаби. Вона обрала і те, й інше."},
    [503] = {n="Шовковиста міль", d="Полюбляє селитися в затінку Нордрассілу й живитися нектаром штормолози."},
    [504] = {n="Дитинча диметрадона", d="Диметрадони полишають своїх дитинчат у кратері Ун'Ґоро напризволяще. Виживають лише найсильніші."},
    [505] = {n="Сутінкова ігуана", d="Хоча більшість плазунів любить грітися на сонці, ці лускаті звірі обожнюють купатися в сяйві двох місяців Азерота."},
    [506] = {n="Дитинча отрутоплюя", d="Ці восьминогі створіння тисячоліттями ховаються в тінистих скелях Кам'янокігтистих гір."},
    [507] = {n="Чубата сова", d="Багато сов гніздяться високо в кам'яних спорудах Дарнасуса й полюють на будь-яких шкідників, що проникають до міста нічних ельфів."},
    [508] = {n="Темнобережне ведмежа", d="Хутро темнобережних ведмедів таке темне через майже вічну темряву, в якій вони живуть, а їхній зір у пітьмі надзвичайно гострий."},
    [509] = {n="Крихітна болотяна потвора", d="Ці маленькі елементалі чіпляються до спин більших трясовинних потвор і визбирують там смачних жуків та кліщів."},
    [511] = {n="Рогатий гримучник", d="Родом із пустельних країв Азероту, ці витривалі плазуни здатні тижнями виживати без жодної краплі води."},
    [512] = {n="Дитинча скарабея", d="Нащадки лиховісних скарабеїв-верескунів Ан'Кіражу, ці малята набагато сумирніші (й тихіші) за своїх батьків."},
    [513] = {n="Малий вартовий Кіраджі", d="Писк, який видають ці крихітні комахоподібні, може здаватися милим, та насправді вони верещать, прагнучи твоєї смерті."},
    [514] = {n="Малий білувальник", d="Один зухвалий орк Скверни колись намагався поневолити цих створінь як своїх особистих воїнів. Шматки його досі розкидані по всьому Аутленду."},
    [515] = {n="Паросток спорлінга", d="Ці пухкенькі малі створіння часто наражаються на халепу, шукаючи свій улюблений харч: світлошапки."},
    [517] = {n="Дитинча сферного мисливця", d="Щойно вилупившись, ці покручені плазуни пожирають слабших побратимів зі своєї кладки на знак панування."},
    [518] = {n="Молодий ратокопит", d="Для оґрів порівняти волосся жінки з кошлатою шерстю ратокопита — велика похвала."},
    [519] = {n="Полум'я Скверни", d="Народжені з демонічної магії, ці примхливі маленькі сутності опоганюють усе, чого торкаються, мерзенними енергіями."},
    [521] = {n="Молодий нетерський скат", d="Дорослі нетерські скати доволі сумирні, проте їхні малята — нетерплячі й надзвичайно енергійні звірята."},
    [523] = {n="Ненажерливий черв'як", d="Завивний фіорд вирує невпинно мінливим колообігом життя. Коли істота гине, її тіло швидко поглинають черви, а ті, своєю чергою, передають поживні речовини низці інших створінь."},
    [525] = {n="Індик", d="Одне з головних джерел їжі під час Свята Зимового Серпанку."},
    [528] = {n="Обпечене мале базиліска", d="Цей буркотливий вид базилісків блукає Горами Грані Клинка, уникаючи зустрічей з іншими дрібними створіннями, коли тільки можна."},
    [529] = {n="Фіордове воргеня", d="Є давня врайкульська приказка: «Не чіпай ворга, що спить, якщо тобі ще потрібне твоє обличчя.»"},
    [530] = {n="Маслянистий слизнюк", d="Цим живим грудкам слизу бракує навіть найпростішого розуму, та це не означає, що вони не можуть стати тобі другом."},
    [532] = {n="Низькорослий Скалкоріг", d="Люті вольвари полюють на цих злостивих почвар заради їхніх рогів, з яких потім вирізають талісмани та інші дрібнички."},
    [534] = {n="Пташеня імператорського орла", d="Таунка збирають пір'я цих шляхетних хижих птахів, щоб використовувати його в нехитрих обрядах ворожіння."},
    [535] = {n="Водяна хвилька", d="Тролі Зул'Драка ненавмисно створили цих маленьких істот, коли прикликали водяних елементалів для боротьби з Погибеллю."},
    [536] = {n="Тундровий пінгвін", d="Тундрові пінгвіни часто збираються великими зграями на кризі, щоб захиститися від загроз із води. На жаль, це робить їх легкою здобиччю для гуманоїдних мисливців, які шукають м'ясо, шкури та інші досягнення."},
    [537] = {n="Мале драконокості", d="Ці потайливі дрібні створіння вилуплюються в гніздах, збудованих навколо прадавніх драконячих кісток у центральному Нортренді."},
    [538] = {n="Уражене дракончатко", d="Колись Кел'Тузад виплекав до дорослого віку дракончика, зараженого чумою, годуючи його лише найдобірнішими розрідженими рештками."},
    [539] = {n="Гротова нориця", d="Гротових нориць часто плутають із мишами. Але ніколи двічі."},
    [540] = {n="Стерв'ятний пацюк", d="Там, де є стерво, завжди знайдуться й пацюки."},
    [541] = {n="Вогнетривкий тарган", d="Зовнішня оболонка тарганячих яєць захищає личинку від спопеління. Саме під час цього визрівання вони здобувають здатність опиратися вогню й жару вулканічного клімату."},
    [542] = {n="Мак-Жаба", d="Барвистіша й жвавіша за більшість жаб."},
    [543] = {n="Сарана", d="Коли сарана збивається в рій, не чути нічого, окрім шуму її крил."},
    [544] = {n="Оазисний метелик", d="Воліє селитися вздовж пустельних струмків, колодязів чи водопоїв і живиться нектаром батогохвоста."},
    [545] = {n="Леопардовий скорпід", d="Полюбляє вночі влаштовуватися на спочинок усередині взуття необачних мандрівників."},
    [546] = {n="Скарабей Тол'віру", d="Падложери, яких часто знаходять у великій кількості в стародавніх розкопаних гробницях; вони здатні довго виживати без їжі."},
    [547] = {n="Блукавець Нордрассілу", d="Під час Третьої війни тисячі цих містичних істот знищили володаря демонів Архімонда."},
    [548] = {n="Мале грифона Дикого Молота", d="Надто боїться навіть спробувати злетіти, доки його не скинуть з великої висоти."},
    [549] = {n="Жовточеревий бабак", d="На відміну від своїх рівнинних родичів, ці створіння живуть посеред розтерзаного війною Сутінкового нагір'я."},
    [550] = {n="Високогірна миша", d="Миші нагір'я, можливо, спотворені культом Сутінкового Молота, агресивні й б'ються між собою за панування."},
    [552] = {n="Сутінкове бісеня", d="Доводячи, що навіть дрібка зла багато на що здатна, це бісеня пускає в хід гострі як бритва зуби та роззявлену пащу, аби пожерти все, що трапиться на його шляху."},
    [553] = {n="Пацюк-безбілетник", d="У скрутні часи, коли тебе носило морем без жодного орієнтиру, поява пацюка була доброю звісткою."},
    [554] = {n="Мале багряного сланцю", d="Дослідами маги Даларану з'ясували, що подрібнені рештки павука з багряного сланцю значно посилюють спалах їхніх вогняних заклять."},
    [555] = {n="Тарган Глибокотверді", d="Таргани Глибокотверді здатні вгризатися в саму скелю, щоб облаштувати там свої гнізда."},
    [556] = {n="Кристалічний жук", d="Родич Сутінкового жука, ця комаха навчилася живитися кристалами, що бринять прадавніми енергіями."},
    [557] = {n="Феєричний дракон Нижнього світу", d="Як і інші феєричні дракони, ці грайливі та містичні літуни народжуються з природним захистом від магії."},
    [558] = {n="Арктичне лисеня", d="Морозними ночами на Штормових вершинах ці звірята вкриваються своїми пухнастими хвостами, наче ковдрою, щоб зігрітися."},
    [559] = {n="Багряна геода", d="Теразана носила цих завзятих багряних елементалів як прикраси, перш ніж Глибокотвердь захопила мода на блакить."},
    [560] = {n="Чайка", d="Чайка — прибережна падложерка, яку часто можна побачити поблизу пристані."},
    [562] = {n="Коралова гадюка", d="Отрута коралової гадюки настільки смертоносна, що, як подейкують, одного укусу досить, аби вбити дорослого кодо."},
    [564] = {n="Смарагдова черепаха", d="Важко повірити, що Шен-цзінь Су, на чийому панцирі спочиває весь Мандрівний острів, починав життя крихітною смарагдовою черепахою."},
    [565] = {n="Джунглева стрілка", d="У джунглях за кожним листком може ховатися жаба. Спинишся перевірити — а її вже й слід прохолов."},
    [566] = {n="Дзеркальний бігунець", d="Готуючись до подорожі в далекі краї, пандарени за традицією ловлять дзеркального бігунця і безпечно переселяють його до іншої водойми."},
    [567] = {n="Храмова змія", d="Пандарени Нефритового лісу вважають цих плазунів далекими родичами шанованого Нефритового Змія, Ю'лона."},
    [568] = {n="Шовкоперлинний слимак", d="Ховається у мушлю, щоб уникнути клешень сусідніх крабів."},
    [569] = {n="Садова жаба", d="Одна з найдивніших напастей для садівників: садові жаби здатні завдати рослинам неймовірної шкоди."},
    [570] = {n="Тануке в масці", d="Точиться запекла суперечка про те, ким є тануке — єнотами чи собаками, та різниця здається дрібницею, коли вони гризуть твою стегнову кістку."},
    [571] = {n="Гаєва гадюка", d="Гірські гозени Нефритового лісу бояться цих отруйних плазунів і нерідко полюють на них з чистої злості."},
    [572] = {n="Краб шпилів", d="Ці крихітні членистоногі — корінні мешканці Пандарії, що звуть домівкою околиці Безвітряного острова."},
    [573] = {n="Піщаний буревісник", d="Піщаний буревісник ширяє високо над Безвітряним островом, у безпеці від наземних хижаків."},
    [626] = {n="Кажан", d="Ця зловісна істота никає нічним небом Східних Чумних земель і живиться падлом."},
    [627] = {n="Заражена білка", d="Ще страшніше за їхній вигляд те, що заражені білки Чумних земель більше не запасають горіхи, а збирають гниле, розкладене м'ясо."},
    [628] = {n="Заражене оленятко", d="Лише недоумок чи божевільний повісив би голову зараженого оленя собі на стіну. Втішає те, що вона якраз пасуватиме до його нових мертвих друзів."},
    [629] = {n="Береговий повзун", d="Цю чарівну морську істоту можна зустріти лише на берегах Кезана, і вона буває трохи дошкульною."},
    [630] = {n="Ґілнеаський крук", d="Прорік крук: останнє слово, яке ти сказав. І так без кінця."},
    [631] = {n="Смарагдовий удав", d="На цього велично гарного змія полюють заради його шкіри з чудовим візерунком. Він добре почувається на буйних зелених берегах річок Азероту."},
    [632] = {n="Попеляста ящірка", d="Свою назву попеляста ящірка дістала через те, що її скинута шкіра скидається на обгорілі жарини."},
    [633] = {n="Гірський скунс", d="Гірський скунс найбільше відомий своєю любов'ю до пригод. Ні, справді, саме цим він і відомий."},
    [634] = {n="Кришталевий павук", d="Ці дивні створіння мерехтять, наче лід, і завдяки цьому ховаються серед засніжених просторів Вінтерспрінга."},
    [635] = {n="Гадюка", d="На відміну від інших змій, що активно полюють, ці хитрі плазуни ховаються в густому листі й чатують на здобич із засідки."},
    [637] = {n="Метушливий печерний плазун", d="Ці павукоподібні гострими, мов лезо, лапами прокладають тунелі в твердій породі Гострих гір."},
    [638] = {n="Нетерський тарган", d="Нетерський тарган пристосувався до холодної космічної порожнечі й не потребує повітря, щоб вижити. Усередині він майже нічим не нагадує звичайного таргана."},
    [639] = {n="Бореанський бабак", d="На відміну від родичів із тепліших країв, ці витривалі звірята оселяються в крижаних пустищах Нортренду."},
    [640] = {n="Заєць-біляк", d="Завдяки надзвичайно широким лапам зайці-біляки легко скачуть по снігу, тоді як їхні переслідувачі грузнуть у заметах."},
    [641] = {n="Арктичний заєць", d="Серце арктичного зайця б'ється вдвічі швидше, ніж у звичайного."},
    [644] = {n="Фіордовий пацюк", d="Якби фіордовий пацюк не був такий схильний до прикрих пригод, він міг би підкорити світ."},
    [645] = {n="Високогірний індик", d="Здатний літати, на відміну від свійських порід."},
    [646] = {n="Курка", d="Намагається не переходити дороги, хай би які були на те причини."},
    [647] = {n="Сива білка", d="У глибокому лісі навіть дрібним створінням потрібна лють, щоб постояти за себе."},
    [648] = {n="Величезна ропуха", d="Це величезна ропуха."},
    [649] = {n="Жовчна жаба", d="Подейкують, що чутки про цілющі властивості жовчної жаби пустив якийсь надто пустотливий аптекар."},
    [650] = {n="Жахливий буряк", d="А ти ще думав, що буряк на вечерю — це жахливо."},
    [652] = {n="Крихітна золота рибка", d="Ця бульбашка набагато гірша за акваріум."},
    [665] = {n="Піщаний скарабей", d="Його легко сплутати зі звичайним жуком, та укус піщаного скарабея швидко розвіє цю оману, якщо тобі не пощастить його дістати."},
    [666] = {n="Мікронакс", d="Щоразу, коли його війська зазнавали поразок на Азероті, Кіл'джеден діставав Мікронакса й тероризував місцевих котоподібних мешканців Аргуса, щоб зігнати злість."},
    [671] = {n="Щасливе квіленя", d="Нащадок імператорського квілена."},
    [675] = {n="Стормвіндський пацюк", d="Цього не помітив ніхто, окрім котів і щуроловів, та коли Дезвінг обрушився на Стормвінд, усі пацюки квапливо втекли з міста. Лише нещодавно вони повернулися."},
    [677] = {n="Сором'язливий бандикун", d="Один гоблін-алхімік якось заявив, що укус цього єнота дав йому дар пророцтва. Виявилося, що то був лише сказ."},
    [678] = {n="Джунглева личинка", d="Ці маленькі зелені личинки родом із нетрів Пандарії. Соковито-зелений колір ховає їх від можливих хижаків."},
    [679] = {n="Гірське козеня", d="Їх часто можна побачити високо на неймовірно стрімких і відлюдних скельних виступах. Мало хто може похвалитися такою впевненою ходою."},
    [680] = {n="Куйтанський мангуст", d="Мангуста цінують за вміння відганяти отруйних змій. Рікк-тікк-тіккі-тіккі-чк!"},
    [699] = {n="Павук-стрибун", d="Цей жахливий і вкрай отруйний вид зістрибує на свою здобич із густих крон Нефритового лісу."},
    [702] = {n="Леопардова деревна жаба", d="Леопардова деревна жаба дістала свою назву за те, як вона стрибає з гілки на гілку."},
    [703] = {n="Маскове танученя", d="Багато юних єнотів повстають проти суворого режиму, нарікаючи, що світанок — надто рання пора, щоб лягати спати."},
    [706] = {n="Бандикун", d="Раціон мовчазного бандикуна складається переважно з яблук."},
    [707] = {n="Мале бандикуна", d="Дехто з друїдів каже, що пандарени та єноти — далекі родичі, але ніколи не тоді, коли поряд є пандарен, який це почує."},
    [708] = {n="Малайський голкопацюк", d="Багато хто вірить, що голкопацюк здатен стріляти своїми голками в напасників."},
    [709] = {n="Малайське щуреня-голкохвіст", d="Хоч рани від молодого голкопацюка рідко бувають смертельними, більшість хижаків шукає легшу здобич."},
    [710] = {n="Болотяний скрипаль", d="Відомий тим, що залюбки ласує смачними рослинами Долини Чотирьох Вітрів."},
    [711] = {n="Сіфанзька видра", d="Сіфанзька видра живе поблизу річок і зазвичай привітна та грайлива."},
    [712] = {n="Видреня сіфанґ", d="Видри плавають, відштовхуючись потужним хвостом і вигинаючи своє довге тіло. У воді дуже швидкі."},
    [713] = {n="Мала м'якопанцирна кусачка", d="М'ясо м'якопанцирної черепахи вважається делікатесом і є головним складником ніжного черепахового супу."},
    [714] = {n="Гарячкокусе маля", d="Поширений народний засіб від укусу гарячкокусого пташеняти — несамовито танцювати, намагаючись випотіти токсини, перш ніж вони почнуть діяти."},
    [716] = {n="Аметистове павученя", d="Рідкість серед павукоподібних: ці неотруйні створіння харчуються виключно рослинами та плодами."},
    [717] = {n="Смаковитий жук", d="Найсмачніший із усієї жучиної родини."},
    [718] = {n="Метелик луюй", d="Зухвала, марнославна комаха, готова кинути виклик будь-якій небезпеці заради того, щоб опинитися в центрі уваги."},
    [722] = {n="Іскрик Мей Лі", d="Подорослішавши, живиться дрібним листям і травою."},
    [723] = {n="Колюча водяна черепаха", d="Розлючена колюча водяна черепаха ховається у свій панцир і починає несамовито крутитися, насуваючись на нападника."},
    [724] = {n="Альпійське лисеня", d="Глибоко заривається у снігові замети, щоб сховатися від хижаків."},
    [725] = {n="Альпійське лисенятко", d="Іноді поцуплює шматочки їжі зі здобичі значно більших звірів."},
    [726] = {n="Степовий варан", d="Завмерши на місці, степовий варан безперервно поводить хвостом туди-сюди. Здалеку це нагадує колихання високої трави й маскує ящірку від хижаків, що нападають з повітря."},
    [727] = {n="Степова миша", d="У степу безліч гризунів та інших дрібних створінь, але немає поширенішого за мишу."},
    [728] = {n="Курка по-сичуанськи", d="Несе яйця лише при яскравому світлі."},
    [729] = {n="Заєць толай", d="У давніх переказах оповідають, що перший заєць толай скакав через безодню поміж зорями, аж доки не сполохав їх, і вони посипалися з небес на світ унизу."},
    [730] = {n="Зайченя толай", d="Зайченят толай ще змалечку виганяють із нори, щоб вони самі знаходили свій шлях."},
    [731] = {n="Змія Зої", d="Ці плазуни мають загнуті луски, завдяки яким видираються кам'янистими схилами та стрімкими урвищами вершини Кун-Лай."},
    [732] = {n="Бурштиновий метелик", d="Ця комаха буяє в сезон дощів, і її вабить до грозових бур."},
    [733] = {n="Луговий стрибунець", d="Уночі лугові стрибунці сповнюють пітьму своєю нестерпною піснею. Ті, хто до неї не звик, не одну безсонну ніч провели під їхні шлюбні поклики."},
    [737] = {n="Мангуст", d="Попри безневинний вигляд, мангусти — небезпечні хижаки, відомі вмінням полювати на отруйних змій, здатних убити куди більших створінь."},
    [739] = {n="Мангустеня", d="Мангустенята полюбляють високу траву, де їх можуть відшукати лише їхні матері."},
    [740] = {n="Яко-щур", d="Зв'язок між яком і щуром доволі дивний, і що саме щур має з цього симбіозу — справжня загадка."},
    [741] = {n="Тихий їжак", d="Ці їжаки, може, й тихі, але часто чути зойки тих, хто необачно наступив на їхні голки."},
    [742] = {n="Туманний їжак", d="Їжаки геть не охочі ні до крокету, ні до фламінго."},
    [743] = {n="Равлик рапана", d="Помічено, як він б'ється з іншими равликами за добрі джерела харчу."},
    [744] = {n="Витривалий тарган", d="Таргани Моторошних Пустищ живуть у тінях. Дехто божиться, що тіні мандрують разом із ними."},
    [745] = {n="Хрусткий скорпіон", d="Майстри прикрас цінують його унікальний панцир за текстуру і міцність."},
    [746] = {n="Краб-імператор", d="Краба-імператора назвали за величний вигляд: гребені його панцира і піднесені клешні моторошно нагадують корону. Таку, що видряпала б тобі очі, якби ти спробував її надіти."},
    [747] = {n="Іскриста світлянка", d="Її осяйне тіло вабить пару."},
    [748] = {n="Позолочений метелик", d="Тендітні крила цієї комахи часто вшивають в одяг і обладунки."},
    [749] = {n="Золота цивета", d="Цивети — суходільні родичі видри, яких цінують за п'янкий мускус."},
    [750] = {n="Золоте циветеня", d="Відомо, що цивети люто оберігають своє потомство."},
    [751] = {n="Танцівлива водомірка", d="Названа так за те, що, ковзаючи водною гладдю, наче танцює. Цей вид рухається уривчасто й непередбачувано, щоб не стати здобиччю риб та інших підводних хижаків."},
    [752] = {n="Жовточерева жаба-бик", d="Попри грізний вигляд, жовточерева жаба-бик отримала влучне ім'я."},
    [753] = {n="Садовий метелик", d="Ця комаха буяє в дощову пору, і її вабить до себе гроза."},
    [754] = {n="Храмова муха", d="Цей вид комах вабить прихована енергія храмів, а їхнє сяйво лиш додає таємничості цим місцям сили."},
    [755] = {n="Тарган-мертвоголов", d="Візерунок на панцирі цього таргана дуже схожий на череп."},
    [756] = {n="Грибний метелик", d="Полюбляє селитися в темних печерах і живитися нектаром серцецвіту."},
    [757] = {n="Крихітний зелений дракон", d="Легенди кажуть, що ці яскраві смарагдові створіння приносять своїм власникам удачу й безпечні мандри."},
    [758] = {n="Крихітний червоний дракон", d="Кажуть, що побачити його восени — на щастя. Відомо, що він ховається від незнайомих створінь."},
    [792] = {n="Нефритове журавлятко", d="Граційне створіння з острова Пандарія."},
    [802] = {n="Громове змієня", d="Маленька версія могутнього громового хмарного змія, що походить із далеких земель Пандарії."},
    [817] = {n="Дике нефритове змієня", d="Таке миле — і водночас таке епічне."},
    [818] = {n="Дике золоте змієня", d="Нащадок Цулона, схований ще до того, як скверна ша остаточно охопила Терасу Нескінченної Весни."},
    [819] = {n="Дике багряне змієня", d="Воно червоне, тож має літати швидше."},
    [820] = {n="Співучий цвіркун", d="Відомий тим, що ласує смачними рослинами в Нетрях Красаранґу."},
    [821] = {n="Дикий вермлінг", d="Воно весь час на мене дивиться. Гадаю, воно хоче мене вкусити."},
    [823] = {n="Високогірний скунс", d="Цей лютий скунс може обприскати нападника за тридцять метрів, тимчасово засліпивши його. Поводься обережно!"},
    [834] = {n="Дробильник", d="Чаклуни могу, охоронці таємниці оживлення каменю, віддають перевагу цим незворушним супутникам перед звірянішими помічниками."},
    [835] = {n="Стрибунець", d="Великий широкий світ може бути небезпечним місцем для такого крихітного, чарівного створіння."},
    [836] = {n="Водяний бігун", d="Водяні бігуни відіграють важливу роль у культурі джинью: вони слугують їздовою твариною, засобом передавання послань і навіть домашнім улюбленцем родини."},
    [837] = {n="Мале смарагдового сланцю", d="Шукачі пригод повідомляють про рідкісні зустрічі з велетенським смарагдовим сланцевим павуком, якого мешканці Глибокого Дому прозвали Нефритоіклом."},
    [838] = {n="Аметистове сланцеве дитинча", d="Дорослі аметистові сланцеві павуки воліють влаштовувати свої гнізда під зовнішніми стінами Глибокого Дому."},
    [844] = {n="Механічний пандаренський драконик", d="Зібраний із, здавалося б, неможливої купи шестерень, пружин, дротів і дрібки чогось особливого, цей драконик утілює дух Пандарії, побачений крізь окуляри інженера."},
    [845] = {n="Нефритова сова", d="Нефрит від природи сповнений життя й кольору, що робить його ідеальним матеріалом для цього лагідного супутника. Кажуть, що вітер, здійнятий її крилами, здатен заспокоїти стривожений розум."},
    [846] = {n="Сапфірове дитинча", d="Хоча кожне дитинча створене однаково, крихітні вади самоцвітів дарують йому неповторну вдачу, щойно його сповнюють життям. Утім, усі вони завжди грайливі й привітні."},
    [847] = {n="Рибка", d="Багато хто помилково вважає, що золоті рибки нічого не пам'ятають. Дресирувальники, які з ними працювали, добре знають, що це зовсім не так, і мають синці на доказ."},
    [848] = {n="Похмуромісячний кролик", d="Цей кролик набагато сильніший, ніж здається."},
    [849] = {n="Повітряний змій Чі-Цзі", d="Прекрасний повітряний змій, оживлений писарями Пандарії."},
    [850] = {n="Повітряний змій Юй'лон", d="Хто б міг подумати, що писарі вміють робити повітряних зміїв?"},
    [851] = {n="Рогата ящірка", d="Вона не лише прудка, а ще й гучна!"},
    [855] = {n="Венера", d="Дивно, що вона не любить мух... чи не так?"},
    [856] = {n="Нефритове щупальце", d="Обережно, іноді воно стає трохи пустотливим!"},
    [868] = {n="Пандаренський водяний дух", d="Водяні духи особливо пустотливі й полюбляють вчащати до каналів Броварні Штормстаут."},
    [903] = {n="Чумоплід", d="Цей вибуховий член рою Зергів, що котиться вперед, завдає жахливої, просто жахливої шкоди. Дуже небезпечний у ближньому бою."},
    [1013] = {n="Маля з Мандрівного фестивалю", d="Легенда каже, що морська драконоподібна черепаха, точнісінько як ця, виросла й стала Шен-зін Су, Мандрівним Островом. Можливо, твоя маленька черепашка теж виросте в щось дивовижне?"},
    [1039] = {n="Імператорський метелик", d="Личинка цього метелика відома на весь світ тим, що створює найтоншу шовкову нитку в усьому Азероті."},
    [1040] = {n="Імператорський шовкопряд", d="Ця пухкенька червона гусениця відома на весь світ тим, що створює найтоншу шовкову нитку в усьому Азероті."},
    [1042] = {n="Червоний цвіркун", d="Будь обережний, бо він може з'їсти весь твій урожай!"},
    [1061] = {n="Маля Місячної Брами", d="Більшість численних малят лісового ходака Віолетти стають ярмарковими стравами завдяки Стампу Тандергорну, та кількох вирощують як їздових тварин або купують шукачі пригод, що прагнуть маленького фіолетового улюбленця."},
    [1062] = {n="Світлячок Місячної Брами", d="Подеколи можна побачити, як їхнє моторошне зелене світло, що нагадує полум'я Скверни, миготить поміж викривлених дерев острова Місячної Брами."},
    [1063] = {n="Око Місячної Брами", d="Навіть не думай зараз шахраювати."},
    [1068] = {n="Ворон", d="Хоч вони й менші за сумнозвісних воронів Ґілнеасу, ці ворони не менш кмітливі та хитрі."},
    [1073] = {n="Теркі", d="Теркі настільки сором'язлива, наскільки й чарівна, тож воліє товариство близьких друзів, а не нових знайомих."},
    [1117] = {n="Жаринкове кошеня", d="Грайливий муркотливий піроман. Не гладь цих кошенят без вогнетривких рукавичок!"},
    [1124] = {n="Пандаренський дух вогню", d="Хоч він і скидається на далекого родича Жаринкового кошеняти, насправді ці дві істоти не мають спільних предків."},
    [1125] = {n="Пандаренський дух повітря", d="Ці духи втілюють саме серце елементальних сил Пандарії."},
    [1126] = {n="Пандаренський дух землі", d="Стихії Пандарії бувають милі та грайливі — аж доки їхній рідній землі не загрожує небезпека."},
    [1127] = {n="Примарне дитинча", d="Завдяки своїй примарній природі вміщується навіть у найменшу коробку."},
    [1128] = {n="Болотяний гризун", d="Гризун звичайного розміру."},
    [1142] = {n="Бойова машина", d="Створена з однією-єдиною метою: лупцювати дрібних звіряток так сильно, як тільки зможе."},
    [1143] = {n="Велетенський кістяний павук", d="Знайдені в запорошеній кладці яєць у глибині лігва Мексни, ці створіння вже народжуються неживими."},
    [1144] = {n="Грибна потвора", d="Тіло Лоатеба вкрите дрібними капсулами, здатними за сприятливого вітру розносити гнилісні грибні спори на відстань до 1000 ярдів."},
    [1145] = {n="Містер Біґґлзворт", d="Покинувши крижаний некрополь Наксрамас, Містер Біґґлзворт миттю знайшов тепле місце під сонцем, щоб гарненько подрімати."},
    [1146] = {n="Зшите цуценя", d="Коли Ґлют загинув від рук гурту хоробрих шукачів пригод, цих малюків знайшли в трупі — вони гризли велетенські неживі кістки."},
    [1147] = {n="Передвісник Полум'я", d="Небагато цих вогняних передвісників лишилося після поразки Рагнароса у Вогняних Землях."},
    [1149] = {n="Біс ядрового вогню", d="Ці крихітні вогняні біси сновигають Розплавленим Ядром великими роями і здатні стрімко поповнювати свою чисельність."},
    [1150] = {n="Попелясте кам'яне ядро", d="Охололе ядро Ґолемаґа, яке, схоже, зберегло дещицю свідомості."},
    [1151] = {n="Неприборкане драконятко", d="Одне з яєць Рейзорґора, що дивом уціліло в Лігві Чорного Крила."},
    [1152] = {n="Хромініус", d="Супротивникам, що стають перед цією лютою хроматичною потворою, лишається тільки сподіватися, що вона не володіє Зупинкою часу!"},
    [1153] = {n="Вартовий драконят Смертельного Кігтя", d="Найслабший серед Чорного Кігтя, лишений стерегти драконят."},
    [1154] = {n="Кулька Вісцидуса", d="Ця маленька кулька не встигла повернутися до Вісцидуса вчасно, щоб знову зростися воєдино."},
    [1155] = {n="Ідол Анубісатів", d="Анубісатський ідол із Храму Ан'Кіраж, просякнутий прадавньою магією кіражі."},
    [1156] = {n="Міні-душогуб розуму", d="Згуба багатьох шукачів пригод: зазирнути йому в очі — означає спізнати справжнє безумство."},
    [1157] = {n="Юна гарпія", d="З роками вони стають лише вродливішими."},
    [1158] = {n="Низькорослий єті", d="Роками на нього полювали місцеві, тож це надзвичайно рідкісний екземпляр."},
    [1159] = {n="Високий том", d="Більшість людей ніколи не читали цієї книги."},
    [1160] = {n="Магічне око", d="Ніколи не спускай з нього очей."},
    [1161] = {n="Драконя нескінченності", d="Можеш не сумніватися: воно достеменно знає, котра година."},
    [1162] = {n="Флюксвогняний котик", d="Спершу його створили інженери в надрах Гномреґана, і флюксвогняний котик став справжнім дивом сучасної інженерії."},
    [1163] = {n="Анодоване рободитинча", d="Інженери-чарівники з Еверлука створили це унікальне дитинча як випробний зразок. На жаль, кілька з них вийшли з-під контролю, і їх так і не вдалося повернути."},
    [1164] = {n="Зубчастий раптор", d="Цю модель рапторів виготовляють у Горах Лезогостря. Їхнє механічне ревіння часто чути неподалік Станції Тошлі."},
    [1165] = {n="Драконя Нексуса", d="Найслабші з виводку Малігоса, ці драконята цінуються за свою безмежну арканну магію."},
    [1166] = {n="Недоросток Кун-Лай", d="Цей рідкісний єті, що мешкає на вершинах Піку Кун-Лай, набагато небезпечніший, ніж здається."},
    [1167] = {n="Смарагдове протодраконя", d="Цих прекрасних драконів можна зустріти на всьому узбережжі Нортренду."},
    [1168] = {n="Муркі", d="Муркі належить до одного з найрідкісніших видів мурлоків у світі."},
    [1174] = {n="Поривчастий гримуар", d="Споганений Скверною фоліант, чиї таємниці настільки жахливі й химерні, що його сторінки набули моторошної подоби життя. Лежить на нічному столику не в одного чорнокнижника."},
    [1175] = {n="Громохвостий плескач", d="Торкнуті блискавкою, ці небезпечні гризуни вимагають триматися від них на безпечній відстані."},
    [1176] = {n="Червона панда", d="Уявляєш, який я милий? Я й сам не вірю."},
    [1177] = {n="Живий піщаник", d="Народжені з піску, ці небезпечні створіння можуть зібратися й розсіятися за одну мить."},
    [1178] = {n="Мікровартовий Сонцехапів", d="Віддані Сонцехапам від самого створення, ці крихітні конструкти все одно можуть добряче дати відсіч."},
    [1179] = {n="Наелектризований лезозуб", d="Видно, як його тілом тече блискавка, від зубів до хвоста."},
    [1180] = {n="Колінокус Зандаларі", d="Цей унікальний раптор народився на острові Зандалар і був перевезений сюди разом із рештою війська Зандаларі."},
    [1181] = {n="Старий пітон", d="Подейкують, що ці змії здатні проковтнути гнома одним ковтком."},
    [1182] = {n="Болотяний квакун", d="Мабуть, краще його не чіпати."},
    [1183] = {n="Син Анімуса", d="Викувані в Троні Грому, ці крихітні творіння служать великому Темному Анімусу."},
    [1184] = {n="Недорослий жахоріг", d="Навіть за такого крихітного розміру жахороги відомі тим, що сіють хаос серед жертв, які нічого не підозрюють."},
    [1185] = {n="Примарне дикображеня", d="Щось у цьому створінні видається знайомим..."},
    [1196] = {n="Сонцехутра панда", d="Ці пухнасті бешкетники полюбляють грітися на сонці, спати на сонці й дрімати на сонці."},
    [1197] = {n="Снігова панда", d="Біле хутро снігової панди дозволяє їй ховатися в заметах вершини Кун-Лай."},
    [1198] = {n="Гірська панда", d="Двоюрідні до снігових панд, гірські панди мешкають у нижчих краях вершини Кун-Лай."},
    [1200] = {n="Карликовий жахоріг", d="Не гладь гострий кінець. Зауваж: усі кінці тут гострі."},
    [1201] = {n="Поріддя Ґ'натуса", d="Дехто з пандаренів вважає, що Ґ'натус — це древній зандаларський лоа, якого лишили стерегти води на південь від острівної цитаделі Лей Шеня."},
    [1202] = {n="Пташеня Джі-Куна", d="Смертоносні нащадки Прадавньої Матері, пташенята Джі-Куна в багатьох культурах вважаються священними скарбами."},
    [1204] = {n="П'єр", d="Мрія кожного кухаря, дбайливо загорнута в досконале плетиво з металу та болтів. Шкода лише, що його страви не годяться для споживання гуманоїдами. Якщо вірити нотаткам Джарда, він задумав змайструвати цього малого для своєї подруги, Емілі Коул."},
    [1205] = {n="Жахоріг-заморок", d="Зандалари навмисне розводять окремі породи жахорогів за дрібний зріст, щоб використовувати їх як їздових тварин."},
    [1206] = {n="Крихітний червоний короп", d="Вважають, що червона луска цих риб попереджає хижаків Степу Танлонг і Жаских Пустищ про отруйність їхнього м'яса. Завзятим рибалкам інколи щастить заприятелювати з однією з них."},
    [1207] = {n="Крихітний синій короп", d="Цих малят можна зустріти у водах Позачасового острова або поряд із самоцвітними даніо та червоночеревими мандаринками. Завзятим рибалкам інколи щастить заприятелювати з однією з них."},
    [1208] = {n="Крихітний зелений короп", d="Вважають, що зелений колір і смуги крихітного зеленого коропа правлять за маскування у водах Нефритового лісу, Долини Чотирьох Вітрів та Красарангських нетрів. Завзятим рибалкам інколи щастить заприятелювати з однією з них."},
    [1209] = {n="Крихітний білий короп", d="Ці витривалі риби виживають у найрізноманітніших кліматах — від засніжених вершин Кун-Лай до помірних солоних вод океанів довкола Пандарії. Завзятим рибалкам інколи щастить заприятелювати з однією з них."},
    [1211] = {n="Кісткогриз Зандаларі", d="Ці крихітні служники Зандалару майстерно ховаються в трюмах велетенських зандаларських військових кораблів."},
    [1212] = {n="Стоподряпник Зандаларі", d="Навіть за такого розміру ці раптори здатні випатрати цілу корову менш ніж за десять секунд."},
    [1213] = {n="Нігтегриз Зандаларі", d="Ці чарівні створіння так і просяться в обійми — за умови, що ти не дуже дорожиш своїм обличчям."},
    [1226] = {n="Лихий вовчик", d="Часто забуте дитинча Великого Лихого Вовка, знайдене наїдженим і сонним у кошику зі солодощами."},
    [1227] = {n="Доглядач звіринцю", d="До головних обов'язків належить витирання пилу з численних магічних артефактів Медіва — заняття, що коштувало життя, розуму чи й тілесної цілості багатьом доглядачам, які служили до Мороуза."},
    [1228] = {n="Безодник Нетерпростору", d="Покинувши Нетерпростір, безодники Малкезаара дивно спотворюються магічним захистом Каражана, який робить їх крихітними та значно менш схильними раптово спалахувати полум'ям."},
    [1229] = {n="Лютий біс", d="Поплічник Терестіана Іллгуфа, цей хитрий біс лишився в Каражані, коли портал до Викривленого Нетеру зачинився за ним."},
    [1230] = {n="Хвилескок", d="Дивовижна знахідка для наукової спільноти Азероту, що довго розмірковувала, нерідко в корчмах, який же на вигляд малюк морського велетня."},
    [1231] = {n="Опоганений хвилько", d="Поріддя Гідроса, якого спільнота елементалів називає «Графом Калюж»."},
    [1232] = {n="Переслідувач Зміїних Кілець", d="Невідомо, як леді Вашж наділяє цих болотоходів силою, що дурманить розум; навіть у ранньому віці ця істота виявляє неабиякі психічні здібності."},
    [1233] = {n="Кишеньковий руйнівник", d="Посланий крізь Викривлений Нетер самим великим Архімондом Осквернителем, щоб тероризувати крихітні цивілізації своїм середнього розміру тупотінням."},
    [1234] = {n="Малий призивач Порожнечі", d="Ліхтарі, які носять призивачі Порожнечі, з'єднують світи живих і мертвих та часто приваблюють заблукалих привидів і духів."},
    [1235] = {n="Маля фенікс-яструба", d="Ці яскраво забарвлені драконояструби стрімко й безпомильно несуть сили Кель'таса крізь нетерну бурю, що оточує Око."},
    [1236] = {n="Тіто", d="Хоч він загалом і майстер коритися режисерським вказівкам, виставу не раз доводилося зупиняти, коли погляди Тіто й Рева зустрічалися, і це закінчувалося тривалою гонитвою по всьому Оперному театрі Каражана."},
    [1237] = {n="Ґаз'рукі", d="Тролі мають довгу й славну історію прикликання гідр. Хай Ґаз'рукі не найбільша і не найсильніша гідра, вона добряче вкусить тебе за пальці, якщо підійдеш надто близько."},
    [1238] = {n="Ненароджена валькіра", d="Валькіри вважаються «ненародженими», доки не здолають істоту високого роду."},
    [1243] = {n="Жива рідина", d="Темні озерця в палаті Прімордіуса застоялися після падіння могу, і в них почали зароджуватися каламутні думки."},
    [1244] = {n="В'язкий жах", d="Ці злостиві слизі надзвичайно чутливі до феромонної мітки Прімордіуса."},
    [1245] = {n="Бруднюк", d="Тренерам бойових улюбленців наполегливо радимо мити руки щонайменше 30 хвилин після гри з бруднюком."},
    [1248] = {n="Квітучий древній", d="Цей бруньковий древній — унікальний різновид в Азероті, створений із вічноживих гілок Великого Дерева, і здатний цвісти будь-якої пори року."},
    [1255] = {n="Зерадар", d="Зерадар — горезвісний псіонічний таран протосів і єдиний архонт, здатний прикликати псіонічний шторм. Нездоланна міць!"},
    [1256] = {n="Шибеник-бот", d="Цей малий, схоже, полюбляє вештатися на краєчку катаклізмічних подій. Утім, немає жодних доказів, що він причетний до їхньої появи, — найпевніше, він просто спостерігач. А може, він просто часто губиться дорогою до інших місць."},
    [1266] = {n="Сю-Фу, дитинча Сюеня", d="Лютий і відданий Сю-Фу обожнює полювати при місячному світлі. Якось у повний місяць він убив і з'їв цілого великого залізошкірого бугая, після чого проспав два дні поспіль."},
    [1276] = {n="Місяць-Місяць", d="Дитинчата Місяцезуба виростають у велетенських, слинявих, чорнохутрих машин для вбивства... усі, крім Місяця-Місяця."},
    [1303] = {n="Чі-Чі, пташеня Чі-Джі", d="Чі-Чі намагається вселяти надію своїм гучним криком, а ще тим, що ганяється за метеликами і зрештою їх поїдає."},
    [1304] = {n="Ю'ла, малятко Ю'лон", d="Майстриня-скульпторка присвятила життя створенню незрівнянно прекрасної статуї, натхненна любов'ю та шаною до Ю'лон. Коли скульпторка померла, Ю'лон вдихнула в статую частку своєї сутності й привела Ю'лу у світ."},
    [1305] = {n="Зао, телятко Ніудзао", d="Завжди напоготові до бійки чи до смачної трави, Зао тримає голову схиленою, а погляд — спрямованим уперед."},
    [1320] = {n="Малий Блінґ", d="Цей вродливий маленький робот — викапаний «татусь», Блінґтрон 4000. Оскільки схеми щедрості Блінґтрона дозрівають лише тоді, коли його зібрано за максимальними характеристиками, не варто чекати від нього безкоштовних подарунків."},
    [1321] = {n="Лазурове журавленя", d="Журавлята з Позачасового острова часом співають дивовижну пісню, що заспокоює нерви й тішить душу."},
    [1322] = {n="Бомбочка Чорнопалів", d="Це була перша бомбочка, створена в Підземній Твердині, і облоговий інженер Чорнопал не міг дивитися, як її знищують. Тож лишив її собі як дружнього, хоч і вибухонебезпечного, улюбленця."},
    [1323] = {n="Попелолистий духик", d="Попелолисті духи з Позачасового острова невтомно захищають рослинність острова від палючої люті Ордоса та його поплічників."},
    [1324] = {n="Попелокрилий метелик", d="Убивці-джінью використовують цього метелика і як переносну принаду, і як джерело світла, щоб виявити слабкі місця в обладунках своїх ворогів."},
    [1325] = {n="Полум'яний метелик", d="Коти та інші допитливі створіння часто затівають із цим метеликом коротку гру, що закінчується мордочкою в обсмаленій шерсті."},
    [1326] = {n="Небосяйний метелик", d="Цього цікавого метелика часом помічають за тим, як він перебиває закляття мандрівного мага чи чорнокнижника."},
    [1328] = {n="Рубінова краплина", d="Води Рубінового озера забарвлені в дивний червонуватий відтінок — мабуть, через рубінові кристали, що залягають глибоко в горах Позачасового острова."},
    [1329] = {n="Кульбабовий пустун", d="Хоч пустун і зачарований квітами, відомо, що він танцює і зі стеблинками трави, а часом і з бур'янами."},
    [1330] = {n="Маля смертоносної гадюки", d="На схилі життя, якщо умови довкілля сприятливі, смертоносна гадюка може скинути шкіру й перетворитися на імперського пітона."},
    [1331] = {n="Краплина Й'Шаараджа", d="Невеликий залишок сили Й'Шаараджа, що породив ша. Одна-єдина краплина Й'Шаараджа здатна підсилювати емоційні стани на тисячі метрів довкола, через що цілі містечка завмирають у страху чи сумнівах."},
    [1332] = {n="Слизьке маля Ша", d="Малята ша віддзеркалюють емоційний стан свого господаря, стаючи збудженими, пригніченими, наляканими чи охопленими сумнівом — залежно від сили негативних думок навколо них."},
    [1333] = {n="Танцюрист Нефритового туману", d="Танцюристів Нефритового туману з Позачасового острова дивовижним чином ваблять парові отвори на північно-західному узбережжі."},
    [1334] = {n="Ковок", d="Дрібний жах Жахітних пустищ, Ковок понад усе любить «їжу для мозку»: мозок мушанів, мозок людей, ну й узагалі будь-який мозок. Можливо, ця дивна харчова потреба якось пов'язана з його величезною головою."},
    [1335] = {n="Лиховісне полум'я", d="Дивні блакитні вогні, що трапляються в Печері Загублених Духів, привели до загибелі чимало необачних шукачів пригод."},
    [1336] = {n="Смердючий пивляр", d="Коли багато поколінь тому село Пі'джу зазнало нападу яунголів Ордону, відважні селяни поставили барило посеред села. Наступного ранку, коли гуляння вщухло, досі п'яні яунголи туманно погодилися підписати мирну угоду."},
    [1337] = {n="Колючоклешній краб", d="Колючоклешні краби Пандарії існують уже тисячі років і лишаються одними з найдавніших створінь континенту."},
    [1338] = {n="Жабеня-ковтач", d="Жаби-ковтачі з Позачасового острова можуть поласувати здобиччю, що в кілька разів більша за них самих, поволі перетравлюючи жертву ззовні отруйним слизом."},
    [1343] = {n="Шаленець", d="Деяких юних і норовливих гозенів змалку привчають носити боксерські рукавиці, щоб вони ненароком не повбивали одноплемінників, а ще важливіше — щоб не колупалися в носі."},
    [1344] = {n="Мстиве дикобразеня", d="Одне зі створінь, що лишилися на Позачасовому острові, коли той зсунувся крізь час, — найпевніше принесене Ордоном у жертву їхньому напівбогу Ордосу."},
    [1345] = {n="Роєня Ґу'чі", d="Роєнята Ґу'чі плетуть давню й дуже міцну шовкову нитку, якої в Пандарії не бачили вже цілі віки."},
    [1346] = {n="Гармонійне дикобразеня", d="Тривале перебування серед умиротворених туманів Шаохао заспокоїло цих духів, і тепер вони стали мирними супутниками туманоткачів."},
    [1348] = {n="Дух Нефритового вогню", d="Уважають, що Дух Нефритового вогню — це живе втілення нефритового подиху самої Ю'лон."},
    [1349] = {n="Гнилий маленький помічник", d="Виснажені довгими годинами праці, мізерною платнею та зухвалими шукачами пригод, що скиглили про нікудишні дарунки Свята Зимового Серпанку, ці капосні дрібні створіння втекли зі своїх чарівних майстерень, щоб приєднатися до Жахливого Гринча."},
    [1350] = {n="Небесний ліхтар", d="Свічка всередині повітряного змія нагріває повітря, і той здіймається вгору без жодного вітру."},
    [1351] = {n="Моторошна маріонетка", d="Цим одержимим лялькам дарують подобу життя примхливі духи померлих."},
    [1363] = {n="Альтеракське пивеня", d="Цей мастиф виведений для порятунку, і рід альтеракських пивенят уславився тим, що знаходив і повертав до життя багатьох мандрівників, які застрягли під снігом у горах... а потім обслинював їх із голови до ніг."},
    [1364] = {n="Муркалот", d="Ми хрестоносці з казки старої. Танцюємо всі разом, як рій. Виходимо в номерах і піснях, з бездоганним кроком на сценах!"},
    [1365] = {n="Скарбовий гоблін", d="Пильнуй свого гаманця."},
    [1384] = {n="Гоґс", d="Завзятий і жахливий, могутній Гоґс без вагань винищує слабших ворогів."},
    [1385] = {n="Біле химереня", d="Обидві голови жахливої химери однаково грізні, і кожна здатна на свою унікальну атаку диханням."},
    [1386] = {n="Маля жаху", d="Темні крила затьмарять і поглинуть розум слабких, бо вони ж такі чарівні!"},
    [1387] = {n="Залізна зірочка", d="Цю величезну зброю знищення зменшили для роботи в саду. Стережіться, кроти!"},
    [1394] = {n="Гидотка", d="Зроблена зі шматочків переможених бойових улюбленців, темної магії і дрібки любові."},
    [1395] = {n="Малі Недоїдки", d="Милі, хоч до столу подавай, але краще не варто."},
    [1396] = {n="Скажена морква", d="Полишена сама на себе, морква просто божеволіє."},
    [1403] = {n="Механічний сокирокдзьоб", d="Скрііііііііп!"},
    [1411] = {n="Королівське павеня", d="Одну павичеву пір'їну часто кладуть на могилу, щоб відігнати злих духів."},
    [1412] = {n="Реалістичний механічний морозний вепр", d="Після численних скарг на те, що приручення молодих вепрів буває вкрай болісним досвідом, на допомогу прийшли інженери з цією моторошно реалістичною моделлю."},
    [1416] = {n="Пташеня терокігтя", d="Терокіготь — вправний мисливець на все дрібне й пухнасте."},
    [1426] = {n="Плюшевий елекк", d="Цей чарівний маленький слоник завжди поруч із тобою."},
    [1427] = {n="Морозохутрий пацюк", d="Набридливі й шкодочинні, та коли вдосталь сиру, їх можна задобрити й перетворити на цілком стерпного супутника."},
    [1428] = {n="Зомстрок", d="Зомстрок — це зло у плоті, нечестива помилка того, кого самотність звела з розуму, витвір, який уже не виправити."},
    [1429] = {n="Осінній паросток", d="Від насінини до квітки виростає крихітний жах."},
    [1430] = {n="Лісовий паросток", d="Від насінини до квітки виростає крихітний жах."},
    [1432] = {n="Беладонний паросток", d="Від насінини до квітки виростає крихітний жах."},
    [1434] = {n="Сонячний паросток", d="Від насінини до квітки виростає крихітний жах."},
    [1435] = {n="Шкірянношкірий замориш", d="Багато років тому один оґр спробував використати шкірянношкірого замориша як м'яч для копання. Відтоді його назавжди прозвали Одноногом."},
    [1441] = {n="Грязьовий стрибунець", d="В оркських дітей є традиція: підкрастися до грязьового стрибунця і пошепки звірити йому заповітне бажання. Якщо стрибунець не стрибне, бажання здійсниться."},
    [1442] = {n="Примарне козеня", d="У найвищому прояві впертості ця колись жива коза просто відмовилася помирати."},
    [1446] = {n="Лучний топтун-теля", d="Кмітливість і дбайлива вдача телят елекків роблять їх вірними супутниками на все життя."},
    [1447] = {n="Місяцепанцерний краб", d="Місяцепанцерний краб відбиває світло так добре, що його можна взяти в руку й користуватися ним як дзеркалом. Тільки не підставляй обличчя до клешень!"},
    [1448] = {n="Морське теля", d="Морське теля від природи схильне балансувати різні речі."},
    [1449] = {n="Дитинча смертостража", d="Це дитинча має незвичайне чуття, яке дозволяє йому виявляти альфа-хижаків і триматися поряд із ними."},
    [1450] = {n="Мікрозахисник дренеїв", d="Хоч цих крихітних механічних охоронців і створили, щоб захищати свійських елекків від шкідників, вони також виявилися напрочуд вправними в масажі спини."},
    [1451] = {n="Розплавлений коргі", d="Обожнює пасти бісенят, качатися в лаві та тулитися до повелителів стихій."},
    [1453] = {n="Річкове теля", d="Напрочуд прудке, коли його роздратувати, але легко вгамовується трапезою з награндської стрілоцвітки."},
    [1454] = {n="Муркідан", d="Поласувавши гомілковою кісткою Ґул'дана, цей завзятий мисливець на демонів був ув'язнений на 10000 років своїм братом Муркфуріоном."},
    [1455] = {n="Мохокусий метушник", d="Замаскований під мох, метушник ховається на деревах і стрибає на своїх жертв згори."},
    [1456] = {n="Чагарниковий метушник", d="Оманливо милий вигляд приваблює здобич, а тоді зустрічає її шквалом нищівних ударів. Обіймати з обережністю."},
    [1457] = {n="Льодошипий вилупок", d="Озброєні надзвичайно гострими пазурами, ці крижані малята прориваються крізь товсті шари льоду й каменю, шукаючи прихистку."},
    [1458] = {n="Кістяна оса", d="В одному з ритуалів оґри затискають кістяну осу в долонях і несамовито трясуть нею. Її отрута додає сили та викликає яскраві видіння."},
    [1462] = {n="Кровожальна оса", d="Усупереч поширеній думці, кровожальні оси живляться не кров'ю, а любов'ю."},
    [1463] = {n="Лісова оса", d="Лісові оси мостять гнізда в мертвих чи дуплистих деревах і миттю нападають на все, що загрожує їхній домівці."},
    [1464] = {n="Сутінкова оса", d="У місячному світлі її крила випромінюють мерехтливе сяйво, що навіює оману мерехтіння зірок."},
    [1465] = {n="Бурштинокола оса", d="Бурштиноколі оси часто дражнять більших створінь, аби ті напали. Щойно жертва вдарить їх, у відповідь налітає цілий рій."},
    [1466] = {n="Яснолапка", d="У цього чарівного кошеняти стільки енергії, що воно інколи гасає навколо без жодної причини."},
    [1467] = {n="Небо-Бо", d="Небо-Бо спершу створила сумнозвісна Міллі Ватт як іграшку для своєї кішки. А кішка просто спала в коробці поряд із нею."},
    [1468] = {n="Кривавий дзьоб", d="Давні племена Дренора, як відомо, добували їхні гострі дзьоби для грубих знарядь і зброї."},
    [1469] = {n="Джунгледзьоб", d="Барвисте пір'я цих птахів дуже цінують колекціонери. Подейкують, що той, хто носить ці пера, матиме удачу."},
    [1470] = {n="Пташеня сокироклюва", d="Краї його дзьоба особливо гострі. Бережи пальці, коли годуєш!"},
    [1471] = {n="Мисливець за фруктами", d="Цей полохливий птах має ненаситний апетит до фруктів."},
    [1478] = {n="Сід Кальмар", d="Цей крихітний кальмар, схоже, полюбляє носити штани, та де ж у світі знайти такі, щоб йому підійшли?"},
    [1495] = {n="Пожирач руди", d="Вони їдять, їдять і їдять, доки не виростуть великими. А тоді їдять іще."},
    [1511] = {n="Пташеня-нерозлучник", d="Звісно, що є пташенята, адже вони звуться нерозлучниками, хіба ні?"},
    [1514] = {n="Містичний весняний букет", d="Оживлений магічними засобами та хлорофілом."},
    [1515] = {n="Каменедробар", d="Майстерно виготовлений набір шестерень і точні з'єднання цього робота вочевидь зроблені з любов'ю."},
    [1516] = {n="Чагарникова курка", d="Відколи ґобліни завезли їх на материк, чагарникові курки стали головною стравою свята Дарів Прочанина завдяки своїй неабиякій смакоті й кволому розуму."},
    [1517] = {n="Палаючий Жаролаз", d="Дно його клітки встелене крихітними обвугленими тільцями різних комах."},
    [1518] = {n="Міцний Елементаль елю", d="Пандаренські майстри броварства випадково прихопили на Свято броварів діжку останньої свідомої партії пива від дядечка Ґао."},
    [1521] = {n="Проклята бірманська кішка", d="Одне з дев'яти життів цієї кішки повернулося, щоб переслідувати живих, голосно нявкаючи, коли ти намагаєшся заснути."},
    [1523] = {n="Віджет Спочилий", d="Навіть смерть не спинила невгамовну цікавість цього кошеняти."},
    [1524] = {n="Поріддя Пустоти, поріддя Поріддя Пустоти", d="Цей слиз має довгий і заплутаний родовід."},
    [1530] = {n="Цуценя-привид Морозного Вовка", d="Вовченяті веліли чекати на місці.\nВоно вдивлялось, виглядаючи здобич.\nЗанадто горде, щоб піти, воно тихо згасло.\nТепер вільне від тягаря, навіки вільне для гри."},
    [1531] = {n="Стародавній охоронець гнізда", d="Стародавнього охоронця гнізда створили з немислимою метою: ненавидіти котів."},
    [1532] = {n="Іккі", d="Малі каліри змалечку живляться личинками, а згодом переходять на все, що менше за них самих."},
    [1533] = {n="Виплодок лантикора", d="Ніхто не знає, у якій глибокій частині Сходження Чорнокрила тримали лантикора, але смерділо там, напевно, доволі гидко."},
    [1536] = {n="Зангарська спора", d="На Дренорі Зангарське море прагне поглинути сушу, випускаючи тисячі цих спор і поволі розростаючись углиб материка."},
    [1537] = {n="Багряна спора", d="Спора, зірвана в Багряних Драговинах — частині Горгронду, яку поглинуло, коли Дренор розірвало магією Нижнього Світу."},
    [1538] = {n="Умбрафенська спора", d="Темно-синє Умбрафенне згодом стане домівкою для племені Зламаних."},
    [1539] = {n="Морська спора", d="Спора із Зангарри — центральної ділянки зангарського наступу, що пізніше розквітне в Зангарські Драговини."},
    [1540] = {n="Сяйлива спора", d="Сяйливі спори трапляються вкрай рідко: їх знаходять глибоко під хвилями Дренора, у найтемніших закутках зангарського грибкового наступу."},
    [1541] = {n="Гідреня", d="Гідреня може стати дорогим улюбленцем, адже здатне їсти одразу з трьох мисок."},
    [1542] = {n="Морозововче щеня", d="Поки ці щенята не виростуть, вони — клубки хутра й зубів, а коли підростуть, лишаються самі зуби."},
    [1543] = {n="Карликова корова", d="Виведена спершу для того, щоб зробити молоко смачнішим для гномів."},
    [1544] = {n="Ненавистоіскра Крихітний", d="Його ненависть не меншає від розміру."},
    [1545] = {n="Вогнекрил", d="Не вистеляй її клітку папером, якщо не хочеш пожежі."},
    [1546] = {n="Грозокрил", d="Наполовину птах, наполовину елементаль — прекрасний Грозокрил здатний наганяти справжній жах і трепет."},
    [1563] = {n="Бронзове драконятко", d="Бронзове драконятко було загублене у часі, доки незвичайна подія не дала йому змогу втекти."},
    [1564] = {n="Цвіт загибелі", d="Наочний доказ того, чому ґоблінські добрива слід застосовувати ощадливо."},
    [1565] = {n="Механічний скорпід", d="Залізо, залізо, сталь і вогонь. Міхи, шестерні, пластини й дроти."},
    [1566] = {n="Павеня Вічноцвіту", d="Ці крихітні створіння, схоже, полюбляють великі пухнасті гнізда, найкраще — на голові дріади, що любить тварин."},
    [1567] = {n="Супутник вартової", d="Супутник вартової з нічних ельфів, який дуже рідко дарують стороннім."},
    [1568] = {n="Жах калюж", d="Живучи так близько до водної гладі, жах калюж не лише товаришує з усіма водяними створіннями — він і сам є одним із них."},
    [1569] = {n="Душа кузні", d="Коли кують зачаровану сталь, краплини магії просочуються у вугілля. За роки, а то й десятиліття, незв'язана енергія поволі набуває форми, породжуючи крихітну елементальну істоту неймовірної стійкості."},
    [1570] = {n="Сонцевогняний каліри", d="Легенда розповідає, що сонцевогняний каліри злітає просто в сонце, коли готовий померти."},
    [1571] = {n="Альбіносне річкове теля", d="Їхня біла шкіра робила б їх беззахисними перед сонячними опіками, якби не була така товста, мов латна броня."},
    [1572] = {n="Сяйливий кривавопер", d="Кривавопер геть безстрашний: він розпускає пір'я й кидається на будь-яку загрозу."},
    [1573] = {n="Золоте Світанкове Перо", d="Кажуть, його пір'я виблискує, наче золото, коли на нього падає проміння вранішнього сонця."},
    [1574] = {n="Син Сете", d="Богоподібна істота, тепер у зручному дорожньому розмірі."},
    [1575] = {n="Небесна мушка", d="Гратися в «принеси» зі скатом завжди весело. Навіть цілитися не треба."},
    [1576] = {n="Око спостереження", d="Тобі завжди здаватиметься, що... щось за тобою стежить."},
    [1577] = {n="Кривавотерникове маля", d="Спустошувачі — улюблений перекус оґрів, поки малі й не такі смертоносні."},
    [1578] = {n="Морознопанцирний клішняк", d="Морознопанцирні клішняки нарощують шари льоду, щоб дістати додатковий захист від більших хижаків."},
    [1579] = {n="Залізнокіготний шкряботун", d="З клешнями, що здатні розчавити латну рукавицю, поводитися з ним краще обережно."},
    [1581] = {n="Багновий краб", d="Ці хитрі ракоподібні зариваються в багно, щоб їх не вихопили більші хижаки."},
    [1582] = {n="Зангарський плазун", d="Вони живляться багатими на поживні речовини грибними спорами, що й надає панцирам цих крабів характерного забарвлення."},
    [1583] = {n="Водоростяний шкряботун", d="Вони вкривають себе водоростями та іншою морською зеленню, щоб здобути перевагу над своєю здобиччю."},
    [1586] = {n="Лазурова нічниця", d="Тендітна й небезпечна, осяйна й смілива — краса, дорожча за золото."},
    [1587] = {n="Королівська нічниця", d="Їхні темно-фіолетові крила дуже цінують оґри-маги, вірячи, що додані до зілля, вони здатні подовжувати життя."},
    [1588] = {n="Запорошений споропер", d="У небезпеці їхні крила випускають дрібний порошок — захисний механізм."},
    [1589] = {n="Багрянокрила нічниця", d="Тендітна й небезпечна, осяйна й смілива — краса, дорожча за золото. Шкода лише, що така легка."},
    [1590] = {n="Болотяний світлячок", d="Учені довго сперечалися, чому світлячки світяться, та провідна гіпотеза — «магія»."},
    [1591] = {n="Фіолетовий світлячок", d="Ці світлячки зберігають своє фіолетове сяйво, бо живляться самими лиш фіолетовими квітами та нектаром."},
    [1592] = {n="Сапфіровий світлячок", d="Його називають «летючим самоцвітом» за блиск, схожий на сяйво найкращих сапфірів."},
    [1593] = {n="Водомушка", d="Водомушка відбиває світло свого черевця від поверхні води, щоб приваблювати пару."},
    [1594] = {n="Багноспинне теля", d="Напрочуд прудке, коли його роздратувати, та легко заспокоюється стравою зі стрілоцвіту Награнду."},
    [1595] = {n="Плоскозубе теля", d="Напрочуд прудке, коли його роздратувати, та легко заспокоюється стравою зі стрілоцвіту Награнду."},
    [1596] = {n="Пташеня вартового завіси", d="Винищене майже до останку заради пір'я, це каліри розвинуло гострі чуття."},
    [1597] = {n="Пташеня каліри", d="Винищені майже до останку заради пір'я, каліри розвинули гострі чуття."},
    [1598] = {n="Сяйливий спорокажан", d="Дикі спорокажани — лютий народ, але приручені змалку, вони стають вірними супутниками."},
    [1599] = {n="Тіньовий спорокажан", d="Дикі спорокажани — лютий народ, але приручені змалку, вони стають вірними супутниками."},
    [1600] = {n="Кістяний змій", d="Молоді кістяні змії намагаються пролізти в череп живої істоти й зжерти її мозок. Тож, мабуть, варто вдягати нічний ковпак."},
    [1601] = {n="Слуга Демідоса", d="Демідос створив безліч слуг, коли влаштовував учти для інших володарів Порожнечі."},
    [1602] = {n="Ґроммлок", d="Хай би як він кричав, ніколи не давай йому демонічної крові."},
    [1603] = {n="Арґі", d="Кози, яких часто ловили на тому, що жують усе, що не варто, спершу звинуватили в аварії «Екзодара»."},
    [1604] = {n="Світло Нетаери", d="Загублене магічне світло мага з Даларану чи розумна свічка з добрим норовом? Вирішувати тобі."},
    [1605] = {n="Хоботок", d="Магічний друг, створений з рівних часток жаги пригод і запалу."},
    [1615] = {n="Висохла ящірка", d="Вона не лише прудка, а ще й гучна!"},
    [1622] = {n="Ґротеск", d="Менша горгулія, яку ставлять на будівлях Погибелі, щоб відводити дощову воду й не дати затопити мавзолеї."},
    [1623] = {n="Левіафанове дитинча", d="Темно-зелена вода в каналізації Чорного Храму надає цим гідрам їхнього прикметного кольору."},
    [1624] = {n="Абіссій", d="Уламок великого абісаля Супремуса, Абіссій містить досить вогняної есенції, щоб пропалити дірку в твоїй кишені."},
    [1625] = {n="Фрагмент гніву", d="Він просто трішки сердитий."},
    [1626] = {n="Фрагмент страждання", d="Він лише ледь роздратований."},
    [1627] = {n="Фрагмент жадання", d="Він лише трохи зацікавлений."},
    [1628] = {n="Сестра спокуси", d="Це той чортик на твоєму плечі, що нашіптує тобі на вухо."},
    [1629] = {n="Смердогнилець", d="Що це за запах?"},
    [1631] = {n="Вогник Гіджалу", d="Сотні таких вогників зібралися разом, щоб захистити Гіджал від Архімонда і врятувати світ."},
    [1632] = {n="Мікрозахисник Сонячного Клинка", d="Бо ти не хочеш знати, що станеться, коли пацюк забреде в Сонячний Колодязь."},
    [1633] = {n="Цуценя хаосу", d="Викривлена Порожнеча — це безмежна безодня жахів і один маленький закуток неймовірної милоти."},
    [1634] = {n="Нікчемний слуга", d="Залежних від магії ельфів, надто малих і кволих, щоб служити в армії Кіль'Джедена, відрядили слугувати демонам вищого рангу."},
    [1635] = {n="К'ют", d="Коли цей улюбленець поруч, твій розум сповнюють заспокійливі передзвони, що нагадують про давно минулі часи."},
    [1636] = {n="Гоночний міні-цепелін", d="Одна з найдошкульніших перешкод Перегонів Новолуння — тепер у тебе на долоні!"},
    [1639] = {n="Могили", d="Якось під час вторгнення в Примарні Копальні загін героїв спромігся зібрати лише один-єдиний череп. Голем, що з нього постав, був надто малий, щоб завдати шкоди ворожим вежам, тож подався блукати Нексусом і зрештою знайшов шлях до Азероту."},
    [1655] = {n="Молода ковзкоблискавкова мурена", d="Річки Дренору кишать муренами. Це люті хижаки, що нападають на все, що заходить у воду."},
    [1656] = {n="Молодий талбук", d="Талбуки відрощують роги до повного розміру ще змалку."},
    [1660] = {n="Сквернове цуценя", d="Поки ці цуценята ростуть, вони — клубки хутра й зубів. А коли виростають, від них лишаються самі зуби."},
    [1661] = {n="Загублене Порожнечне щеня", d="Подейкують, що деякі звірі, торкнуті Порожнечею, існують у просторі між цим світом і наступним."},
    [1662] = {n="Жаринове щеня", d="Це щеня, знайдене за обгризанням почорнілої кістки в Чорній Кузні Ливарні Блекрок, навдивовижу швидко до тебе звикає."},
    [1663] = {n="Барвінкове телятко", d="Ці пустотливі маленькі річкові звірята обожнюють набрати повний рот води й бризнути нею одне в одного."},
    [1664] = {n="Кошмарний дзвін", d="Колись цей священний артефакт жерці-дренеї використовували, щоб заспокоювати духів, та нині його заполонили змучені душі, і його вабить до місць смерті й зіпсуття."},
    [1665] = {n="Краб-привид", d="Ці краби розвинули досконалу форму маскування, через яку їхній панцир здається прозорим."},
    [1666] = {n="Блорп", d="Ця риба, схоже, геть не реагує на твої команди — та, власне, навіть не помічає, що ти поруч."},
    [1672] = {n="Зіпсований страж гнізда", d="Різниця між зіпсованим стражем гнізда та кухарем, що смажить омлет, насправді дуже невелика."},
    [1687] = {n="Ліва акула", d="Хто б покинув таку миловидну акулу? У Залізної Орди й справді немає душі."},
    [1688] = {n="Трощій", d="Цей загублений ґорен, знайдений за блуканням у невеликій сніговій бурі, носить із собою шахтарську кирку, аби показати, що він майстер на всі руки."},
    [1690] = {n="Уламок Цирукха", d="Дрібка Цирукха вічно палає в цьому шматку Шифру. Краще тримай його при собі."},
    [1691] = {n="Покусень", d="Цей юний переслідувач легко вирвався з лабет Саргераса за жменьку магічних мініласощів."},
    [1692] = {n="Дике тигреня", d="Улюбленці часто дуже схожі на своїх господарів, і це особливо помітно, коли господар — саберон."},
    [1693] = {n="Палаючий вогнесокіл", d="Поклоніння аракоа сонцю породило кількох дивних і страхітливих слуг."},
    [1699] = {n="Зачарований казан", d="Відьма Стрега зачарувала свій казан, щоб той не перекидався й не розливав гарячу юшку. Вона й гадки не мала, що казан набуде свідомості й спробує її вбити."},
    [1700] = {n="Зачарований смолоскип", d="Відьма Стрега не любила носити смолоскипи сама. Одне швидке закляття — і смолоскип слухняно йшов за нею в ніч."},
    [1701] = {n="Зачароване перо", d="Відьма Стрега, втомившись писати подячні листи, скористалася магією, щоб упорати цю справу автоматично. На жаль, перо мало темний бік, тож усі адресати отримали листи з вельми різкими словами…"},
    [1705] = {n="Буркотун", d="Ти врятував його, та, може, це він урятував тебе."},
    [1706] = {n="Попелясте пащеня", d="У цього малюка був нелегкий початок життя, тож неодмінно подбай про нього як слід."},
    [1708] = {n="Пташеня альбатроса", d="Багато моряків вірять, що скривдити альбатроса означає накликати страшну біду на всю подорож."},
    [1709] = {n="Пташеня королепера", d="Хоча інші види птахів по черзі ведуть зграю під час перельоту, королепер завжди лишається попереду. Чи робить він це, щоб допомогти решті зграї берегти сили, чи задля переваги — досі невідомо."},
    [1710] = {n="Пташеня оливкоспина", d="Завжди в тіні свого брата."},
    [1711] = {n="Пташеня небоканії", d="Дуже рідкісний птах, але цього довірили саме тобі."},
    [1712] = {n="Золоте орля", d="Ці птахи часто полюють на черепах, скидаючи їх з великої висоти, щоб розбити панцир."},
    [1713] = {n="Вухата сова", d="Зір у неї кращий, ніж слух."},
    [1714] = {n="Північна яструбина сова", d="Її гострі очі вирізнять зайця-біляка навіть у заметіль."},
    [1715] = {n="Нічний пікірувальник", d="Ці створіння можуть полювати майже в повній темряві."},
    [1716] = {n="Совеня-вартовий", d="Юний супутник, якому потрібне навчання."},
    [1717] = {n="Згасле око", d="Той, хто колись був грізним ворогом, тепер чарівний друг!"},
    [1718] = {n="Ненависне око", d="На що це ТИ дивишся?!"},
    [1719] = {n="Око інквізиції", d="Агов. Це мене ти шукаєш?"},
    [1720] = {n="Еммігоза", d="Пра-пра-пра-пра-праправнучка Сенеґоса."},
    [1721] = {n="Штормороджене дракончатко", d="Його луска наелектризована, тож пригортати його — справа вкрай ризикована."},
    [1722] = {n="Дракончатко Сну", d="Прекрасний мрійнику, прокинься для мене, зоряне сяйво й роса вже чекають на тебе."},
    [1723] = {n="Дитинча кошмару", d="Що таке дрібка псування між друзями?"},
    [1725] = {n="Бурчун", d="Бурчуни народжуються, коли сльози викраденої дитини падають на купку свіжого снігу."},
    [1726] = {n="Норне павученя", d="Передні лапи цього павука майже незнищенні, тож він може вгризатися чи не в будь-яку поверхню."},
    [1727] = {n="Гніздовий павук", d="Чому його звуть гніздовим павуком? Невже він любить ховатися в гніздах? А навіщо йому це? Що він там робить? Ой лишенько! Хай хтось перевірить діток!"},
    [1728] = {n="Молодий повзоспин", d="«Молодий» вказує на вік цього повзоспина, а не на його зрілість."},
    [1729] = {n="Оливохвостий заєць", d="«Оливохвостий» — назва трохи оманлива, адже все його тіло просто буре..."},
    [1730] = {n="Примарний прядильник", d="Ніби шахти, повної звичайних, не примарних павуків, було ще замало, щоб налякати."},
    [1731] = {n="Павук Скверни", d="Точнісінько як звичайний павук, тільки сповнений Скверни."},
    [1734] = {n="Мерехтлива водомушка", d="Вряди-годи світлячки узгоджують своє мерехтіння, даруючи неймовірне видовище шукачеві пригод, якому пощастило застати це явище."},
    [1735] = {n="Личинка жаху", d="Личинка жаху шукає жертву, щоб живитися її снами та страхами. Невдовзі вона виросте в найгірші страхи своєї жертви."},
    [1736] = {n="Слизький бурочешуйчастий", d="Ці змії — на диво сумирні створіння. Проте вони так добре зливаються з довкіллям, що чимало шукачів пригод підходять надто близько до їхніх гнізд. Більшість укусів стається через цілком уникні випадковості."},
    [1737] = {n="Долинний пурхач", d="Долинні пурхачі зазвичай живуть неймовірно довго. Так було, доки люди не знайшли їм застосування в боях улюбленців."},
    [1738] = {n="Каштановий кільцехвіст", d="То три білі смуги на бурому хвості чи дві бурі смуги на білому хвості?"},
    [1739] = {n="Джерельний водомір", d="Водоміри сяють найяскравіше навесні, звідси й назва."},
    [1740] = {n="Примарна личинка", d="Якщо жива личинка живиться мертвими, то чим живиться личинка-мрець?"},
    [1741] = {n="Моторошний щур", d="Незрівнянно найкращий спосіб поширити чуму нежиті."},
    [1743] = {n="Чорнолапе лисеня", d="Упіймавши здобич, воно нерідко стає червонолапим."},
    [1744] = {n="Туманне лисеня", d="Зникає так само тихо й загадково, як туман."},
    [1749] = {n="Рожевий тайпан", d="Останнє, що ти побачиш, — червоний спалах."},
    [1750] = {n="Крихітна примара", d="Радше миле, ніж лячне."},
    [1751] = {n="Син Кривокупола", d="Який батько, такий і син."},
    [1752] = {n="Хрумчик", d="Дивно, але Хрумчиком його назвали ще до того випадку."},
    [1753] = {n="Медуза Похмурих вод", d="Коли пекельний кальмар поглине майже всю поживу в окрузі, він може повернутися до своєї первісної форми поліпа й почати життя спочатку."},
    [1754] = {n="Каналізаційна медуза", d="Стоки Даларану працюють не так добре, як ти гадаєш."},
    [1755] = {n="Пухка медуза", d="Щойно її щупальця тебе обхоплять — порятунку немає, як і від її любові до тебе."},
    [1756] = {n="Гребенеспинне порося", d="Воно обожнює бавитися в багні! А потім залюбки тебе обійме!"},
    [1759] = {n="Чаклунське порося", d="У формулі було трохи забагато... фіолетового."},
    [1760] = {n="Сквернове порося", d="Навіть поросята не вбережені від псування Легіону. Хоча це, схоже, цілком безпечне."},
    [1761] = {n="Кажанятко-відлуння", d="Більшість кажанів не сліпі, окрім цього. Цей сліпий."},
    [1762] = {n="Свинорилий кажан", d="Ніколи не кажи \"хрю\" в його присутності."},
    [1763] = {n="Шипохвостий бобер", d="Він пройшов увесь шлях аж із Нового Бівертауна."},
    [1764] = {n="Заряджений манолюб", d="Заряджена оґрами-магами Хаймолу, ця спрагла до мани істота висмокче тебе дочиста, перш ніж ти й оком змигнеш."},
    [1765] = {n="Емпірейний манолюб", d="Мерехтлива істота з чистої арканної енергії, на якій важко затримати погляд."},
    [1766] = {n="Підсилений манолюб", d="Уперше створений поряд із рунами Хаймолу, цей крихітний манолюб б'є по-справжньому міцно!"},
    [1773] = {n="Освічений манолюб", d="Маги шукають цих манолюбів, щоб увібрати їхню силову енергію."},
    [1774] = {n="Моторошний манолюб", d="Щойно манолюб поглине достатньо силової енергії, він стає агресивнішим і підступнішим. Наближайся з украй великою обережністю."},
    [1775] = {n="Краб-скрипаль Коралоспин", d="Навіть у молодому віці клешні цього краба здатні ламати кістки."},
    [1776] = {n="Мулорога мушля", d="Угадай, що в неї за ліжко. Шматок хліба."},
    [1777] = {n="Брут", d="Я Брут."},
    [1778] = {n="Пилова кролиця", d="Це надзвичайно невловиме створіння полюбляє ховатися в місцях, куди шукачі пригод нечасто заходять."},
    [1802] = {n="Смердючий хвилевик", d="Після довгої нічної гульні маги помічають, що їхні водяні елементалі трохи неприємно пахнуть."},
    [1803] = {n="Шукач пригод Будяколиста", d="Він покинув ліс, щоб побачити світ, який такому малюку має здаватися значно більшим."},
    [1804] = {n="Воскресле шаблезубе кошеня", d="Чарівне навіки."},
    [1805] = {n="Алярм-о-бот", d="Продається: трохи вживаний Алярм-о-бот. Перебудований і відновлений. Усе ще набридливий."},
    [1806] = {n="Підробний Блінґтрон", d="Не хочеш розоритися на новенький робот? Заведи собі маленького помічника за півціни! Завітай до Гоблінської Експериментальної Інженерної Корпорації і зроби замовлення! Усі продажі остаточні."},
    [1807] = {n="Лютий виплодок", d="Найжорстокіших і найлютіших з виводка можна впізнати за червонуватим відтінком."},
    [1808] = {n="Виплодок лей-ліній", d="Коли стикаються демони, жахіття й магія!"},
    [1809] = {n="Кристалічний виплодок", d="Близькість до скупчень кристалічної мани зробила тіло цього виплодка майже твердим, мов камінь."},
    [1810] = {n="Шипокігтевий виплодок", d="Ці створіння виростили хітиновий панцир навколо своїх іклів, лап і черевця."},
    [1828] = {n="Малюк Вінстон", d="Розумна мавпа, яка стверджує, що прибула 'з місяця'. Чи має вона на увазі Білу Пані, чи Блакитне Дитя?"},
    [1884] = {n="Малюк-старіріг", d="Хіба «малюк-старіріг» — це не суперечність сама в собі?"},
    [1885] = {n="Сонценароджена валькіра", d="Валькір вважають «сонценародженими», коли їх вшановують у присутності Одіна."},
    [1886] = {n="Курок", d="Завжди хотів пригорнутися до зброї? Знайомся: Курок — наймиліша гармата."},
    [1887] = {n="Вірмі Тункінс", d="У рідному світі він командував армією з десяти мільйонів демонів. Тепер його міць підвладна тобі. Тож пошли його битися з куркою!"},
    [1888] = {n="Небесне теля", d="Як Божевільному Торговцю вдалося роздобути одне з цих неземних створінь — невідомо. Та ми точно знаємо, що він розуміє його цінність."},
    [1889] = {n="Кажаня Скверни", d="Вогонь кажана Скверни ніколи не обпікає свого господаря."},
    [1890] = {n="Цуценя коргі", d="Завдяки крихітним лапкам воно куди аеродинамічніше."},
    [1903] = {n="Зум", d="Можливо, він і не найшвидший слимак, та серце в нього чемпіонське."},
    [1907] = {n="Сова-сплюшка", d="Жодних жартів про розмір, будь ласка."},
    [1911] = {n="Малий скат-хвостокол", d="Цих швидких і спритних плавців дуже прагнуть колекціонери улюбленців. Хоч вони й здаються приязними, жало на хвості здатне вбити одним дотиком."},
    [1912] = {n="Молода мутантна бойова черепаха", d="Ммм... Піца!"},
    [1913] = {n="Оленятко осяйнокопитих", d="Ну, а де ж його батьки? Ти чудовисько."},
    [1914] = {n="Прибережний побережник", d="Він обожнює довгі прогулянки берегом."},
    [1915] = {n="Сліпий пацюк", d="Бачиш, як вони мчать?"},
    [1917] = {n="Громоуражений бобер", d="Колись це створіння було звичайним бобром, та його водночас уразили блискавка, подих штормокрилого дракона і камінь."},
    [1918] = {n="Прихильник Альянсу", d="Мабуть, трохи аж надто завзятий."},
    [1919] = {n="Фанатик Орди", d="Ось хто справжній фанат своєї справи!"},
    [1920] = {n="Трансмутант", d="Ось що буває, коли алхімія йде шкереберть... зовсім-зовсім шкереберть."},
    [1921] = {n="Відв'язане змієня", d="Норов змієняти залежить передусім від того, як давно воно живилося маною. Не забувай годувати своїх улюбленців."},
    [1922] = {n="Причаєне совеня-кошеня", d="Це пташка! Це кіт! Це... кусає мене..."},
    [1926] = {n="Зголодніла лапа", d="Тисячі років тому десятьох магістрів вигнали зі спільноти високорідних за те, що вони шукали могутності в згубній темряві. У нетрях вони знайшли голод, відчай і Косумота."},
    [1927] = {n="Аш'ана", d="Одне з виводка Аш'али, довірене тобі Сноткачами."},
    [1928] = {n="Вогнекажаня", d="Запалюй!"},
    [1929] = {n="Корґнелій", d="Справжня королівська особа серед коргі."},
    [1930] = {n="Лаґан", d="Ці морські створіння люблять прослизати крізь тісні щілини й чаяться в уламках затонулих кораблів."},
    [1931] = {n="Придворний писар", d="Привиди — ненаситні читачі."},
    [1932] = {n="Кошмарний батожник", d="Батожник, хоч як його назви, пахнув би так само солодко."},
    [1933] = {n="Кошмарний трент", d="Не вмів ладнати з іншими рослинами в розсаднику."},
    [1934] = {n="Бенакс", d="Молодший брат Анакса. Старший брат Сенакса й Денакса."},
    [1935] = {n="Сквіркі", d="В особливу пору року потаємний клан мурлоків часто відправляє юних пуголовків досліджувати світ, шукати пригод і починати свою власну історію."},
    [1936] = {n="Бешкетниця", d="Ця люта кішка пройшла за військом Скверни до Азероту під час повернення Легіону."},
    [1937] = {n="Дивовижна куля мудрості", d="Чарівна, сповнена мудрості голова в кулі з обличчям Гадґара — вона здатна відповідати на запитання лише кількома фразами."},
    [1938] = {n="Врятоване оленятко", d="Маючи вдосталь твоєї любові й малих пляшечок молока, вона виросте досить сильною, щоб повернутися в дику природу."},
    [1939] = {n="Легіонер Муркі", d="Гордий прибічник Орди, цей крихітний мурлок покинув свій виводок, щоб вистежувати й нищити вбраних у синє ворогів."},
    [1940] = {n="Лицар-капітан Муркі", d="Крихітний шанувальник Альянсу, цей хоробрий мурлок змайстрував собі меч і щит, щоб нищити вбраних у червоне ворогів."},
    [1941] = {n="Сніжноклик", d="Цуценя Сніжноспіва, морозного вовка Тралла. Здолавши її в бою, ти здобув супутника на все життя."},
    [1943] = {n="Кролик Шляхетного саду", d="Чому кролики несуть яйця?"},
    [1949] = {n="Вогнистий полум'яник", d="Хто готовий до масажу гарячим камінням?"},
    [1952] = {n="Жахопаща", d="Глибоко під ареною Срібного турніру знайшли кладку яєць, що належала парі — Ейсідмо й Дредскейлу."},
    [1953] = {n="Снобольд-коротун", d="Його куди легше терпіти, коли він не сидить у тебе на голові."},
    [1954] = {n="Нерубіанський роїльник", d="Тисячі цих метушливих жахіть і донині кишать у надрах Нортренду."},
    [1955] = {n="Магмове лютеня", d="У вічній рівновазі морозу й вогню розлючене полум'я живить безліч войовничих фронтів."},
    [1956] = {n="Залізнокутий протовилупок", d="Мешканці Ульдуару перетворювали на закуті в залізо страхіття навіть малих вилупків."},
    [1957] = {n="Рунокований служка", d="Рунокованим вартовим Ульдуару не потрібні ні відпочинок, ні підзарядка — вони крокують без кінця."},
    [1958] = {n="Дитинча святилища", d="Почухай йому черевце більш ніж двічі — і сам напрошуєшся, щоб на тебе стрибнули."},
    [1959] = {n="Зимове лютеня", d="У вічній рівновазі морозу й вогню незворушна крига стає захистом без міри."},
    [1960] = {n="Хльосткобій", d="Ці паростки сяють зсередини — їх благословила дарунком сама Еонар."},
    [1961] = {n="Ультратонк G0-R41-0N", d="Новий рівень технології брухтоботів: збиває брухт у купу, а потім нищить її струменями полум'я та ракетами."},
    [1962] = {n="Повзуче щупальце", d="Є в цьому щупальці щось глибоко тривожне, тож, мабуть, краще не дивитися на нього надто довго."},
    [1963] = {n="Кісткоскалок", d="Маленький уламок Лорда Марровгара, що НІКОЛИ не припиняє атакувати твої гомілки."},
    [1964] = {n="Кипляча кров", d="Воно так і прагне торкнутися тебе, та навіщо?"},
    [1965] = {n="Гнилодих", d="Вічна відповідь на питання «що це за сморід?»."},
    [1966] = {n="Душезламне дракончатко", d="Король-Ліч перетворив духів загиблих малят Синдрагоси на нежить просто перед її кістяком — як останню наругу над великою драконицею."},
    [1967] = {n="Гуль-наймит", d="Один із незліченних гулів, прикликаних Королем-Лічем у його останній битві, приречений вічно блукати світом."},
    [1968] = {n="Лиха душа", d="Нерозкаяна душа, що колись була ув'язнена у Фростморні, а тепер невпинно кидається поміж світами."},
    [1969] = {n="Зоряний пил", d="Зрештою, усі ми створені із зоряного пилу."},
    [1974] = {n="Пташеня Сніжнопера", d="Пташенята фалькозаврів Сніжнопера інстинктивно тікають до дорослих поблизу, коли їм щось загрожує. Цей вид особливо полюбляє велику здобич."},
    [1975] = {n="Пташеня Лиходзьоба", d="Фалькозаври Лиходзьоба міцніші за інші види фалькозаврів, але мають слабший нюх. Вони полюбляють їжу з різким запахом і часто живляться падлом, що кілька днів пролежало на сонці."},
    [1976] = {n="Пташеня Гострокігтя", d="Фалькозаври Гострокігтя можуть харчуватися самими лише дрібними горіхами та ягодами, а свої кігті використовують переважно для захисту."},
    [1977] = {n="Пташеня Кровозора", d="Хоч на вигляд вони й люті, дзьоб фалькозаврів Кровозора пристосований радше до споживання плодів."},
    [1978] = {n="Сумлінний зброєносець", d="Побачивши твою звитягу в бою, цей зброєносець присягнув тобі на вірність."},
    [1979] = {n="Сумлінний грунтлінг", d="Побачивши твою звитягу в бою, цей грунтлінг присягнув тобі на вірність."},
    [1984] = {n="Білий канюк", d="У своїх мандрах Крайса зібрала чимало екзотичних птахів, та жоден з них не такий рідкісний, як це пташеня."},
    [1997] = {n="Крекери", d="Кажуть, адмірал флоту Тетіс ніколи не розлучався зі своїм вірним папугою — той завжди був поруч або сидів у нього на плечі. Тетіс будь-коли міг покликати його свистом."},
    [1998] = {n="Спора вічноживих", d="На родючих ґрунтах Печер Лементу ніщо не вмирає по-справжньому."},
    [1999] = {n="Печерний мокасин", d="Ця змія, схоже, звикла бути поруч із тобою. Можливо, колись вона була супутницею одного з друїдів Ікла."},
    [2000] = {n="Молодий Отрутозуб", d="Не торкнутий скверною девіатів, що сочиться крізь Печери Лементу."},
    [2001] = {n="Копач", d="Цей крихітний робот спеціалізується на свердлінні, затисканні та метанні блискавок зі свого мозку. Типовий ґномський винахід."},
    [2002] = {n="Наксі", d="Він просто безперестанку вивергає чумну рідину. Звідки вона береться? І куди дівається?"},
    [2003] = {n="Грогалет", d="Створений великим і могутнім чаклуном, який відмовлявся носити мантії з кишенями."},
    [2004] = {n="Сміттяр", d="Як убити те, що вже живе у смітті?"},
    [2017] = {n="Безкінечне драконя", d="Нескінченна зграя драконів значно різноманітніший, ніж гадає більшість мешканців Азероту."},
    [2018] = {n="Дух парадоксу", d="Це загадка, оповита таємницею всередині головоломки."},
    [2022] = {n="Тіларр Ґроннден", d="Жах настільки жахливий, що ти й сам дивуєшся, як таке взагалі може бути справжнім."},
    [2035] = {n="Дитинча Кровного виводку", d="На відміну від інших вирмів, кровні вирми висмоктують своїх ворогів, а не пожирають їх цілком."},
    [2036] = {n="Дитинча Морозного виводку", d="Серед військ лицаря смерті морозний вирм — найгрізніша зброя. Це дитинча не виняток."},
    [2037] = {n="Дитинча Мерзенного виводку", d="Біологічна небезпека. Тримати лише в рукавицях."},
    [2041] = {n="Кишенькова гармата", d="Пан Смайт тримав її у своїй скрині, та завжди мовби надавав перевагу молоту. Як виявилося згодом, це була помилка."},
    [2042] = {n="Клапоть", d="Цей боягузливий супутник нічого не боїться нутром... бо нутра в нього немає."},
    [2047] = {n="Бан-Фу, дитинча Бан-Лу", d="Зустрічайте наймолодшу представницю династії Сюень! Донька Бан-Лу. Племінниця Сю-Фу. Онука небесного Сюеня... Це Бан-Фу!"},
    [2049] = {n="Син Скума", d="Він дуже доброзичливий, але навіть найменші обійми обернуться для тебе добрячим ударом струму."},
    [2050] = {n="Осиротілий скверномиш", d="На Зламаному узбережжі їх справді чимало."},
    [2051] = {n="Сутінок", d="Це енергійне кошеня змінює кольори залежно від настрою."},
    [2057] = {n="Трикутка", d="Він пограбує твій пармезан, обчистить твою абонданс і вичистить твій епуас. Це справжній мунстер морів, погибель сімох камамберів."},
    [2058] = {n="Жнець ворогів 0.9", d="Найперший прототип смертоносного Жнеця ворогів."},
    [2062] = {n="Тінь", d="Загублений на Аргусі й охоплений темрявою, цей грайливий лис здатен відганяти Порожнечу, просто будучи поруч із тобою."},
    [2063] = {n="Хитрий бабак", d="Цей бабак увесь цей час був поруч із тобою. Ось який він спритний."},
    [2064] = {n="Шахтарська мавпа", d="Краще тримай її подалі від гармат."},
    [2065] = {n="Землерийна щуриця", d="Розбійники нерідко тримали кількох таких у кишенях про всяк випадок. Не питай мене чому."},
    [2071] = {n="Бронзовий протодракончик", d="Бронзових протодракончиків знаходили лише в найдивовижніших часових лініях."},
    [2072] = {n="Позачасовий бронзовий дрейк", d="Цей дрейк дивним чином зберіг свій вік упродовж усіх мандрів, та ось розмір його точно змінився."},
    [2076] = {n="ШвидкийНомерIII"},
    [2077] = {n="Примарна акула", d="Прокляття королеви Азшари над мешканцями Азсуни вразило не лише нічних ельфів. Ця акула приречена на вічність бездонного голоду."},
    [2078] = {n="Крихітрон", d="Під час багаторічної війни з чорною зграєю драконів дворфи намагалися створювати менших големів, у яких було важче влучити."},
    [2079] = {n="Покинутий експеримент", d="Малоріак був надзвичайно винахідливий і не марнував навіть найменших клаптиків плоті."},
    [2080] = {n="Брязкощелеп", d="Оживлені кістяні конструкти Нефаріана були дієвим способом боротися з численними шукачами пригод, що дошкуляли йому, а надто з їхніми магами."},
    [2081] = {n="Сестра кладки Сутінків", d="Навіть зовсім крихітні створіння можна спаплюжити: апокаліпсис не оминає нікого."},
    [2082] = {n="Скутий потік", d="Серед найогидніших справ культу Сутінкового Молота було скування стихій малих струмків і річечок."},
    [2083] = {n="Безликий прислужник", d="Очей у нього немає, та завжди здається, ніби він пильно дивиться на тебе."},
    [2084] = {n="Зефірний принц", d="Дрібне божество вітру, що владарює над легкими подмухами, які на коротку мить переконують тебе, ніби літню спеку ще можна терпіти."},
    [2085] = {n="Раф'аль", d="Якщо ти відчув легкий порив, від якого пробіг дрож, то це, напевно, був Раф'аль."},
    [2086] = {n="Пломінь-гончак", d="Дехто каже, що це щеня Риплімба й Рейджфейса, інші ж кажуть: «Не хочу про таке навіть думати»."},
    [2087] = {n="Відлюдник попелястої павутини", d="Рідкісний вид попелястих павуків, відомий тим, що самиця пожирає ноги свого партнера й відкладає яйця в його тіло, яке ще здригається, а також гарним фіолетовим забарвленням."},
    [2088] = {n="Здиматель", d="П'ять речей, без яких він не може жити: здиматися, здиматися, здиматися, здиматися, здиматися."},
    [2089] = {n="Інфернальний Жароклешня", d="Під час свого перебування у Вогняних Землях Фандрал часто нудьгував і вправлявся у формотворчій магії на тамтешній флорі та фауні."},
    [2090] = {n="Безликий розумобій", d="Заволодіти твоїм розумом сповна він не здатен, але влаштувати справді жахливу мігрень — цілком."},
    [2091] = {n="Зіпсована кров", d="Деякі краплі крові Дезвінга живуть і донині, глибоко в загублених куточках світу, навіки шукаючи свого втраченого носія."},
    [2092] = {n="Нестабільне щупальце", d="Друзі прозвали його «Ляпко»."},
    [2093] = {n="Амальгама руйнування", d="Просякнута елементієвою рудою, якою вкривали панцир великого дракона Дезвінга, і один з останніх відголосків того безумства, що ледь не поглинуло Азерот."},
    [2113] = {n="Марсуул скверникіготь", d="Хоча більшість марсуулів на Аргусі живиться плодами, цей надає перевагу соковитому хрускоту дрібних гризунів."},
    [2114] = {n="Сніговий єті", d="Хто їх робить? Як вони туди потрапляють? Цього не знає ніхто, хіба що Дід Зимовій."},
    [2115] = {n="Косоокий", d="Мені весь час здається, ніби хтось за мною стежить."},
    [2116] = {n="Осиротілий марсуул", d="Насправді він не сирота. Просто з такою назвою тобі не так соромно його викрадати."},
    [2117] = {n="Бич Скверни", d="Прекрасний і смертоносний."},
    [2118] = {n="Сумирний небоплавець", d="Небоплавці трапляються найрізноманітніших барв. Біологи вважають, що яскравість цих кольорів допомагає і приваблювати пару, і відлякувати хижаків."},
    [2119] = {n="Уражений Скверною небоплавець", d="Стережися, коли він плюється."},
    [2120] = {n="Хапке втілення", d="Тягнеться до тебе з якогось безмежного незвіданого закутка Порожнечі... щоб тебе обійняти."},
    [2121] = {n="Риюча жовчна личинка", d="Якщо жовчна личинка залишається в норі надовго, вона починає втрачати свій колір. А коли нарешті виповзає назовні, буває доволі ненажерливою."},
    [2122] = {n="Анторанська жовчна личинка", d="Близькість Анторуса робить цих личинок украй агресивними."},
    [2123] = {n="Жовчна личинка", d="Рання стадія життєвого циклу жовчоплази."},
    [2124] = {n="Жовчобич", d="Завершальна стадія життєвого циклу жовчобича."},
    [2126] = {n="Анторанський жовчобич", d="Жовчобичі здебільшого живляться трупами жертв Легіону. Та відколи ти прибув, вони призвичаїлися смакувати ще й тілами демонів."},
    [2127] = {n="Мерехтливий аргуніт", d="Народжений на місці падіння «Зенедара» на Аргусі."},
    [2128] = {n="Малий викривлений переслідувач", d="Хоч він і має чимало спільного з викривленими переслідувачами Азероту, дослідження свідчать, що ці види розвивалися цілком незалежно один від одного. Дивовижно!"},
    [2129] = {n="Малий переслідувач Порожнечі", d="Порожнеча може поглинати життя або зливатися з ним. Останнє часто має непомітні наслідки."},
    [2130] = {n="Уламок Порожнечі", d="Тебе не полишає дивне відчуття, що він хоче тебе вбити."},
    [2131] = {n="Арканний пожирач", d="Багато тисячоліть тому манавирми буяли на Аргусі, та відтоді минуло чимало часу й багато що змінилося."},
    [2132] = {n="Знавіснілий від Скверни змій", d="Коли мани стає обмаль, ці змії шукають інших джерел енергії, щоб поживитися."},
    [2133] = {n="Карликовий марсуул", d="Він любить, коли його гладять за плавцями."},
    [2134] = {n="Юний небоплавець", d="Небоплавці вміють літати від народження, і подеколи спостерігали, як самиці народжують просто в польоті!"},
    [2135] = {n="Бунтівний біс", d="Проти чого вони бунтують? Краще запитати, проти чого вони НЕ бунтують."},
    [2136] = {n="Ууна", d="Ууну знайшли прив'язаною до ур'зула й випустили в Морок, де вона блукала в суцільній пітьмі."},
    [2143] = {n="Тоттл", d="Єдине бажання Тоттла — досліджувати світ поруч із тобою!"},
    [2157] = {n="Дарт", d="Це юне жабеня врятували з лютого воєнного табору кривавих тролів. Турботою й щедрою годівлею ти здобув його довіру, і Краг'ва попросив тебе завжди про нього дбати."},
    [2158] = {n="Поштовик-елементаль", d="Поштмейстера часто описують як істоту езотеричну, містичну, ба навіть незбагненну. Про загадкового володаря пошти відомо так мало, що, мабуть, ніхто за межами кола Воскової Печатки не здатен підтвердити саме існування цього дивовижного, закоханого в листи поштовика-елементаля."},
    [2163] = {n="Силітидський міні-танк", d="Цей силітидський бойовий танк розвинувся завчасно. Він ніколи не досягне повного розміру, але такий самий лютий, як і його більші родичі."},
    [2165] = {n="Франсуа", d="Франсуа, бундючний представник курчазії, чиї статки й вплив зросли на визиску та праці дзьоблетаріату."},
    [2184] = {n="Вомпер", d="Коли Вомпер хоче гратися, він дасть тобі знати грайливим стусаном головою."},
    [2185] = {n="Кеп'н Крекерс", d="Не кажи Кеп'ну Крекерсу нічого, чого не хотів би чути щодня впродовж наступних 20 років."},
    [2186] = {n="Поріддя Меректи", d="Про велику змію Меректу та численні яйця в Храмі Сетраліс відомо небагато, та всі мешканці Зандалару, схоже, відчувають до цих змій помітну суміш поваги й страху."},
    [2187] = {n="Брудний слиз", d="Ти не зовсім певен, звідки він узявся, та й не дуже хочеш знати, але точно впевнений, що він пожирає неймовірну кількість сміття."},
    [2188] = {n="Пода", d="Пода був лише маленькою частинкою великої справи й завжди намагався відповідати взірцю свого старшого брата Коди."},
    [2189] = {n="Цьомчик", d="Цьомчик обожнював життя у Ґленбруку: там було повно охочих погратися й місць, де можна поспати, а ще саме там коїлися неймовірні речі на найбезневинніших чаюваннях."},
    [2190] = {n="Кобреня-охоронець", d="Щойно вилуплене кобреня може бути не менш смертоносним, ніж доросла кобра, а то й більше."},
    [2192] = {n="Мстива курка", d="Наймудріші інженери Азероту добре знають: єдине, що небезпечніше за живу злу курку, — це розум злої курки, пересаджений у тіло механічної курки."},
    [2196] = {n="Малий Тіка", d="Більшість хижаків насамперед атакують найм'якші місця своєї здобичі. А Малий Тіка воліє бити прямо в обличчя."},
    [2197] = {n="Дитинча жахорога", d="Жахороги — одні з найвитриваліших і найсильніших створінь, які ступають по Азероту. Вони можуть видаватися сумирними велетнями, та стережися опинитися перед таким, коли він став на стежку війни."},
    [2198] = {n="Таптаф", d="Таптаф беззаперечно відданий — доки його годують."},
    [2199] = {n="Відновлений ревенант", d="З часом мешканці Друствару збагнули, що ховати когось чи щось небезпечно: на жаль, завжди знайдуться темні особи, які прагнуть викопати й оживити все, що тільки відшукають."},
    [2201] = {n="Зачарована маска тікі", d="Зандалари — майстри магії та спілкування з духами, і вони часто наділяють предмети силами, щоб зміцнити свій зв'язок зі світом духів."},
    [2202] = {n="Міїмії", d="Бинти мумії слугують двом цілям: одна — зберегти все всередині незайманим, інша — пом'якшити жах тих, хто побачив би, що насправді ховається під ними."},
    [2352] = {n="Баа'л", d="Про цього потойбічного слугу відомо небагато."},
    [2372] = {n="Тіньоспинний повзун", d="Навіть найміцніший краб із найтвердішим панцером може піддатися темним таємницям тіней."},
    [2373] = {n="Річкова жаба", d="Річкові жаби долини Штормової Пісні відомі тим, що намагаються загіпнотизувати людей, дивлячись просто в очі й видаючи низьке гуркотіння."},
    [2374] = {n="Прісноводний повзун", d="Раки-самітники долини Штормової Пісні використовують для своєї мушлі все, що знайдуть і що їм підходить. Якщо влізло — там і сидять."},
    [2375] = {n="Долинний бабак", d="Долинні бабаки дуже прудкі на ноги й майстерно риють нори. Діти полюбляють ганятися за ними й намагатися стукнути по голові, коли ті висовують її, щоб погрітися на сонці."},
    [2376] = {n="Долинна курка", d="Колись давно курей у Долині Штормової Пісні розплодилося так багато, що мешканці боялися, чи не виклюють вони весь маїс із полів і не лишать решту голодними."},
    [2377] = {n="Піщаноспинний повзун", d="Піщаноспинні повзуни дістали свою назву через злегка липкий зовнішній панцир, до якого під час руху чіпляється пісок."},
    [2378] = {n="Річкова видра", d="Вуса в річкових видр починають рости змалечку й не припиняють ніколи. Коли видра виростає й доживає до старості, вусів на її морді більше, ніж у будь-якої іншої відомої істоти."},
    [2379] = {n="Медоносна бджола", d="Подейкують, що ці медоносні бджоли здатні відчути пилок щойно розквітлої рослини на півночі Долини Штормової Пісні, навіть коли самі ще в найглибших нетрях Друствару."},
    [2380] = {n="Паразитична вепромуха", d="Жало оси-нищительки може спричинити сильний біль, що триває до трьох годин. Якщо вона вжалила, негайно зверніться до лікаря."},
    [2381] = {n="Рак-самітник", d="Раки-самітники — єдині з усіх раків-самітників, хто здатен відрощувати кінцівки, втрачені в бою."},
    [2382] = {n="Суходільна квакуха", d="Слиз, що його виділяють суходільні квакухи, так добре відштовхує воду, що корабельники Кул-Тіраса вже багато років використовують його для просочення деревини."},
    [2383] = {n="Велетенський деревоточець", d="Велетенський деревоточець може вгризтися майже в будь-яку поверхню, по якій повзе, окрім суцільного каменю."},
    [2384] = {n="Прибережний метелик", d="Метелики відчувають смак лапками! Я якось спробував так само, але тільки все забруднив."},
    [2385] = {n="Рифовий самітник", d="Витівка з підкиданням під двері спрацьовує не так добре, коли будинок може за тобою погнатися."},
    [2386] = {n="Прибережний дріботун", d="Фіолетове забарвлення допомагає цьому видові зливатися з камінням і тінню, але якщо ці раки надто довго затримуються на відкритому піску, вони стають легкою здобиччю для чайок."},
    [2387] = {n="Золотий жук", d="Багато прадавніх племен шанували цих величезних жуків."},
    [2388] = {n="Кровогарячкова тарантула", d="Для тролів ці створіння цілком безпечні, проте все живе в Назмірі їх боїться."},
    [2389] = {n="Невловний ковзун", d="Водяні ковзуни тримаються на поверхні води завдяки її натягу та довгим водовідштовхувальним ногам."},
    [2390] = {n="Листокрилий пурхач", d="Сидячи на дереві, цей вид стає майже невидимим для будь-якої здобичі."},
    [2392] = {n="Молодий піскорийник", d="Цей вид нишпорить у піску, шукаючи закопані рештки гнилих створінь. Так він підтримує наші пляжі чистими!"},
    [2393] = {n="Липкий слизняк", d="Огидне створіння. Навряд чи комусь таке потрібно."},
    [2394] = {n="Повернуте дитинча", d="Жах за життя. Жах і по смерті."},
    [2395] = {n="Ситий кровопивця", d="Наносити прямо на чоло."},
    [2397] = {n="Примарний крук", d="Аж раптом залунало тихе постукування…"},
    [2398] = {n="Болотний стрибун", d="Скільки боліт він уже переплигнув? Ніхто не знає."},
    [2399] = {n="Рак-самітник", d="Коли ти запасливий, але хочеш лишатися в русі!"},
    [2400] = {n="Прибережний стрибун", d="Доволі надокучливий вид. Хоч які високі мури зведи, ці створіння однаково перестрибнуть через них."},
    [2401] = {n="Риюн", d="Риюна змайстрував гном-фермер, щоб копати ями, та він, як і слід було чекати, швидко вийшов з ладу, спричинивши низку лих."},
    [2402] = {n="Брутус", d="Створений за технологією вічно виляючого хвоста, Брутус — механічно сертифікований хороший хлопчик."},
    [2403] = {n="Безодняний вугор", d="Коли наги вдерлися до Стормсонга, вони привели своїх улюблених тваринок — безодняних вугрів."},
    [2404] = {n="Морський джміль", d="Ці витривалі бджоли — основа потужного виробництва меду й медовухи. Десятиліттями Припливні мудреці забороняли будь-кому вивозити їх за межі Стормсонга."},
    [2405] = {n="Корлейнський сокіл", d="Корлейнських соколів від народження навчають бути розвідниками й бойовими супутниками. Ті нечисленні, кого оминуло прокляття Серцезгуби, служать тому ж самому Орденові Жарин."},
    [2406] = {n="Дрюстварське порося", d="Це порося уникло перетворення на ковбасу від рук Роланда завдяки хитрому павукові."},
    [2407] = {n="Знавіснілий білохвіст", d="Цей червононосий зайчик неймовірно м'який на дотик — тільки бережи пальці."},
    [2408] = {n="Жовчоіклий шмигун", d="Срібний пил, що виблискує на кожній нозі цього павука, приваблює здобич, яка несвідомо потрапляє в павутину, з якої вже не вибратися."},
    [2409] = {n="Великокрилий ара", d="Краще не залишай свою їздову тварину під ним."},
    [2410] = {n="Механічний лучний собачка", d="Ця чарівна купа крутіїв, шестерень і зубчастих коліс зібрана не в Гномрегані. То де ж тоді?"},
    [2411] = {n="Лозове цуценя", d="Вона обожнює, коли їй чухають животик. Тільки стережися скалок."},
    [2412] = {n="Крихітний жахорог", d="Улюбленець серед дітей, попри часті випадкові штрикання рогом."},
    [2413] = {n="Гомілкогриз Зандаларі", d="Відомий тим, що гризе гомілки геть усім — від сауридів до брутозаврів."},
    [2414] = {n="Личинка кровожера", d="Винятково драглиста, надто ж після ситного обіду."},
    [2415] = {n="Траґґ Допитливий", d="Краґ'ва неохоче відправив Траґґа до експедиції Таланджі, сподіваючись, що там знайдеться хтось підхожий, аби супроводити його в мандрівці Азеротом."},
    [2416] = {n="Малий Бен'фон", d="Білі брутозаври були на межі вимирання, аж доки кілька заповзятливих шукачів пригод не взялися до справи. Малий Бен'фон, можливо, успадкувала зріст свого батька, та норов у неї достеменно материнський!"},
    [2417] = {n="Ранішу-коротун", d="Завжди голодний, а вдача в нього навдивовижу приємна."},
    [2418] = {n="Дитя Джані", d="Лоа-стерв'ятник гадає, що ти можеш дечого навчити цього саврида. Тільки не спускай з ока свого гаманця."},
    [2419] = {n="Болотяна ропуха", d="Ці ропухи геть не в захваті, коли їм відривають лапки."},
    [2420] = {n="Проклятий чаклун", d="Ніхто не знає, звідки взялася ця примарна маска-тікі й чому вона повсякчас така люта. А втім, тебе вона, схоже, вподобала!"},
    [2421] = {n="Сауроліск-маля", d="Вони такі милі, доки в них не виростуть гострі, мов бритва, зуби й не з'явиться отрута."},
    [2422] = {n="Синій пурхач", d="Такий гарненький, що аж з'їв би. Але не варто. Він отруйний."},
    [2423] = {n="Прісноводний щипач", d="З цим крабом під боком знайти прісноводні перлини буде завиграшки."},
    [2424] = {n="Багряна жаба", d="Дивовижний червоний колір цієї жаби, схоже, розвинувся саме для маскування в крові. Моторошно."},
    [2425] = {n="Рак-самітник у мушлях", d="Вона лише хотіла втекти. Знайти затишну мушлю. Посидіти на пляжі. А тепер вона — твій улюбленець."},
    [2426] = {n="Піщана жалка оса", d="Загальновідомий факт, що оси виробляють значно якісніший мед, ніж бджоли. Загальновідомий у дуже, дуже вузькому колі осівників."},
    [2427] = {n="Коу'па", d="Це справжній сміливець, що вже багато років вірно мандрує поряд із Коджо. Він полюбляє хованки, а ще завзято ковзати на власному панцирі."},
    [2428] = {n="Хижий шмагач", d="Ця жахлива рослина-людожер обіцяє, що здатна здійснити всі твої найзаповітніші мрії. Якщо її нагодувати."},
    [2429] = {n="Азериті", d="Уся в матінку. Азериті палко захищає рідну матір і накинеться на кожного, хто схоче заподіяти їй лиха."},
    [2430] = {n="Загублений платизавр", d="Платизаври блукали землями ще до того, як хтось почав вимірювати час. Це прадавній вид, що пристосувався ходити суходолом, а ще з якоїсь причини звик повторювати короткі звуки тричі поспіль."},
    [2431] = {n="Жахокліщ-п'явка", d="Жахокліщі стали дуже навальним і панівним видом усюди, куди б їх не занесло. Вони неймовірно швидко нападають на будь-який новий вид і не вгамовуються, доки не знайдуть слабке місце, яке можна використати."},
    [2432] = {n="Пухнастий повзунок", d="Молодь рівнинних павуків Аратійського нагір'я здатна жбурляти хмари колючих волосків зі свого черевця ворогам просто в очі. І це ще не все: вони ж бо плюються отруйним павутинням."},
    [2433] = {n="Альдрусіанський паросток", d="Доки лишається бодай один із його паростків, гілколорд Альдрус ніколи не помре по-справжньому."},
    [2434] = {n="Порожнечний звивун", d="Або Дарбел Монтроуз була нікудишньою чорнокнижницею, або ж вона просто обожнювала все миле. А може, і те, і те."},
    [2435] = {n="Малесенька титанічна сфера", d="Цих створінь зробили, щоб вони допомагали титанам із усілякими дрібними справами, та ось ця напрочуд крихітна. Малесенька титанічна сфера, уперед!"},
    [2436] = {n="Коростявчик", d="Хоч Йогурса й пережила пошесть, що вразила багатьох ведмедів Гілсбреда, та вона втратила розум, а її ведмежата навіки скверні."},
    [2437] = {n="Лютоверещун", d="Почасти сова, почасти ведмідь... і почасти олень, що завбачливо дозволяє уникнути можливих судових позовів."},
    [2438] = {n="Гнилопер", d="Чумопер та її виводок добре годуються падлом, що його битва за Стромґард розкидала по всьому Нагір'ю."},
    [2439] = {n="Калюжа азериту", d="Ці краплі азериту нестійкі й схильні вибухати, якщо їх потурбувати."},
    [2440] = {n="Фозлінг", d="Живий уламок Фозрука — найгучнішого кам'янолицього бегемота Араті."},
    [2441] = {n="Верескун", d="Легенда клану Кам'янокулаків розповідає про хмару птахів-стерв'ятників, що летіла за воїнами-оґрами крізь Темний портал під час Другої війни; можливо, усі двоголові падложери Азерота — їхні нащадки."},
    [2442] = {n="Джмелик", d="Джмелик, може, і не був найбільшою бджолою серед мільйонів у вулику, та це не означає, що йому не вирости в чемпіона."},
    [2443] = {n="Мініоблогова вежа", d="Могутня бойова машина чарівно маленьких розмірів."},
    [2444] = {n="Мінібойова машина", d="Могутня бойова машина чарівно маленьких розмірів."},
    [2445] = {n="Шкряботун", d="Шкряботуна назвали так за кораблі, які він трощить, а не за те, як він рухається, і ти про це не забувай."},
    [2446] = {n="Іскропанцирний піщаний краб", d="Панцирі цієї особливої зграї крабів мерехтять на піску, наче самоцвіти."},
    [2447] = {n="Павучок Жариноткача", d="Павуки-жариноткачі відомі серед острівних племен своїм теплим павутинням, придатним для прядіння."},
    [2448] = {n="Скелекопитне козеня", d="Копита цього різновиду кіз розвинулися так, що однаково впевнено ступають і по піску, і по камені."},
    [2449] = {n="Фальшивий Кулакобій", d="Хтось залишив цю механічну горилу на острові, щоб стежити за тамтешніми тваринами, та хто і навіщо?"},
    [2450] = {n="Жарине цуценя", d="Єдині м'ячики, які цей пес ганяє, — тверді, мов діамант, вогнетривкі камені. Дуже важкі, кидати їх — задоволення сумнівне."},
    [2451] = {n="Кровокам'яний тунельник", d="Це отруйний черв'як у тебе в кишені чи... чекай, навіщо воно взагалі в кишені?"},
    [2452] = {n="Поро", d="Поро не вміє літати, та живе довго й щасливо, стрибаючи по землі й струшуючи плоди з дерев."},
    [2453] = {n="Молодий розсолопанцирник", d="Навіть юних розсолопанцирників вабить лінія в небі, де вона сходиться з хвилями, — вона кличе їх."},
    [2454] = {n="Маля кунчонга", d="Судячи з розмірів, мантиди знову відроджують свій рій — найпевніше, через появу нової імператриці."},
    [2455] = {n="Капітан Нібс", d="Колись Капітан Нібс очолював приречену морську подорож мавп, надто розумних собі на лихо, що дуже швидко скінчилася потопленням."},
    [2456] = {n="Барнабі", d="Багатий пірат-капітан зустрів дивного чоловіка на пристані невідомого міста й виторгував вічне життя для свого вірного супутника. Як і з більшістю бажань, пов'язаних з мавпами, щось пішло не так."},
    [2457] = {n="Холодносвітний прибійник", d="Колись холодносвітні були доволі звичним явищем в океанах, на буркотіння багатьох рибалок, та більше їх немає."},
    [2458] = {n="Мускусобоке телятко", d="Досить намочити бодай одну з цих пахучих тварюк — і за запахом це те саме, що качатися в купі мокрих псів."},
    [2459] = {n="Пирхун", d="Цей витривалий вид, що особливо полюбляє прибережні чагарникові трави, прожив багато років у незвіданих землях."},
    [2460] = {n="П'явка Вору'кар", d="Вору'кар безмежно віддані своєму ватажку, Ворус'араку, який вивів їх у безпеку з лабет Короля-Ліча."},
    [2461] = {n="Чорнильчик", d="Хоч би яка історія крилася за його загадковою пов'язкою на оці, він про неї мовчить."},
    [2462] = {n="Малий восьминіг", d="Восьминога-малюка фахівці називають «м'якунчиком»."},
    [2463] = {n="Піщанопанцирний цокотун", d="У теплі літні місяці шум, який здіймають ці шкідники, здатен звести людину з розуму."},
    [2464] = {n="Смертожальний скорпід", d="Його жало болючіше за... ну, насправді ні за що. Ти точно хочеш лишити його собі за улюбленця?"},
    [2465] = {n="Грайливий морозець", d="Знаєш, як прикро повернутися до свого напою, а лід уже геть розтанув? Це його робота."},
    [2466] = {n="Хихотливе полум'я", d="Найпідступніший з-поміж духів-пустунів і причина, чому пандарени винайшли вогнетривкі штани."},
    [2467] = {n="Пустотливий зефір", d="«Стережися прохолодного вітерцю, бо він несе підступ.» — пандаренське прислів'я"},
    [2468] = {n="Реготливий камінчик", d="Земля, що двигтить у тебе під ногами... це вона трясеться чи регоче, а чи водночас і те, й те?"},
    [2469] = {n="Брунька будяк-куща", d="Лісові духи, що населяють острови Великого моря, понавигадували безліч пасток, аби заманити необачних гостей."},
    [2471] = {n="Копитце", d="Копитце любить: гасати, підстрибувати, пустувати й буцатися — саме в такому порядку."},
    [2472] = {n="Хапун", d="Із цим малюком краще вдягни рукавиці — він обожнює кусатися!"},
    [2473] = {n="Сонцелуске маля", d="Яскрава луска цього рідкісного вітрозмія вбирає сонячне світло, щоб гріти його навіть у затінку."},
    [2474] = {n="Шестеренко-пружинний стрибунець", d="Механічні жаби можуть стрибнути понад сім мільйонів разів, перш ніж їхні шестерні почнуть зношуватися."},
    [2475] = {n="Слизько", d="Ці створіння можуть рухати кожним щупальцем окремо, тож вони чудово справляються з кількома справами водночас і обіймають краще за всіх."},
    [2476] = {n="Роздутий кровожер", d="Найменший поріз може стати згубним для цього виду: вони починають витікати всюди довкола."},
    [2477] = {n="Кроґґеня", d="Роги кроґґа починають стрімко рости майже одразу після народження, а ще вони з найтвердіших природних матеріалів, які лиш трапляються на живих створіннях."},
    [2478] = {n="Сер Щипало", d="Ніхто не знає, хто перший почав вбирати крабів Азероту в одяг, і ця мода ще нескоро мине."},
    [2479] = {n="Цебропанцирник", d="Ніхто не знає, хто перший почав вбирати крабів Азероту в одяг, і ця мода ще нескоро мине."},
    [2482] = {n="Вовк-кулька", d="Куля з Темного Місяця, зроблена у формі вовка."},
    [2483] = {n="Мурлок-кулька", d="Куля з Темного Місяця, зроблена у формі мурлока."},
    [2484] = {n="Кінь-кулька", d="Куля з Темного Місяця, зроблена у формі коня."},
    [2525] = {n="Тарантул Червоного хребта", d="Тарантули, що мешкають на півдні Червоного хребта, менші за своїх родичів з інших куточків Азероту, проте надолужують це швидкістю і лютістю."},
    [2526] = {n="Пір'я", d="Гадали, що Пір'я загинуло в потужному вибуху, та найкмітливіші інженери зуміли відтворити його як неперевершене механічне диво."},
    [2527] = {n="Дитя Па'ку", d="Дітям подекуди розповідають історію, що всі крилаті створіння не могли літати, доки Па'ку не наслав достатньо вітру, щоб підняти їх із землі."},
    [2528] = {n="Нащадок Краґ'ви", d="Жаба з роду Краґ'ви за своє життя стрибає в середньому понад сім мільйонів разів."},
    [2529] = {n="Мала громова ящірка", d="Великі пластини на спині цієї ящірки зроблені з таємничого, але надзвичайно провідного матеріалу, що робить її ідеальною для накопичення й вивільнення величезних обсягів електрики."},
    [2530] = {n="Механтул", d="Механтула створив невідомий ґномський інженер. Подейкують, що оригінальне креслення знайшли в кімнаті, затягнутій старою запорошеною павутиною, проте ні самого механтула, ні інженера, що накреслив схему, відшукати так і не вдалося."},
    [2531] = {n="Механічний тарган", d="Механічні таргани мають менше шансів пережити апокаліпсис, ніж справжні живі таргани, тож це один із доволі сумнівних здобутків інженерної думки."},
    [2532] = {n="Прокажений пацюк", d="Випромінювання від усіх механізмів Ґномреґану надає цим пацюкам слабкого зеленого сяйва, помітного лише в цілковитій темряві."},
    [2533] = {n="Сторожовий пес-сигналізатор", d="Сторожового пса-сигналізатора створили для охорони, та люди понад усе хотіли мати такого вдома, бо вже надто він милий."},
    [2534] = {n="Міні-павук-танк", d="Ніхто достеменно не знає, чому комусь спало на думку, що зменшені копії машин Ґномреґану — це гарна ідея, але гратися з ними справді дуже весело."},
    [2535] = {n="Лозовий привид", d="Моторошна магія Друствару викликала появу немислимих створінь. Одні досі чаяться в тінях, інші ж наче й самі зіткані з тіней."},
    [2537] = {n="Малюк-раптор Зандаларів", d="Раптори Зандалару вкриваються пір'ям у дуже ранньому віці, через що здаються легкою здобиччю для необачного хижака. Насправді ж ці малі страхіття жеруть усе, що забажають, і самі майже жодному виду не дістаються на поживу."},
    [2538] = {n="Прудкий", d="Як і в багатьох інших видів, за розміром найбільшого пазура можна приблизно вгадати, яким завбільшки стане раптор, коли виросте."},
    [2539] = {n="Дряпій", d="Один із найдавніших записів про перемогу у великій битві на Зандаларі зображає могутніх воїнів, що мчали в бій на броньованих рапторах. Легенда каже, що не воїн обирав собі раптора, а раптор обирав воїна."},
    [2540] = {n="Танзіл", d="У певні години дня сонячне світло так відбивається на пір'ї червонястих рапторів, що воно скидається радше на полум'я, ніж на пір'я."},
    [2541] = {n="Статечний папуга", d="Цей вишуканий папуга — лише для найповажніших мореплавців."},
    [2544] = {n="Вартова Темне Узбережжя", d="Сови-вартові Темне Узбережжя повік-віків стережуть свій рідний край."},
    [2545] = {n="Порив Циклара", d="Коли Циклар прибув на Темне Узбережжя, всюди довкола з'явилися маленькі вихори. Одні з часом розвіялися, інші ж знайшли дорогу назад до Циклара і розчинилися в навколишніх вітрах."},
    [2546] = {n="Детектив Рей", d="Ось що буває, коли намагаєшся перевершити небилиці Піпа Квіквіта про те, як його ковтали небезпечні створіння."},
    [2547] = {n="Крапля Гідрата", d="Водяні краплі Гідрата ще й чудово зволожують суху шкіру."},
    [2548] = {n="Вічногорючий древінь", d="Самотній Прадавній знань у Дарнасусі своїм останнім зусиллям зумів урятувати цього древеня, огорнувши його чарівною аурою, щоб полум'я не спалило його остаточно."},
    [2549] = {n="Драглі Порожнечі", d="Ці драглі бачили й кращі часи. Тепер вони дивляться на світ п'ятдесятьма різними очима."},
    [2550] = {n="Зур'адж Виснажений", d="Колись могутній воїн н'ракі, Зур'адж втратив свою силу, яку викрав і поглинув невідомий суперник."},
    [2551] = {n="Кам'яношкіре маля", d="Грайливих стусанів цих лосенят досить, щоб збити орка з ніг."},
    [2552] = {n="Шкірокрилий верескун", d="Ми небагато знаємо про цей вид, але одне знаємо напевно: кажани — це не комахи."},
    [2553] = {n="Гнилий гуль", d="Хапай, поки не пізно."},
    [2554] = {n="Голкоспинне щеня", d="Голкоспинні дикобрази вижили в острівному кліматі, бо розвинулися такими, що їм надзвичайно щастить."},
    [2555] = {n="Альбіносний сутіньовартовий", d="Білі круки-альбіноси неймовірно рідкісні й дуже цінуються серед торговців Великого моря."},
    [2556] = {n="Тінепере маля", d="Хоч воно ще зовсім пташеня, його кігті вже досить гострі, щоб проштрикнути шкуру багатьох дрібніших створінь."},
    [2557] = {n="Вогнежальний джиґун", d="Кажуть, укус вогнежальних ос болючіший за укус будь-якого іншого виду — біль пече, наче полум'я під шкірою."},
    [2558] = {n="Лорд Гавкінгтон", d="Лорд Гавкінгтон дістав свій титул після того, як решта мешканців Гейвенсвуду піддалася божевіллю."},
    [2559] = {n="Язикобій", d="Він має одне рішення для всіх своїх проблем: дати кривдникові доброго прочухана язиком."},
    [2560] = {n="Дряпунчик", d="Головні заняття: качатися на спині, грітися на сонці, скиглити, випрошуючи почухати черевце, і насолоджуватися чуханням черевця."},
    [2561] = {n="Громолускове дракеня", d="Цих дракенят часто ловлять мешканці Йорундолу, доки ті ще малі й піддаються навчанню."},
    [2562] = {n="Багряний октопод", d="Багряний різновид октопода виростає більшим і витривалішим за інших і здатен витримувати нищівний тиск глибин."},
    [2563] = {n="Ніченогорнутий споглядач", d="В Армії Вартових велика честь — отримати під опіку сову, народжену серед гілля великого дерева Тельдрассил."},
    [2564] = {n="Перебудований бот-горила", d="Зручність бойових роботів у тому, що після бійки їх можна просто зібрати докупи. Крок другий — приладнати велетенську лазерну гармату, щоб напевно перемогти в наступній сутичці."},
    [2565] = {n="Перебудований механічний павук", d="Кожен, хто серйозно ставиться до бойових механічних павуків, знає: запасні ноги треба купувати про запас. Ці штуки доволі крихкі."},
    [2566] = {n="Пташеня альбатроса", d="Альбатрос здатен пролетіти далі за будь-який інший вид птахів у всьому Азероті."},
    [2567] = {n="Багряне кажаня", d="На відміну від більшості інших видів кажанів, багряні кажани насправді сліпі й цілковито покладаються на ехолокацію, щоб орієнтуватися."},
    [2568] = {n="Кобальтовий крук", d="Пір'я кобальтового крука моторошно сяє у місячному світлі, тож уночі його легко помітити."},
    [2569] = {n="Фіолетовий безодній вугор", d="Безодні вугри здатні проковтнути й перетравити істоту, удвічі ширшу за їхнє тіло."},
    [2575] = {n="Пан Крабс", d="Пан Крабс здобув свою нинішню мушлю, вийшовши переможцем у затяжній бійці майже з десятком інших раків-самітників."},
    [2576] = {n="Дзьоберт", d="Улюблена страва Дзьоберта - воронові ягоди."},
    [2577] = {n="Жабеня", d="Шкіра бірюзової жаби часом так влучно мерехтить на сонці, що дає чудове маскування на поверхні води."},
    [2578] = {n="Лускань", d="Луска завроліска - на диво гнучкий, але міцний матеріал, який часто використовують, щоб укріпити чи полагодити зламані або зношені речі."},
    [2579] = {n="Кам'янокіготь", d="Квілени були улюбленими супутниками давнього народу могу завдяки своїй відданій вдачі."},
    [2580] = {n="Заблукалий дух", d="Надто часті переходи у світ духів можуть бути небезпечними для здоров'я."},
    [2581] = {n="Комета", d="Двигун Налак'ши захищає безліч могутніх істот - і безліч крихітних."},
    [2582] = {n="Баох-Сі", d="Як на предмет, що багато століть був нерухомий, ця статуя пересувається напрочуд добре."},
    [2583] = {n="Лазуровий вітрошукач", d="Улюблена розвага цього малого хмарного змія - ганятися за власним хвостом."},
    [2584] = {n="Дух джерела", d="Стихійні духи Пандарії, як відомо, готують каверзи для необачних відвідувачів за роки наперед."},
    [2585] = {n="Роїстий Кор'тіків", d="Не дозволяй їм їсти після опівночі: легенда каже, що це дуже небезпечно."},
    [2586] = {n="Бурштиносяйний жалоносець", d="У цілковитій темряві сяйво, що йде від цих жалоносців, водночас заспокоює і трохи лякає."},
    [2587] = {n="Поріддя Ґаралона", d="Кунчонґи надзвичайно агресивні: щойно навчившись ходити, вони пожирають усе, що трапиться на шляху. А чого з'їсти не можуть, те трощать."},
    [2589] = {n="Живий бурштин", d="Мантиди в багатьох справах сильно покладаються на бурштин і навіть використовують його в частині своєї магії."},
    [2590] = {n="Ненажерливий гордин", d="Як поріддя найнебезпечнішого ша, це мале чудовисько має великі плани, та спершу мусить зачекати кілька тисяч років."},
    [2591] = {n="Щастя", d="Ця істота настільки ж лиха, наскільки й чарівна."},
    [2621] = {n="Малий Нефаріан", d="Цей кишеньковий володар Блекрок занадто малий, щоб дошкуляти різним класам, але образити як слід усе ж уміє."},
    [2622] = {n="Дзвіночок", d="Ці сяйливі дитинчата мають неповторний колір луски, за яким уже багато поколінь упадають чинбарі."},
    [2623] = {n="Дотті", d="Хай тебе не вводять в оману м'яка шерстка й великі очі Дотті: її крихітні гострі зубки годяться не лише на те, щоб скубти траву."},
    [2638] = {n="Мінімант", d="Дехто вважає, що силу чаклунові дає борода, але вони помиляються. Уся магія насправді в капелюсі."},
    [2645] = {n="Піщаноклешневий щипач", d="Краби Назджатару, схоже, на диво спокійно сприймають раптове зникнення води."},
    [2646] = {n="Піщаноклешневий сонцепанцир", d="Яскраві панцирі роблять цих крабів легкою здобиччю для хижаків, тож вони здебільшого тримаються в затінку."},
    [2647] = {n="Мерехтливопанцирний скрадач", d="Яскраві панцирі раків-самітників Назджатару змушують ювелірів Азероту аж тремтіти від захвату."},
    [2648] = {n="Тремтоголкове скрадливе мале", d="Тремтоголки видають характерне клацання, коли помічають здобич на видноті."},
    [2649] = {n="Сиплячий тремтоголок", d="«Сипіння» цього краба чути навіть під водою, а насправді це він швидко клацає своїми меншими клешнями."},
    [2650] = {n="Великий морський альбатрос", d="Ці альбатроси трохи менші за тих, що живуть на суходолі, і здатні долати над морем величезні відстані."},
    [2651] = {n="Глибоприпливний мальок", d="Глибоководні скаженці Назджатару здавна є основною їжею наг."},
    [2652] = {n="Кровопивець", d="Декого зі скаженців торкнувся шепіт глибин, і тепер вони прагнуть забарвити води в червоний колір крові."},
    [2653] = {n="Спіральний слимак", d="Тиск нищівних глибин, де живуть ці слимаки, допомагає сформувати їхню неповторну мушлю."},
    [2657] = {n="Чорнопровальний плазун", d="Навіть у безпросвітних западинах і проваллях Великого моря життя все одно існує."},
    [2658] = {n="Тремтоголковий глибинний переслідувач", d="Серед безлічі моторошних істот, що чигають у глибинах, гніздо тремтоголків посідає чи не найвищий щабель."},
    [2659] = {n="Жолобовий слизняк", d="Якщо ти пірнаєш у глибини й один із них присмоктується тобі до ноги, не панікуй -- вони відносно безпечні."},
    [2660] = {n="Багновий слизняк", d="Що тут іще скажеш? Слизняки обожнюють багно."},
    [2661] = {n="Іржокореневий нюхач", d="Нюхачі мають дуже добрий нюх і легко знаходять траву й насіння, заховані під снігом чи мотлохом."},
    [2662] = {n="Сутінкозубий нюхач", d="Темне хутро дозволяє сутінкозубим легше ховатися серед куп брухту на острові Мехагон."},
    [2663] = {n="Звалищний тарган", d="Із усіх створінь Мехагона саме таргани, здається, найменше постраждали від усіх змін."},
    [2664] = {n="Експериментальний тарган", d="Досліди над цим тарганом виростили його до велетенських розмірів. Кому таке могло знадобитися?"},
    [2665] = {n="Прудка жаба", d="Перед лицем механізації жаби Мехагона мали лише два шляхи: ховатися або розмножуватися. Цей вид обрав другий."},
    [2666] = {n="Жовтий мотлохострибунець", d="Перед лицем механізації жаби Мехагона мали лише два шляхи: ховатися або розмножуватися. Цей вид обрав перший."},
    [2667] = {n="Моторизована квакуха", d="Механічні жаби острова Мехагон якимось чином пристосувалися живитися різними механічними комахами."},
    [2668] = {n="Мідний стрибунець", d="Наслідки дослідів короля Мехагона можна побачити всюди — і в місті, і на острові."},
    [2669] = {n="Іржоболтова квокчуха", d="Одні з небагатьох плотських створінь, що лишилися на Мехагоні, вони дають мешканцям Іржоболта їжу й навіть товариство."},
    [2670] = {n="Мехагонський бабак", d="Досліди з механізації змусили нечисленних звіряток, що лишилися на Мехагоні, ховатися або тікати."},
    [2671] = {n="Зразок 97", d="Зразок 97 утік зі своєї клітки, перш ніж його встигли повністю механізувати. Тепер він прагне помсти."},
    [2672] = {n="Сплавлений завулковий пацюк", d="Хоч це й не справжні пацюки, вони захопили задні завулки міста Мехагон і розносять заражені програми — звідси й назва."},
    [2673] = {n="Звалищний тунельник", d="Цим звіряткам запрограмували природний потяг до риття, і тепер вони виконують важливу роботу, розгрібаючи величезні купи брухту."},
    [2674] = {n="H4ND-EE", d="Коли тобі потрібна допомога, ти знаєш, кого кликати."},
    [2675] = {n="Брязкітливий сортувальник брухту", d="Машиністи Мехаґона хоч і автоматизують чимало міських робіт, та все одно багато часу витрачають на ремонт і обслуговування своїх винаходів."},
    [2676] = {n="Несправний мікробот", d="Не пам'ятає, на що його спершу запрограмували, — просто хоче битися з іншими улюбленцями."},
    [2677] = {n="Сутінковий дракончик", d="Поява дракончиків поблизу Грім Батола непокоїть червоний драконяча зграя — щось коїться в загубленому місті."},
    [2678] = {n="Безодняне ковзне мале", d="Вугри, що населяють рови та провалля Назджатара, — улюблена пожива багатьох тутешніх створінь."},
    [2680] = {n="Штрикач Занж'ір", d="Майстер штрикати, колоти, штовхати, тицяти й видовбувати."},
    [2681] = {n="Мерґл", d="Плем'я мурлоків, до якого належить Мерґл, — одне з небагатьох, що опиралися поневоленню нагами."},
    [2682] = {n="Пуголовок Некроплавців", d="Легенда каже, що плем'я Некроплавців знайшло некромантію на рунних табличках на дні моря."},
    [2683] = {n="Водоростоплавець", d="Хай тебе не обманює його миловидність: це мале чудовисько штрикне тебе в щиколотки, щойно ти відведеш погляд."},
    [2684] = {n="Мерехтливий діамантовий панцир", d="Рідкісний вид крабів, що трапляється переважно в Назджатарі. Він легко ховається серед буйних водоростей і коралів цих місць."},
    [2685] = {n="Піщаноклешневий шукач гнізд", d="Будь-що може стати гніздом, якщо докласти достатньо зусиль."},
    [2686] = {n="Перламутровий мерехтливий панцир", d="Коли сонце падає на його панцир під правильним кутом, світло розсіюється на тисячу різних боків."},
    [2687] = {n="Сяйливий мерехтливий панцир", d="Подарунок, знайдений одного дня й збережений для особливої нагоди, якщо все колись зміниться на краще."},
    [2688] = {n="Блискучий мерехтливий панцир", d="Подарунок, знайдений одного дня й збережений для особливої нагоди, якщо все колись зміниться на краще."},
    [2689] = {n="Тремтоголковий голкар", d="Рідкісний різновид тремтоголкових із видовженими голками, щоб протинати м'яку плоть і очі."},
    [2690] = {n="Печерноморочний жах", d="Наче темної підводної печери було замало для жахіть, ще й ці створіння тут живуть -- і їм це місце до вподоби."},
    [2691] = {n="Тремтоголковий пожирач", d="Цих огидних крабів вабить запах крові, і вони, схоже, тішаться боєм."},
    [2692] = {n="Безсвітловий причаєнець", d="У печерах без світла яскравий колір панцира аж ніяк не заважає влаштовувати засідки."},
    [2693] = {n="Поріддя Налаади", d="У темному місці, не знаному нікому, морське дно звивається дітьми Налаади, килимом життя і смерті."},
    [2694] = {n="Збожеволілий кровожер", d="У бездонних глибинах за Вічним Палацом розуми губляться в темряві."},
    [2695] = {n="Кинджалозуба лють", d="Лютожери в Назджатарі навчилися триматися великими зграями, інакше їх пожерли б численні хижаки глибин."},
    [2696] = {n="Безіменний восьминіг", d="Вплив прадавніх богів на підводне життя Назджатара годі сплутати: безліч створінь просто блукають бездумними очима Н'Зота."},
    [2697] = {n="Аметистовий м'якопанцирник", d="Замолоду шпилясті равлики вирощують м'якший панцир, який швидко стає для них завузьким."},
    [2698] = {n="Призматичний м'якопанцирник", d="Навіть із м'якшим дитячим панциром молодий призматичний шпилястий равлик виблискує, мов діамант."},
    [2699] = {n="Вологосвітловий слизняк", d="Здається, що яскраве забарвлення цього глибоководного слизняка випромінює м'яке, тепле сяйво."},
    [2700] = {n="Звивайло", d="Бережи свої вуха."},
    [2701] = {n="Морелютий", d="Стихії безперестанку стикаються й б'ються за реліквії, та мало за яку так запекло, як за Камінь Припливу."},
    [2702] = {n="Штормогнів", d="Камінь Припливу здатен підсилити прислужників і шторму, і моря, тож обидві сторони прагнуть ним заволодіти."},
    [2703] = {n="Піскозамок", d="Цю купку оживленого піску весело розминати між пальцями, ось тільки їй це не надто до вподоби."},
    [2704] = {n="Лускатовиводкова гідра", d="Матріархи гідр Назджатару безперестанку крадуть і нищать яйця одна одної, тож ніколи достеменно не знаєш, хто з них вилупиться."},
    [2706] = {n="Солянокам'яний алган", d="Поряд із солянокам'яним алганом тобі пригадається запах моря, змішаний із гнилими водоростями."},
    [2707] = {n="Бруньковий алган", d="Докази незаперечні: алгани розмножуються брунькуванням. Тепер цю суперечку можна вважати остаточно вирішеною."},
    [2708] = {n="Кораловий батожник", d="За сприятливих умов хижий корал Назджатару може рости неймовірно швидко."},
    [2709] = {n="Прудкий вугор", d="Вугри Назджатару — справжні майстри ховатися в численних щілинах і каменях морського дна."},
    [2710] = {n="Потонуле гіпогрифеня", d="Коли хвилі ринули на місто звідусіль, не всім пощастило отримати дар Н'Зота."},
    [2711] = {n="Золотий Снорф", d="Народження надзвичайно рідкісного золотого снорфа було такою дивовижею, що навіть король Мехаґон не зміг змусити себе механізувати свого улюбленого пухнастого друга."},
    [2712] = {n="Снігом'який Гризун", d="З-поміж усіх нюхачів саме в цього найм'якша шерсть. На іронію, він не дуже любить, коли його гладять."},
    [2713] = {n="Затхлошкірий Нюхач", d="Рідкісний нюхач, якого важко відшукати: щоб звити гніздо, він глибоко заривається під вологе листя."},
    [2714] = {n="OOX-35/MG", d="За ці роки початковий прототип пеленгувального маяка зазнав чимало вдосконалень."},
    [2715] = {n="Загублений Робохапач", d="Незрозуміло, кому належала ця рука спочатку, але назад її власник уже не отримає."},
    [2716] = {n="Утилітарна Механокліщ", d="Хоч який зручний цей винахід, його запрограмували геть зневажати жарти про руки."},
    [2717] = {n="Мікробот XD", d="Один із мікроботів, що охороняли місто Растболт, тепер його можна придбати за помірну ціну."},
    [2718] = {n="Мікробот 8D", d="Він просто такий щасливий, що його запрограмували існувати."},
    [2719] = {n="Кісткогриз", d="У жодному разі не дай йому вгризтися тобі в кістки."},
    [2720] = {n="Арахноїдний Метушбот", d="Ніхто не знає, хто створив цих механічних павуків, але ненавидять їх усі."},
    [2721] = {n="Лунке Слизеня", d="Щоб з'їсти гнома, слизу не обов'язково бути великим."},
    [2747] = {n="Огидний Ригайло", d="Сам лише сморід, який ця істота видає, коли відригує, може легко зіпсувати тобі весь день."},
    [2748] = {n="Зіггі", d="Щоразу, коли його жвала ледь помітно вібрують, це означає, що він наслав комусь жахіття."},
    [2749] = {n="Нечисть склепу", d="Шість ніг, дві клешні, безліч очей, тіло в шипах? У цієї істоти є все!"},
    [2750] = {n="Верескуха", d="Собаки чують її наближення з величезної відстані."},
    [2753] = {n="Розпилювач 0D", d="Навіть йому не загасити вогню в моєму серці."},
    [2754] = {n="Примарне драконеня", d="Невбивні дракони — що тут може піти не так?"},
    [2755] = {n="Допитливий Стрибунчик", d="Останнього, хто спробував зазирнути в його крихітну торбинку, більше ніхто не бачив."},
    [2756] = {n="Опромінений елементальчик", d="Коли западе темрява, цей маленький елементаль стане невичерпним джерелом лагідного зеленого сяйва."},
    [2757] = {n="Слизька видра", d="Слизький наліт на цій видрі чудово захищає від сонячних опіків."},
    [2758] = {n="Слизький вугор", d="Вугри й так слизькі. А цей — слизький подвійно."},
    [2760] = {n="Слизький восьминіг", d="Цей маленький восьминіг бризкає слизом замість чорнила."},
    [2761] = {n="Слизький іклозуб", d="Дорослий іклозуб кусає так сильно, що прокушує платинову вудку наскрізь. Бережи пальці."},
    [2762] = {n="Слизький темний мисливець", d="Життя в такій глибині зробило цей вид дуже чутливим до світла."},
    [2763] = {n="Слизький рак-самітник", d="Слиз дає раку-самітнику всередині життєво потрібні поживні речовини, тож за бажання він може роками обходитися без їжі."},
    [2765] = {n="Слизький морський слимак", d="Слизькі морські слимаки лишають слизький слимачий слиз на слизькому морському дні."},
    [2766] = {n="Броньований сейфобот", d="Ходячий сейф, який жбурляє в тебе грошима, — не надто надійне сховище."},
    [2767] = {n="Згарище", d="У Згарища завжди напоготові запас добряче підсмажених зефірок."},
    [2776] = {n="Ріккі", d="Ріккі має хист прослизати в усілякі тісні закутки й вибиратися з них, якщо його як слід підкупити інжиром."},
    [2777] = {n="Ґіллванас", d="Про справжні наміри цієї мурлочки відомо небагато, та її прибічники — одні з найвідданіших."},
    [2778] = {n="Фіндуїн", d="Несподіваний ватажок мурлоків, якому довелося обійняти цю роль після смерті свого батька, Мурджіана."},
    [2779] = {n="Анімовий вірмлінг", d="Навіть найдрібніші створіння Тіньокраю не виживуть без аніми."},
    [2780] = {n="Дейзі", d="Дейзі рухається дуже неквапливо й залюбки прокотиться в тебе на плечах."},
    [2792] = {n="Папі", d="Подейкують, що ці фіолетові метелики прилетіли з місцини, яку звуть Чортовим островом."},
    [2793] = {n="Сонцелюбний пурхач", d="Спершу крила цього метелика не мають певного кольору, але поступово жовтіють, проводячи час на сонці."},
    [2794] = {n="Багряний літун", d="Цей метелик забарвлений у червоне кров'ю своїх ворогів."},
    [2795] = {n="Дженафур", d="Ця кішка відома своєю брехливістю — не зважай на її солодке нявчання."},
    [2796] = {n="Поплямована Порожнечею жаба", d="Витягнуті з жахливого видіння Оґриммара, ці жаби просякнуті енергією Порожнечі."},
    [2797] = {n="Поплямоване Порожнечею щеня", d="Тепер це щеня — не просто клубок хутра й зубів: воно зіткане з хутра, зубів і Порожнечі."},
    [2798] = {n="Чумороджена слиз", d="У Малдраксусі чума має дивну звичку знову й знову знаходити шлях до тебе."},
    [2832] = {n="Мухар", d="Спрага мани невгамовна, та на щастя це мале створіння споживає її зовсім небагато."},
    [2833] = {n="Анубісат, спотворений Порожнечею", d="Псування Н'Зота поширилося на безліч істот, зокрема й на цього маленького анубісата."},
    [2834] = {n="Поріддя рою акірів", d="У рої акірів незліченна кількість істот, і всі вони підтримують всюдисущий Рій-розум."},
    [2835] = {n="Ра'кім", d="Крилаті акіри дуже швидкі та спритні, а їхні крила створюють приємний вітерець теплого пообіддя."},
    [2836] = {n="Око Псування", d="Це моторошне око бачить усіх і завжди, а кліпає лише раз на десять тисяч років."},
    [2837] = {n="Глюп", d="Геть незрозуміло, чи цей слиз від початку мав усі ці очі всередині, чи то просто «недоїдки»."},
    [2838] = {n="Ц'Тулька", d="Це завжди Ц'Тулька. Завжди."},
    [2839] = {n="Заєць, спотворений Порожнечею", d="Лише істота неймовірної могутності могла спотворити таке чарівне створіння… хіба що цей заєць і сам уже наближався до темряви."},
    [2840] = {n="Кіт, спотворений Порожнечею", d="Цей кіт їсть усе — від випадкових недоїдків до дивних сяйливих кубів неймовірної сили. Будь обережний перед його пащею."},
    [2841] = {n="Пацюк, спотворений Порожнечею", d="Останнім часом точиться суперечка про те, чи пацюки, спотворені Порожнечею, кращі чи гірші за чумних пацюків."},
    [2842] = {n="Аномалус", d="Цей слиз лишає за собою слизький слід, сморід якого міг би позмагатися з тушею звіра, що тисячу років гнила в дюнах Ульдуму."},
    [2843] = {n="Жук, спотворений Порожнечею", d="Панцир цих жуків доволі крихкий через вплив Порожнечі, але водночас він на диво швидко відновлюється."},
    [2844] = {n="Сморід", d="Цьому малому щороку десь на тілі виростає ще одне око."},
    [2845] = {n="К'утішка", d="Його щупальця дарують найкращі обійми, які лиш відчував твій мозок."},
    [2846] = {n="Спотворене щупальце", d="Звідки воно взялося, куди прямує? А ти звідки взявся, моторошне щупальце?"},
    [2847] = {n="Гнилодих", d="Драконодихове чилі — ніщо проти смороду, що йде з пащі цієї істоти."},
    [2848] = {n="Тунельник акірів", d="Ці скарабеї акірів — справжні майстри прокладати тунелі крізь будь-який ґрунт."},
    [2849] = {n="Карликовий верблюд", d="Цих карликових верблюдів часто плутають із загадковими фігурками верблюда."},
    [2850] = {n="Проклятий вартовий дюн", d="Цього малого вигнали й прокляли інші вартові Ульдуму, прирікши провести решту життя крихітною, незначущою істотою."},
    [2851] = {n="Лиховісний скрадач", d="Три ноги, дві руки, три очні яблука — зайві про всяк випадок, на надзвичайні ситуації."},
    [2852] = {n="Нефритовий захисник", d="Кілька завзятих рудокопів подалися за нефритовим квіленом у пошуках багатств, та більше про них ніхто не чув."},
    [2853] = {n="Пташеня вітроперих", d="Хоч би що казали тобі юні пандарени, насправді вітроперих журавлів не вкривають пера з вітру."},
    [2863] = {n="Оазисний нищитель Порожнечі", d="Ніхто не знає напевно, що за пил сиплеться з цих метеликів, і всім надто страшно з'ясовувати, що це насправді."},
    [2864] = {n="Сарана, спотворена Порожнечею", d="Навіть деякі комахи піддалися Порожнечі. Вони й справді пристосовуються та виживають за будь-яких обставин."},
    [2865] = {n="Ковзач Порожнечі", d="Особливо чарівно вони виглядають, коли ковзають над водою під повним місяцем."},
    [2866] = {n="Світляк Порожнечі", d="Це сяйво Порожнечі додається до їхнього природного світіння чи заступає його? Цього світ, мабуть, ніколи не дізнається."},
    [2867] = {n="Золотий цвіркотун", d="Золотий цвіркотун зумів зберегти свою бездоганну сутність, попри спроби зіпсувати його з боку ша та сил Н'Зота."},
    [2868] = {n="Експеримент 13", d="Назва натякає, що до цього було проведено ще дванадцять експериментів, менш вдалих, ніж начепити кілька гармат на механічного тигра. Цікаво, якими ж вони були?"},
    [2869] = {n="Кігтик", d="Усе, що потрібне цьому ведмедеві, — свіжі батарейки та зрідка заміна мастила."},
    [2870] = {n="Голосильний батожник", d="Цей батожник прийшов не з чорної лагуни, не з зірок і не з-за місяця. Він просто хоче, щоб ти його нагодував."},
    [2872] = {n="Тіньоколюче маля", d="Магія Порожнечі й велетенські летючі комахи — поєднання, якого ніхто не просив. На диво дієве!"},
    [2878] = {n="Ренні", d="Якби давали бали за капості, які чиниш, телепортуючись туди-сюди в подобі крихітного чарівного вульпіна, Ренні очолив би таблицю лідерів."},
    [2888] = {n="Глімр", d="Мандрівний шукач пригод урятував невеликий гурт мурлоків, що втратили свої домівки, — і так народилася іскра надії."},
    [2889] = {n="PHA7-YNX", d="Натхненні фалінксами Бастіону, інженери змінили конструкцію так, щоб вона стала приблизно на 300% миліша."},
    [2890] = {n="Сонечко", d="Усі собаки потрапляють до Бастіону.\n\nА коти — до Ревендрету."},
    [2891] = {n="Червоніюче павученя", d="Крипти й гробниці Ревендрету — ідеальне місце для розмноження павуків, і виводок Гробопроривача люто захищає захоплену ним територію."},
    [2892] = {n="Зв'язане поріддя Світла", d="Поріддя Світла завжди можна знайти на полях битв, яких торкається світло, хай би якої форми воно набувало."},
    [2893] = {n="Оживлений фоліант", d="Стережися пробуджувати силу знання."},
    [2894] = {n="Обтяжена душа", d="Душа, обтяжена гріхами свого минулого."},
    [2895] = {n="Загублена душа", d="Душа, що зустрілася віч-на-віч із гріхами минулого, блукає, загублена серед недавнього сум'яття Тіньових Земель."},
    [2896] = {n="Первісний болотник", d="Відомо, що твань, з якої постають копачі, часом зливається докупи й здіймає справжній безлад."},
    [2897] = {n="Гнівник", d="Породжені надмірною пихою та гнівом, ці втілення прагнуть іще більшого, щоб підтримувати себе."},
    [2898] = {n="Сира емоція", d="Ці створіння постають у катакомбах під Ревендретом через мерзенні ритуали, що їх там чинять над душами."},
    [2899] = {n="Придворний посланець", d="Кам'яних бісів створили, щоб вони служили посланцями та шпигунами для краю Ревендрет, і ті з них, що належать до Двору Женців, виконують цю роль надзвичайно добре."},
    [2900] = {n="Дал", d="Товариш Чіпа по доставці послань, Дал завжди був пунктуальним — доки одного дня не повернувся зі свого призначеного обходу."},
    [2901] = {n="Спійманий кам'яний демон", d="Замкнений у скрині й забутий на довгі роки, цей кам'яний демон збожеволів від люті й шукає бійки."},
    [2902] = {n="Сутінкове дредвінгове щеня", d="Цей дредвінг — найпоширеніший серед дредкажанів, його можна зустріти по всьому королівству."},
    [2903] = {n="Багряне дредвінгове щеня", d="Дикі дредкажани важко піддаються приручанню. Багряні малюки вирізняються з-поміж родичів своєю невловимістю та витривалістю."},
    [2904] = {n="Фіолетове дредвінгове щеня", d="Рідкісна мутація надала цьому дредкажанові фіолетового черевця, через що він став бажаним подарунком для колекціонерів улюбленців з вишуканим смаком."},
    [2905] = {n="Спритник", d="Спритник трохи менший за інших вульпінів, зате чудово грає у схованки."},
    [2907] = {n="Скеля", d="Кігті вульпіна гострішають самі собою, коли він ходить бруківкою чи будь-якою кам'янистою поверхнею."},
    [2908] = {n="Щебетливий долинний крикун", d="Попри миле ім'я, його щебет — це радше жахливий, моторошний крик, від якого холоне кров."},
    [2909] = {n="Хмаропере пташеня", d="Ці люті крилаті створіння труть дзьобами об тверді поверхні, щоб нагострити їх і налякати ворогів."},
    [2910] = {n="Флуфа", d="Коли хутро Флуфи намокає, воно пахне цитрусами."},
    [2911] = {n="Бурштиновий блискокрил", d="Подібно до того, як кальмар випорскує чорнило, щоб утекти під водою, блискокрил може струсити пилок зі своїх крил і так само зникнути."},
    [2912] = {n="Запорошений спорокрил", d="Метелики Арденвельду здатні нести насіння й коробочки, що в багато разів важчі за них самих, допомагаючи нічним феям в їхніх вічних трудах."},
    [2913] = {n="Пухнастий мерехтливий метелик", d="Мерехтливі метелики насправді зовсім не мерехтять на сонці. Ніхто не знає, хто дав їм таку назву, але йому є за що відповісти."},
    [2914] = {n="Зоряне снове лоша", d="Коли на небі повний місяць, пасма гриви снового лошати починають мерехтіти й сяяти, наче летючі зорі."},
    [2915] = {n="Вербовий Вітерець", d="Коли вітер дме саме як треба й завиває в ущелинах Арденвельду, можна побачити цих лошат, що мчать разом із вітром у захопливому видовищі зграбності й барв."},
    [2916] = {n="Голодний копач", d="Хоч ці гормлінги, можливо, й не найшвидші землекопи, та вони дуже витривалі й здатні долати під землею величезні відстані, перш ніж стомляться."},
    [2917] = {n="Глубер у ролі Ґ'хууна", d="Навіть жахливий Ґ'хуун колись, мабуть, був отаким милим."},
    [2918] = {n="Замазура", d="Ці маленькі слимаки намагаються з'їсти буквально все, по чому проповзають."},
    [2919] = {n="Горм-кореножал", d="Укус цих гормів неймовірно болючий і часто спричиняє тимчасовий параліч навіть у великих жертв."},
    [2920] = {n="Горм-голкар", d="На цьому різновиді гормів більше гострих колючок і шпичаків, ніж у цілій столиці Орди."},
    [2921] = {n="Горм-переслідувач", d="Якщо рахувати, скільки разів за хвилину змахують його крила, можна вирахувати, за скільки часу цей маленький жах тебе вжалить."},
    [2922] = {n="Анімайт-пожирач", d="Ніхто не знає, звідки взялися пожирачі, та припускають, що вони розплоджуються на кількох загублених землях у Межисвітті."},
    [2923] = {n="Перлокрила чапля", d="Голодний крик, який видають ці улюбленці, може позмагатися з будь-яким стражденним зойком, що лунає в Торгасті."},
    [2924] = {n="Тихий бродник", d="Ці мешканці дикої природи Арденвельду іноді сплять, стоячи просто у воді."},
    [2925] = {n="Золоте хмаропере", d="Зграю тероклів називають руном."},
    [2926] = {n="Тероклоре пташеня", d="Молоді тероклори напрочуд вправні мисливці й намагаються здолати здобич, що вдвічі більша за них самих."},
    [2927] = {n="Пурхаюча мерехтлива муха", d="Чомусь ці сині мерехтливі мухи часто бояться води."},
    [2928] = {n="Послужлива мерехтлива муха", d="Мерехтлива муха здатна нести пилку вагою майже до половини власної ваги й при цьому зберігати повну спритність у польоті."},
    [2929] = {n="Яскрава мерехтлива муха", d="Крила мерехтливих мух майже завжди насичені якоюсь пилкою, тож у польоті з них рівним струмком сиплеться блискучий пилок."},
    [2930] = {n="Черепаха мерехтливого ставка", d="Усупереч поширеній думці, харчування черепахи аж ніяк не впливає на колір її панцира."},
    [2931] = {n="Яснолуске маля", d="Цих яскраво забарвлених черепах найрідше можна побачити в дикій природі. Кажуть, що потерти верх її панцира — на щастя."},
    [2932] = {n="Срібнопанцирна черепаха", d="Черепахи понад усе полюбляють всілякі ягоди, хоча їстимуть майже все."},
    [2933] = {n="Соболь", d="Насправді у вульпінів дуже світла шкіра, але неймовірно густе хутро не дає її кольору проступити назовні."},
    [2934] = {n="Золотолапе лисеня", d="Золоті вульпіни сумнозвісні гучним гавкітливим виттям, що лунає над рівнинами Бастіону."},
    [2935] = {n="Чистота", d="Попри дуже тонке хутро, молоді вульпіни зовсім не линяють."},
    [2936] = {n="Мідношерсте лисеня", d="Чим вульпін відрізняється від лиса? Гарне запитання."},
    [2937] = {n="Іржохутре дитинча", d="Зрідка таке дитинча народжується у золотошерстого вульпіна. У зграї це вважають знаком близької біди."},
    [2938] = {n="Позолочений брідник", d="Ці золотопері створіння не несуть золотих яєць — для цього тобі знадобилася б золота гуска."},
    [2939] = {n="Пташеня брідника", d="Якщо дуже дбайливо пригладити їхнє сріблясте пір'я, воно майже перетворюється на дзеркальну поверхню."},
    [2940] = {n="Зжертий брідник", d="Щойно вилупившись, вони мають безбарвне, біле пір'я. Та за кілька тижнів воно розквітає широким спектром прекрасних кольорів."},
    [2941] = {n="Індиго", d="Грива цього крихітного лошати виблискує величним кольором індіго, коли світло падає на неї саме під потрібним кутом."},
    [2942] = {n="Завзяте небесне лоша", d="Мало що буває таким чарівним, як юне небесне лоша."},
    [2943] = {n="Дикий етервірм", d="Ці летючі створіння не лишають пір'я в дикій природі. Якщо ж колись пір'їна відділяється від їхнього тіла, вона на мить яскраво спалахує, а потім зникає з очей."},
    [2944] = {n="Рука Оонара", d="Шал битви і хватка війни досі не покинули кісток Оонара."},
    [2945] = {n="Огрядний Кістоікл", d="У новонародженого кістоікла іклів не видно, але за кілька тижнів вони виростають до розміру, співмірного з його тілом."},
    [2946] = {n="Згубний Кістоікл", d="Ікла цих створінь зрослися з черепом так, що вони не відчувають болю, коли налітають чи врізаються в будь-що."},
    [2947] = {n="Сяйлива павутинниця", d="Яскравий колір сяйливої павутинниці вабить потенційних хижаків, аби ті гналися за нею просто в її тенета."},
    [2948] = {n="Кістоплетене маля", d="Малдраксус повниться могутніми й жахливими створіннями, тож більшість мешканців напрочуд спокійні поряд із місцевими велетенськими павуками."},
    [2949] = {n="Прудкий отрутоплюй", d="Якщо цей вид плює отрутою на свою здобич, то це й досі вважається отрутою — чи просто чимось геть огидним?"},
    [2950] = {n="Хапун", d="Те місце на спині, до якого ніяк не дотягнутися, щоб почухати? Поклич на допомогу цього малого. І проблему вирішено."},
    [2952] = {n="Булькотливий гнійник", d="Бульбашки всередині цих слизьких створінь видають дуже приємний звук, коли нарешті спливають на поверхню й лопаються."},
    [2953] = {n="Сором'язливий Мелвін", d="Одне з перших творінь Марілета, Винахідника Чуми, Сором'язливий Мелвін був надто боязким для тих вимог, які Дім Чуми ставив перед слизами."},
    [2954] = {n="Личинка чумної воші", d="Цей паразит чіпляється до деяких більших звірів Малдраксусу й п'є їхню кров, доки повністю не виросте. Дивно, як звірі цього навіть не помічають."},
    [2955] = {n="Личинка трупної воші", d="Замолоду крив'яні воші доволі м'які, та згодом усе їхнє тіло вкривається твердими пластинами."},
    [2956] = {n="Жадібна личинка", d="Бути вкинутим до ями з личинками крив'яних вошей — болісна доля для тих, хто підвів великі доми Малдраксусу."},
    [2957] = {n="Звивистий хребет", d="Деякі хижаки Малдраксусу збирають хребти як трофеї, і деякі з тих хребтів не припиняють ворушитися навіть тоді."},
    [2958] = {n="Хребет", d="Брак кінцівок це створіння надолужує бадьорим настроєм."},
    [2959] = {n="Мікромант", d="У Малдраксусі марно не пропадають навіть найменші кістки."},
    [2960] = {n="Олія безхребетних", d="Це слиз утримує кістки всередині, чи кістки тримають слиз докупи?"},
    [2961] = {n="Намацувач твані", d="Намацувача твані краще не обіймати. Ці плями ніколи не відпираються."},
    [2962] = {n="Кіготь", d="Кого здолав — того й зший!"},
    [2963] = {n="Му'дуд", d="Душа, що оселилася в Му'дуді, за життя була жорстоким правителем, а тепер прагне запанувати над найлютішим королівством з усіх."},
    [2964] = {n="Гнилокриле дзумкало", d="Зазубрені щелепи цього виду глибоко вгризаються в усе, що він кусає, спричиняючи сильне подразнення."},
    [2965] = {n="Кровожерне павученя", d="На відміну від більшості павуків, що висмоктують з жертви всі соки, кровожер уподобав саму лише кров."},
    [2966] = {n="Серцегрішник", d="Іноді гріхи великих душ настільки могутні, що оживляють саме каміння, на яке їх покладено."},
    [2967] = {n="Дворецький-копач", d="Копачі — це піт (а часом і сльози) Ревендрету, і їхня допомога абсолютно необхідна для того, щоб усе тут діяло як слід."},
    [3006] = {n="Кам'яношкіре жахокриле щеня", d="Цих жахокрилих кажанів створює Каменотеска для Двору Жнеців. Вони прив'язуються до своїх господарів і виростають лютими бійцями."},
    [3007] = {n="Рожевокінчасте павученя", d="Цих павуків упізнають за характерним забарвленням численних ніг, а ще вони відомі вигадливими танцями, якими лякають і збивають з пантелику ворогів."},
    [3008] = {n="Загублене перо", d="Більше не загублене, тож тепер подумує змінити ім'я."},
    [3009] = {n="Граф", d="Угніздившись на теренах замку Нафрія, Граф і гадки не мав, що його скує вічний кам'яний сон."},
    [3010] = {n="Верескун Сінфолу", d="Разом з новими мешканцями Сінфолу кілька цих молодих жахокрилих кажанів супроводжували війська Ренатала в Пащу."},
    [3011] = {n="Кажанчик", d="Угніздившись над Сінфолом, Кажанчик одного вечора прокинулася від музики першого Двору Жарин. Відтоді вона не пропустила жодного."},
    [3012] = {n="Камінчик", d="Покинутий господарем у відлюдній кімнаті, маленький кажан цілі віки спить у камені."},
    [3013] = {n="Личинка крововоші", d="Яка ж бридка речовина вирує всередині цього створіння?"},
    [3014] = {n="Багновий повзун", d="Ховаючись серед очерету біля брудних калюж, молоді багнові повзуни терпляче чекають, коли поблизу з'явиться легка здобич."},
    [3015] = {n="В'янучий повзун", d="Живлячись рештками аніми в спустошених землях Кінцебагна, ці багнові повзуни поволі в'януть, та в зголоднілому стані вони вдвічі небезпечніші."},
    [3016] = {n="Грибчик", d="Це крихітне деревце вкрите дивними спорами, але, схоже, воно зовсім не проти."},
    [3017] = {n="Листолюб", d="Ці паростки ростуть неприродно швидко, якщо дати їм досить аніми, а коли виростають повністю, їхнє листя стає гострим, як лезо."},
    [3018] = {n="Корінчик", d="Поки знайдеться й буде посаджений бодай уламок цього виду, він знову виросте в той самий чудовий вид, яким був колись."},
    [3019] = {n="Стеблик", d="Що б ти не робив, не проси його нести відро води. Ми не говоримо про те, що сталося з тією частиною Тіньових Земель."},
    [3020] = {n="Рунячий стрибунець", d="Цей улюбленець надзвичайно спритний у повітрі й завжди приземляється на лапи, навіть коли його жбурнули саморобною пружинною стрибунометалкою."},
    [3021] = {n="Стрибунець глибоколісся", d="Прихована енергія, що ховається в насінні Арденвельду, інколи наділяє дрібних створінь неприродними здібностями."},
    [3022] = {n="Накопичувач Мерехтливого Гілля", d="Ці створіння здатні вміщати у своїх щоках величезну кількість їжі, щоб легко переносити її між схованками."},
    [3023] = {n="Сер Реджинальд", d="Ніхто до пуття не знає, звідки Реджинальд узяв своє ім'я, але ми знаємо напевно: на жодне інше він не відгукується."},
    [3024] = {n="Жарина", d="Можливо, небеса й випалили частину Ревендрету, але витривалі створіння все ж здатні існувати в цих суворих умовах."},
    [3025] = {n="Карпал", d="Ніхто не знає, чому всі ці кістляві руки — ліві. Куди ж поділися праві?"},
    [3026] = {n="Баштовий мертвотарган", d="Торгаст — це вежа поневірянь і вічної агонії, а отже, ідеальне середовище для цих створінь."},
    [3027] = {n="Сичливий мертвотарган", d="Багато хто запитував, звідки взялися ці створіння і як вони потрапили до Пащі, та жоден з тих, хто їх досліджував, більше не озвався."},
    [3028] = {n="Відсікачка", d="Якщо відрубана рука сама собі аплодує в Торгасті, чи почує її Тюремник?"},
    [3029] = {n="Повзун Пащі", d="Таємничі сили, що оживляють цю рухливу долоню, поки що не видаються аж надто лихими."},
    [3030] = {n="Попелястий жмакальник", d="Іноді краще облишити дивне створіння, яке ти знайшов у загадковому глеку в глибинах Торгасту, у спокої."},
    [3032] = {n="Шалений щур Пащі", d="Його зуби гострі, мов бритва, і прогризуть чи не що завгодно."},
    [3033] = {n="Переслідувач Пащі", d="Ці охоронці Торгасту завжди пильнують, чи немає підозрілої активності."},
    [3034] = {n="Чигун Торгасту", d="Те моторошне відчуття, коли тіні немовби ворушаться і йдуть слідом за тобою, — це не просто відчуття: зазвичай це одне з таких створінь."},
    [3035] = {n="Лавандовий гризун", d="Якщо штрикнути крихітного ґормлінга в бік, він видає дуже приємний, м'якенький звук. Та НЕ радимо штрикати його надто часто."},
    [3036] = {n="Воля Реморнії", d="Реморнія зазнала незліченної кількості зла й гріха і висмоктуватиме силу з будь-якого доступного джерела, щоб живити свої жадання."},
    [3037] = {n="Жах", d="Варто поглянути на одне з таких створінь — і в самій глибині твоєї істоти утворюється бездонна порожнеча почуттів, яку потім сповнює відчуття жаху."},
    [3038] = {n="Невмирущий мертвотарган", d="У цього виду на спині дуже виразний візерунок, завдяки якому його легко впізнати навіть серед нескінченних жахіть Пащі."},
    [3039] = {n="Гниючий щур Пащі", d="З цієї огидної істоти безперестанку злущуються крихітні лусочки шкіри, лишаючи по собі слід і дуже виразний, бридкий сморід."},
    [3040] = {n="Гострокіготь", d="Гострі як бритва кігті завиграшки розривають будь-що, тож із них виходить чудова відкривачка для консервів на крайній випадок."},
    [3041] = {n="Шукач смерті", d="Які ж жахіття бачили ці очі у вежі Торґаст своїм невсипущим, немиготливим поглядом?"},
    [3042] = {n="Пухнастик", d="Вирвати перо в розпорядника вважається таким гріхом, що вартий подорожі до Ревендрета."},
    [3043] = {n="Джиґлз", d="Хоч і не надто пухнастий, цей слизький котик усе одно лишається одним із найчарівніших створінь, які ти бачив."},
    [3044] = {n="Гормлінг Хребтопащ", d="Поки малі, вони мають чарівну мордочку й милі маленькі вусики. А вирісши, отримують гострі як бритва клешні й стають невтомними машинами для поїдання. Що ж, життя сповнене компромісів."},
    [3045] = {n="Райдужний слиз", d="Здається, цей слиз змінює колір тим більше, чим довше на нього дивишся, а тоді раптом наче починає дивитися на тебе у відповідь. Можливо, час відпочити."},
    [3046] = {n="Гнильний ґейст", d="Попри те, що ґейсти зотлілі й мертві, рухаються вони з винятковою швидкістю та спритністю."},
    [3047] = {n="Хребтожук", d="Тебе хребтожукнули!"},
    [3049] = {n="Пульсуюча Личинка", d="Зазвичай вони звичайнісінького білого кольору, та їхня шкіра відбиває все, що вони з'їли, і вкривається чудовими барвистими плямами залежно від перетравлених органів."},
    [3050] = {n="Похмурий скакунець", d="Легенди кажуть: якщо побачиш похмурого скакунця уві сні, тобі судилося битися з ним на смерть."},
    [3051] = {n="Оживлений Круор", d="Ці слизькі створіння видають найдивніші присмоктувальні звуки, коли намагаються вилізти на стіну. У Малдраксусі це загальновідомий факт — з очевидних причин."},
    [3052] = {n="Малий некроскат", d="Куди б не залетіли ці створіння, звідусіль сиплеться дощ отруйних спор, обертаючи дрібних необачних тваринок на моторошний бенкет."},
    [3053] = {n="Місяцем торкнуте мале Нетеру", d="Дивне маля, що вилупилося на Карнизі Нетервінґу. Вважають, що його благословили згасальні місячні енергії Долини Тіньового Місяця."},
    [3054] = {n="Перо архіваріуса", d="Це перо було добрим другом архіваріусові Фейну ще від найперших його днів, та Джаніра вважає, що йому час із ним розпрощатися, бо він прив'язується надто сильно."},
    [3061] = {n="Розпорядливе Пір'ятко", d="Розпорядники, що прагнуть піднятися в розпорядницькому товаристві, знають: треба настовбурчити пір'я, щедро роздавати соки й невпинно ухкати."},
    [3062] = {n="Загублене Пір'ятко", d="Перекази мовлять, що розпорядників створили на поміч мешканцям Бастіону в їхніх вічних обов'язках. Схоже, вони не проти."},
    [3063] = {n="Ларіонський стрибун", d="Ларіони — горді звірі, і кожного, хто заходить на їхню територію, сприймають як виклик."},
    [3064] = {n="Ларіонське дитинча", d="Подорослішавши, ларіон, що зростав поруч з аспірантом, ніколи не відійде від боку свого господаря чи господині."},
    [3065] = {n="Хоробрість", d="Юних ларіонів часто дають аспірантам як ранню перевірку співчуття й лідерства."},
    [3066] = {n="Люсі", d="Люсі, як і всіх котів, відправили до Ревендрету, та вона якось утекла. Коли місцевих копачів про це запитали, ті лише списали все на те, що вона кішка."},
    [3067] = {n="Спригганська пройдисвітка", d="Спригани — підступні вороги, що живуть в Арденвельді й мучать нічних фей. Ця вирішила утнути найзухваліший трюк — приєднатися до тебе."},
    [3079] = {n="Спріґан Зимолистя", d="Вірність сприганів мінлива, мов пори року."},
    [3080] = {n="Зеленаве маля", d="Вирощені в зелених гаях Арденвельду, ці маленькі лиси сповнені есенцією переродження."},
    [3081] = {n="Гнилісна личинка", d="Ці личинки поїдають усілякі матеріали, з яких уже вичерпалася аніма. Вони геть невибагливі."},
    [3082] = {n="Зореміль", d="Крила цього метелика мерехтять, наче зоряне небо над Арденвельдом."},
    [3083] = {n="Зобокажан", d="Якщо улюбленець — суцільна паща, то куди дівається все, що він з'їдає? Некроманти Малдраксуса розітнули безліч таких створінь, але відповіді так і не знайшли."},
    [3092] = {n="Сквіблз", d="Сквіблза створили так, щоб він ніколи не полишав тебе ані на крок."},
    [3097] = {n="Бездоганний аметистовий цяцьковий черв'як", d="Цяцькові черв'яки дуже цінуються на Завуальованому ринку, де ті, чиї самоцвіти мають найменше вад, сягають захмарних цін."},
    [3098] = {n="Мала Гидота", d="Поля битв усіяні частинами Малих Гидот, цілком взаємозамінними, тож зібрати таку істоту докупи зовсім нескладно."},
    [3099] = {n="Наповнений ефірний вірм", d="Наповнені ефірні вірми можуть слугувати переносними батареями аніми, але їх треба привчити не тікати, ледве зачують бій."},
    [3100] = {n="Позачасове механічне драконятко", d="Дракони бувають найрізноманітніших часових різновидів — позачасові, загублені в часі й навіть нескінченні."},
    [3101] = {n="Спритник", d="Спритник прокрався на борт, щоб вирушити до Пащеки. Він не боїться — просто справді хоче трохи побути в твоєму наплічнику."},
    [3102] = {n="Анімітовий виплодок", d="Молодий аніміт швидко росте, якщо його надмірно годувати. Радять згодовувати йому не більше аніми, ніж міститься в одній пересічній душі, на рік — щоб лишався сумирним."},
    [3103] = {n="Мідноспинний ефірний вірм", d="Осяйна луска ефірного вірма відбиває ясне небо Бастіону."},
    [3104] = {n="Рубіновий цяцьковий черв'як", d="Самоцвіти на цяцьковому черв'якові швидко тьмяніють і розсипаються, щойно того вб'ють. Тож здорових черв'яків заможні посередники тримають як коштовних улюбленців."},
    [3105] = {n="Бірюзовий цяцьковий черв'як", d="Цяцькових черв'яків посередники знайшли на невідомому світі, і самоцвіти їхні були такі прегарні, що учасники експедиції невдовзі пересварилися між собою."},
    [3106] = {n="Топазовий цяцьковий черв'як", d="Цяцькові черв'яки не мають природних ворогів, а самоцвіти вирощують, щоб приваблювати пару."},
    [3107] = {n="Ґурґл", d="По всьому Азероту раз у раз відкривають нові види мурлоків — надто вже вони навальні в розселенні й невибагливі в харчуванні."},
    [3108] = {n="Допитливий муркотун", d="Муркотуни полюють на навальних скратів на Заповитому Базарі, проте лишають їх рівно стільки, щоб самим зоставатися потрібними."},
    [3109] = {n="Сріблястий муркотун", d="Муркотуни — традиційні улюбленці посередників, і обидва мають із цього взаємну вигоду, а в культурі посередників без цього не обійтися."},
    [3110] = {n="Штукенція", d="Штукенцію вважають взірцевим муркотуном — мабуть, найкращим за всю історію. А ще він безжальний убивця дрібної звірини."},
    [3111] = {n="Вологий скрат", d="Скрати отруйні, жалкі й напрочуд вологі — усе, чого тільки можна бажати від улюбленця."},
    [3112] = {n="Скрат-сміттяр", d="Скрати — особливо навальний вид: розмножитися здатен навіть один-єдиний скрат, а поїдають вони майже все."},
    [3113] = {n="Рідкість", d="Один посередник так уподобав скратів, що тримав цей рідкісний екземпляр як улюбленця, а на згадку успадкував його сморід."},
    [3114] = {n="Гарматне м'ясо", d="Коли ти зшивач із Малдраксусу і мусиш дати імена цілій купі почвар, часом просто береш найочевидніше."},
    [3115] = {n="Чіпкі рештки", d="Не зовсім живий, не зовсім мрець, лиш голий рукав — і всьому тут кінець."},
    [3116] = {n="Інвазивна дзизкавка", d="Ґорми знаходять спосіб вдертися майже будь-куди, і Паща не виняток."},
    [3117] = {n="Незгасне жало", d="Хоч цей улюбленець і нащадок гормової королеви, що загубилася в Пащі, його, схоже, не торкнулася погана магія Тюремника."},
    [3118] = {n="Метушливий пацюк Пащі", d="Кігті пацюка Пащі здатні нагородити однією з кількох хвороб, що обривають навіть посмертне життя."},
    [3119] = {n="Втрачена кінцівка", d="Уламки душ повняться в Пащі, шукаючи сенсу або кінця своїм мукам. Та декотрі просто хочуть подати тобі руку."},
    [3120] = {n="Хватка жаху", d="Ці зачаровані рукавиці пащеприсяжні використовують, щоб ловити втеклих в'язнів."},
    [3121] = {n="Чіпка латна рукавиця", d="Опирайся скільки завгодно — вона лише стисне міцніше."},
    [3122] = {n="Залізохват", d="Колись був пащеприсяжний настільки мерзенний, що його вбили власні слуги. Та злоба його була такою великою, що уламок його досі живе в цій рукавиці."},
    [3123] = {n="Смертотарган", d="Дикий шкідник, що мешкає в Пащі. Ніхто до пуття не знає, чим він живиться чи нащо існує, але позбутися його не вдається."},
    [3124] = {n="Мерзенний смертотарган", d="Формально кожен смертотарган вважається мерзенним, але ці перевершують усіх."},
    [3125] = {n="Золоте око", d="Бачиш відблиски на воді? У глибинах є не лише темрява."},
    [3126] = {n="Око скорботи", d="Ці очі надіслали, щоб сповільнювати й знесилювати заблукалі душі Пащі, аби їх було легше ловити."},
    [3127] = {n="Чомпі", d="Один із кількох невідрізнюваних улюбленців, усі на ім'я Чомпі."},
    [3128] = {n="Око всевидіння", d="Око Тюремника, знешкоджене, тепер лише всевидюща магічна дрібничка."},
    [3129] = {n="Око винищення", d="Лють, яку Зоваал плекав через своє покаране існування, відлунює в цьому оці."},
    [3130] = {n="Позолочений темний лицар", d="Золоті обладунки цих зв'язаних Жерлом крихкі й легко гнуться -- позолочена броня є покаранням."},
    [3131] = {n="Прислужник Жерла", d="Святилище Панування приймає зв'язаних Жерлом усіх форм, розмірів і ступенів тілесності."},
    [3132] = {n="Морд'ал Вечірня Зоря", d="Безжальний мучитель найдрібніших душ. Дехто каже, що за життя він був відомий як «Термаплаґ»."},
    [3133] = {n="Тура", d="Тура ніколи не говорить, і про неї майже нічого не відомо."},
    [3134] = {n="Боязкий гризун", d="Годі й шукати улюбленця, який би так любив гризти."},
    [3135] = {n="Молодий Гранатогорлий", d="Гранатогорлий качається в яскраво-червоних квітах, щоб посилити свій колір: це і поклик до родичів, і застереження ворогам."},
    [3136] = {n="Кортіанський зразок", d="Оскільки Кортію роздер на шматки Тюремник, ті нечисленні види, що лишилися, треба зберегти в архіві."},
    [3137] = {n="Замшілий ґроміт", d="Колір шкури цього виду рідкісніший на Кортії й допомагає йому ховатися від хижаків. А в цьому випадку — і від зв'язаних Жерлом."},
    [3138] = {n="Свійський ауніанець", d="Приручений вид, доволі спокійний і, схоже, голодний."},
    [3139] = {n="Пожирачик", d="Пожирачі різних видів і ступенів могутності існують по всьому Межипросторі, та завжди шукають аніму."},
    [3140] = {n="Скрегозуб", d="У нього лише два зуби, але обидва налаштовані серйозно."},
    [3141] = {n="Дика трупна муха", d="Яйця трупних мух трапляються в Малдраксусі всюди, тож їх легко прихопити з собою випадково."},
    [3153] = {n="Блимко", d="Блимко щойно вилупився і готовий до пригод, але дорогою йому, можливо, треба буде кілька разів подрімати."},
    [3169] = {n="Архетип зосередження", d="Частина зосередження, частина ядра й ані крихти послідовної чи стійкої форми."},
    [3170] = {n="Резонансна луна", d="Серцевина пісні, що майже згасла багато віків тому."},
    [3171] = {n="Всемогутнє ядро", d="Воно могло б стати чим завгодно. Воно могло б стати *усім*. А поки що воно... ось таке."},
    [3172] = {n="Джорді", d="Важко сказати напевне, адже обличчя в нього немає, але ця істота, здається, тебе вподобала."},
    [3173] = {n="Буфонід-квакун", d="Характерну пісню квакуна буфоніда чути на величезній відстані."},
    [3174] = {n="Архетип відкриття", d="Частина лицьової сфери, частина кубової фабрики, частина вдалої цікавості."},
    [3175] = {n="Муркастраза", d="Виводок-королева малюків-мурлоків, Муркастраза багато років воювала зі своїм заклятим суперником Дезі."},
    [3176] = {n="Норний вомбата", d="Бачили лише щойно синтезованих норних вомбат. Решта, напевно, радо копає собі під землею, і їх більше ніхто не побачить."},
    [3177] = {n="Драккс", d="Драконідне маля — видовище незвичайне, але саме настав час незвичайних речей."},
    [3178] = {n="Архетип руху", d="Одна частина дзьоба, дві частини крил, одна частина невміння спинитися й одна частина небажання спинятися."},
    [3179] = {n="Архетип оживлення", d="Одна частина каміння, дві частини більшого каміння, три частини дрібнішого каміння — і одна частина здатності попри все рухатися."},
    [3180] = {n="Отруйний буфонід", d="Дехто з найвідчайдушніших мешканців Зерет Мортіса вважає отруйних буфонідів справжнім делікатесом."},
    [3181] = {n="Архетип безтурботності", d="Одна частина слизької шкіри, одна частина дужих лап, одна частина голосового мішка й одна частина цілковитого прийняття себе."},
    [3188] = {n="Труб'ул"},
    [3189] = {n="Архетип множинності", d="Одна частина роздвоєння, дві частини роздвоєння, чотири частини роздвоєння... ой."},
    [3190] = {n="Лютий лепорид", d="Одні лепориди лагідні й милі. Інші ж... теж милі."},
    [3191] = {n="Боязкий лепорид", d="Декотрі з найбоязкіших лепоридів живуть глибоко під землею. Вони вибираються назовні лише по їжу, а потім повертаються до своїх нір."},
    [3196] = {n="Пташеня протоптаха", d="Хоч більші протоптахи й полюють на дрібних тварин, пташенята живляться переважно комахами та личинками."},
    [3197] = {n="Архетип Метаморфози", d="Одна частина зябер, одна частина поспіху й одна частина того, чим треба бути цієї миті."},
    [3200] = {n="Багряний протоптах", d="Через своє яскраво-червоне забарвлення багряні протоптахи насилу ховаються від хижаків, а це, за іронією, означає, що знайти їх украй важко."},
    [3201] = {n="Архетип Хижацтва", d="Вісім частин лап. Вісім частин очей. Одна частина павутиння. Одна частина невситимого голоду."},
    [3202] = {n="Тарахнід-переслідувач", d="Декотрі тарахніди воліють чатувати на здобич у засідці. А ці воліють гнатися за нею, знерухомлювати її й пожирати цілою."},
    [3203] = {n="Тарахнід-засідник", d="Коли здобич потрапляє в досяжність цього створіння, назад вона виходить украй рідко."},
    [3204] = {n="Архетип Виживання", d="Трохи панцира. Трохи клешні. І стільки витривалості, скільки знадобиться."},
    [3205] = {n="Металевий скарабід", d="Декотрі дрібніші скарабіди Зерет-Мортісу мають металеві зовнішні панцири для захисту. До того ж завдяки цьому вони мають розкішний вигляд."},
    [3206] = {n="Смарагдовий скарабід", d="Яскраво забарвлений панцир цього скарабіда робить його цікавішим для можливих партнерів. На жаль, це робить його цікавим і для можливих хижаків."},
    [3207] = {n="Архетип Хитрості", d="На три частини розважливість, на одну — небезпека, на одну — макаронина."},
    [3208] = {n="Червоний віперид", d="Характерне червоне забарвлення цих віперидів слугує застереженням для можливих хижаків: «їж на власний ризик!»"},
    [3209] = {n="Королівський віперид", d="Де сідає віперид вагою 350 фунтів? Там, де йому заманеться."},
    [3210] = {n="Зелений віперид", d="Віпериди можуть сидіти нерухомо годинами, мовчки очікуючи на свою здобич."},
    [3211] = {n="Архетип Злоби", d="На дві частини крила, на одну — кинджал, на п'ять — садизм."},
    [3212] = {n="Кровосисний веспоїд", d="Чи то за життя, чи то по смерті — деякі речі однакові всюди. Гидкі кровосисні комахи — одна з таких речей."},
    [3213] = {n="Дитинча вомбати", d="Попри беззахисний вигляд, хижаки часто уникають нападати на молоду вомбату. Достеменно невідомо чому, але багато хто вважає, що річ у милому маленькому носику вомбати."},
    [3214] = {n="Мама вомбата", d="У Зереті Мортіс багато моторошних створінь, та жодне з них не таке моторошне (й водночас миле), як вомбата, що захищає своїх малят."},
    [3215] = {n="Геоменталь, торкнутий Пащею", d="Жодна людина при здоровому глузді ніколи не бачила геоменталя, торкнутого Пащею. І все ж безліч людей таких бачили."},
    [3216] = {n="Амбістанський кусач", d="Амбістанський кусач — одне з найприязніших створінь, яких можна зустріти в Зереті Мортіс... доки воно таким не перестане бути."},
    [3217] = {n="Ауреліда-літун", d="Більшість аурелід Зерета Мортіс задовольняються плаванням, та дехто з них народжений літати!"},
    [3218] = {n="Розлючений пультрид", d="Ніхто не назве цього пультрида «куркою»."},
    [3219] = {n="Хижий гелицид", d="У разі небезпеки гелициди ховаються у свої важко броньовані мушлі. Якщо ж їх дратувати й далі, вони завдають удару нищівної сили."},
    [3220] = {n="Архетип Вдоволення", d="Дві частини крил, одна частина дзьоба, дві частини пазурів і одна частина самовдоволення."},
    [3221] = {n="Безсвітловий мучитель", d="Цей крихітний мучитель Торгаста втішається тим, що карає у вежі кожну душу, яка не здатна на нього наступити."},
    [3222] = {n="Шеллі", d="Хіба ж вона не найсолодший маленький гелицид?"},
    [3223] = {n="Амбистомовий стрілець", d="Амбистоми — створіння прудкі, але боязкі. За першого ж натяку на небезпеку стрілець ховається в найближчу нору."},
    [3224] = {n="Лютий скарабід", d="Червоне забарвлення цього скарабіда дає зрозуміти можливим супротивникам, що з ним краще не жартувати."},
    [3225] = {n="Агресивний птахід", d="Ці птахіди ворожі, але ніколи не злі. Вони насолоджуються кожною миттю кожної битви."},
    [3226] = {n="Мультикурка", d="Геть незрозуміло, що в них такого «мульти»."},
    [3227] = {n="Стабілізований геоменталь", d="Геоментальні витвори Ліхувіма — найвеличніші з-поміж усіх ходячих куп каміння."},
    [3229] = {n="Архетип оновлення", d="Усього лиш грудка драглів, але оновлена знову, і знову, і знову."},
    [3230] = {n="Жахливе желе", d="Воно живиться страхом, та загалом надто миле, щоб самому наганяти жах."},
    [3231] = {n="Протоколючка", d="Саме існування цієї істоти переконливо натякає, що десь є й інші, досконаліші аураліди, побудовані на колючках."},
    [3232] = {n="Стрибучий лепорид", d="Полишені на самих себе, ці лепориди підстрибують високо вгору від найменшого подразника. Іноді вони навіть приземляються як належить."},
    [3233] = {n="Архетип пильності", d="Наполовину фортеця, на чверть очі на стеблинках, на чверть слиз."},
    [3234] = {n="Загрозливий віперид", d="Якщо одні віпериди чатують на здобич у засідці, то цей різновид годинами вистежує свою майбутню вечерю."},
    [3235] = {n="Мікролицид", d="Якщо синтезовані істоти народжуються вже дорослими, навіщо комусь створювати недорослого гелицида?"},
    [3236] = {n="Гномелія Шестернесерце", d="Завзята, дивакувата і трішечки незграбна — справжнісінька гномська інженерка!"},
    [3237] = {n="Е'рні", d="Маленький амбистан, який був то завеликий, то замалий, а врешті — саме впору. Він пішов за тобою додому!"},
    [3242] = {n="Малий Мака'джин", d="Схоже, Бен'джин і Мака'фон не сиділи склавши руки, відколи ти бачив їх востаннє. Мака'джин готовий до пригод, але радо вдовольниться і великою купою зелені."},
    [3243] = {n="Піппін", d="У нього золоте серце. У прямому сенсі. Ці блискучі песики на піку моди серед заможних гномів усюди."},
    [3244] = {n="Дразка'зет Гнівна", d="Багато еонів тому хитрий лоа смерті обманом утягнув цю крихітну прадавню істоту в угоду про вічну службу, тож тепер вона довіку виконує свій обов'язок, червона від люті."},
    [3245] = {n="Корисний майстерняний бот", d="Ім'я «Біпбоп», а слідом слова «Зроблено Тредісом» грубо, але з любов'ю видряпані на нижній пластині цього крихітного бота нерубійського виробу."},
    [3246] = {n="Тезпет"},
    [3247] = {n="Покопок", d="Це не справжній Покопок, а репліка, яку він дав тобі для використання поза Зеретом Мортіс. Її деталі настільки точні, що цілком переконають будь-кого, хто не провів багато часу зі справжнім."},
    [3248] = {n="Ічабод", d="Ічабод почав своє існування як прототип грізних жниварних големів, що тероризують фермерів Вестфолу, та трохи гномської винахідливості зробило так, що тепер він навряд чи кинеться тобі на коліна."},
    [3249] = {n="Малий Урсок", d="Перш ніж стати відомим як один із Диких Богів, Урсок ще ведмежам блукав Ґризлі-Гіллз."},
    [3250] = {n="Егбоб", d="Деяким яструбоступам судилася велич. Іншим судилося бути Егбобом."},
    [3251] = {n="Дзизкуха", d="Деякі види червоних бджіл відомі тим, що живуть самотньо. І все ж ця працьовита бджілка радо знаходить час для тебе."},
    [3252] = {n="Ґаррлок", d="У жилах Ґаррлока тече прадавня горіанська кров. Наскільки відомо, лише крихітний зріст стримує його імперські амбіції."},
    [3253] = {n="Трощокопит", d="Облогова муштра починається рано для кодо-телят, які не вміють стримуватися й трощать усе підряд. Бережи гомілки."},
    [3254] = {n="Вартова Мисливиці", d="Для ворогів невинні очі цієї Вартової приховують смертельну небезпеку Мисливиці, що скрадається й чигає в тінях."},
    [3255] = {n="Жовтець", d="Його рожеві ріжки роблять його душею будь-якого свята."},
    [3256] = {n="Самоцвітне оніксове маля", d="Майстри-ювеліри Драконових островів так відточили своє ремесло, що їхні оздоблені самоцвітами статуї можна оживити. З цим малям, викуваним з обсидіану, краще тепер не жартувати."},
    [3259] = {n="Кудлай", d="Це кроленя миле від кінчика свого ґудзикового носика до кінчиків смертоносних кігтиків."},
    [3260] = {n="Сніжний деревопурх", d="Майже невидиме, це створіння стрибає з дерева на засніжене дерево."},
    [3261] = {n="Вакін", d="Надія, як цей фенікс, постає з попелу розбитих мрій."},
    [3262] = {n="Фіолетова лють", d="Якийсь дуже кмітливий чарівник, чи дракон, чи інша магічна істота вважала себе вельми дотепною, коли вирішила пофарбувати крижаного елементаля у фіолетовий заради надзвичайно вигадливої гри слів. Мабуть, вони мали рацію."},
    [3263] = {n="Потайна жабокачка", d="Виглядає як качка, і пахне як качка, і крякає як качка... а що таке качка?"},
    [3264] = {n="Кристалічний міні-монстр", d="Скалка уламка частинки скіпки шматочка кристала, а походжає так, наче тут усе її. Добре, що ти їй до вподоби."},
    [3265] = {n="Пан Мускоксель", d="Воістину найшляхетніший з-поміж смердючих вівцебиків."},
    [3266] = {n="Чорне слайвернове щеня", d="Над безкраїми зеленими рівнинами й пагорбами линуть слайверни, лишаючи на землі лише крихітні тіні — єдиний слід їхнього шляху небом."},
    [3269] = {n="Лазурова брижориба", d="Як не дивно, ти зустрів цю рибу, коли вона пливла повітрям."},
    [3270] = {n="Щаслива риба Джина", d="Для декого ця риба красномовно оповідає про своє виживання в найтяжчих умовах. Для більшості ж вона каже просто «буль»."},
    [3272] = {n="Колючий заєць", d="Це найприязніше колюче створіння, яке тобі лишень доведеться зустріти."},
    [3273] = {n="Магмовий слимак", d="Якимось чином цьому створінню вдається бути водночас гарячим, кам'янистим і слизьким."},
    [3274] = {n="Альвін Ковадло", d="Коли Альвін сказав, що хоче стати найкращим ковадлом усіх часів, ніхто йому не повірив. Якби ковадла вміли сміятися, саме він сміявся б тепер."},
    [3275] = {n="Каштан", d="Якось Каштан знайшов жолудь, більший за себе, з'їв його цілком і подвоївся в розмірах. Добре, що він не з'їв транкалумпфа."},
    [3276] = {n="Деревопурхач", d="Багато хто намагався тицьнути в милі носики таких створінь. Більшість позбулася пальців."},
    [3277] = {n="Бурштинова деревна літунка", d="Ліси Вічноспівного нещодавно поповнилися цими летючими дрібнюками."},
    [3278] = {n="Фісташка", d="Фісташка дістала своє ім'я саме так, як ти й гадаєш."},
    [3279] = {n="Бронзовий ентузіаст перегонів", d="Ця маленька любителька перегонів не пропустила жодного забігу і не знайшла гонщика, який би їй не сподобався."},
    [3280] = {n="Соромлекрилка", d="Ці невловні створіння славляться тим, що їх важко відшукати, якщо ти не знаєш, де шукати. На щастя, Ганіко підказав тобі, де дивитися."},
    [3281] = {n="Кошлатий оттук", d="Поміж бійками, купанням і забавами в цих оттуків геть напружений розклад."},
    [3282] = {n="Своґлет", d="Гучне відлуння відрижки дорослого горносвоґа чути за багато миль. Тоненький звук відрижки своґлета лунає не так далеко, зате значно мелодійніше."},
    [3283] = {n="Сніголемент", d="Коли відчуєш, як спиною пробігає холодок, не лякайся. Це, певно, лише твій улюбленець-сніголемент."},
    [3284] = {n="Віскук", d="Малі оттуки проводять дні, плаваючи, ганяючись за метеликами й вправляючись у своєму грізному ревінні."},
    [3285] = {n="Любчик", d="У його великих очах ти бачиш власне відображення. А ще бачиш геть усе навколо — настільки великі ці очі."},
    [3286] = {n="Пан Дуделко", d="Його звуть Пан Дуделко за мелодійні звуки, які він видає своїм хоботом."},
    [3287] = {n="Примарне полум'я", d="Сон зі спогаду про вогонь."},
    [3288] = {n="Хоботолумп", d="Хоч їхні крихітні бивні й не надто стають у пригоді в бою, хоботолумпи надолужують це самою лише вагою."},
    [3289] = {n="Відлуння пекла", d="Іскра може стати жариною. Жарина може стати лютим вогнем. Ця істота ніколи не була ані іскрою, ані жариною — вона завжди була лише лютим вогнем."},
    [3290] = {n="Бунбо", d="Він сідає, де лише забажає, та найбільше любить вмоститися на колінах."},
    [3291] = {n="Кудлик", d="Жага бою в Кудлика сягає самих глибин."},
    [3292] = {n="Фенікс-бажанокрил", d="Дехто гадає, що ця істота жевріє, бо палає вогнем. Насправді ж річ у її пекучому погляді."},
    [3293] = {n="Попелокрил", d="Червоний, мов вогні, у яких він народився."},
    [3294] = {n="Джеральд", d="Чи можливо повстати з попелу часу? Джеральд вважає, що так, і його не переконати в іншому."},
    [3295] = {n="Ігнеоїд", d="Ігнеоїд утворюється, коли магма пробивається на поверхню Азероту й насичується темною магією стихій. Так постає істота крихітна, люта й дуже мила."},
    [3296] = {n="Паламантер", d="Цей саламантер хоче стати твоїм найкращим другом."},
    [3297] = {n="Загублений у часі саламантер", d="Цей саламантер зустрів самого себе, заблукавши в часі. Удвох вони кілька годин просиділи на одному камені. Було приємно."},
    [3299] = {n="Відлуння глибин", d="Що поглинули глибини, того ніхто вже не поверне."},
    [3300] = {n="Залізодзьоба качка", d="Хоч багато створінь Драконових островів і є загадковими, качки, мабуть, найзагадковіші з усіх. Звідки вони взялися? Куди прямують? Що замислили? Цього ми, певно, ніколи не дізнаємось."},
    [3301] = {n="Дике каченя", d="Кря."},
    [3302] = {n="Пілот", d="Усе ще вчиться літати."},
    [3303] = {n="Каченя-крижень", d="Чим годувати миле маленьке каченя? Що? Ні, не сиром із крекерами! Крекери качкам шкідливі."},
    [3306] = {n="Кряк-Е", d="Біп. Біп. Біп. Кря."},
    [3307] = {n="Хоробре каченя", d="Це жах, що лопотить крилами над Драконовими островами. Це крилатий кошмар, що дзьобає твої смарагдові сни. Що? Ні, це не Дезвінг, це качка!"},
    [3309] = {n="Зеленава качка", d="Ці прекрасні, невловні птахи мають украй непередбачувані маршрути перельотів, які важко відстежити, тож декотрі дослідники помилково вважають, ніби качок узагалі не існує."},
    [3310] = {n="Відлуння висот", d="У гірському повітрі іній чіпляється за траву, поки насувається буря."},
    [3311] = {n="Супутник-огуна", d="Його очі помічають порух мишачого хвоста за багато миль звідси."},
    [3313] = {n="Степовий тупотун", d="Кожен крок цього створіння стрясає землю. А коли їх біжить достатньо разом, це звучить як шалена гроза."},
    [3316] = {n="Лаббінс", d="Хто тут найгарніше мале чудовисько? Ти!"},
    [3317] = {n="Копитопомічник", d="Хоч таке й трапляється нечасто, але громоящери, як відомо, інколи прив'язуються до кентаврів. І до їхніх близьких союзників. Тобі пощастило!"},
    [3318] = {n="Громоноге теля", d="Коли ці створіння мчать табуном, вони звучать як гроза. А коли вони мчать табуном під час грози, вони звучать як катаклізм."},
    [3319] = {n="Дзявкало", d="Невдовзі після того, як ти прикінчив зогнилу матір цього слайверна, ти на власній шкурі дізнався і звідки в нього таке ім'я, і чому Зон'Воґі попросив тебе про нього подбати."},
    [3320] = {n="Білоус", d="Біле хутро допомагає цим малюкам ховатися в снігу, коли поблизу никають хижаки."},
    [3321] = {n="Чорнопера гніздарка", d="Немає люті страшнішої за лють чорнопера-матері, що боронить своє гніздо."},
    [3322] = {n="Деревогризний пікумен", d="Ці птахи гострими дзьобами та драконоподібними кігтями вишукують здобич на стовбурах і гілках дерев. Вони спілкуються між собою, вистукуючи дзьобами по деревах, і цей звук чути на велику відстань."},
    [3323] = {n="Світлопера", d="У неї світлі пера. Що тут іще додати?"},
    [3325] = {n="Супутник бакар", d="Вірний і лютий, цей бакар — найкращий друг героя."},
    [3326] = {n="Плавуноспинний деревозуб", d="Коли цей деревозуб не пливе собі ліниво за течією річки, він полюбляє ласощі й обійми."},
    [3327] = {n="Сутінковий деревозуб", d="Мисливці цінують цих створінь радше за їхнє товариство, ніж за хутро."},
    [3328] = {n="Крихітний деревозуб", d="Вартує золота, а то й більше. Ці малюки доволі тендітні, зате надзвичайно сміливі. — Боб Бігарт"},
    [3329] = {n="Торкнутий бурею деревозуб", d="Деревозуб із блискавицею всередині? Ну й розряд!"},
    [3330] = {n="Бакі", d="Погризши коріння магічних дерев, ця істота здобула здатність долати сам час."},
    [3331] = {n="Емма", d="Хіба нормально, що в риби є ікла?"},
    [3332] = {n="Патос", d="Ця оборкова рибка — без жодних оборок."},
    [3333] = {n="Берилогрив", d="Воркіни з Драконових островів мають гриви найрозмаїтіших разючих барв."},
    [3334] = {n="Загублене в часі лоша воркіна", d="Цілком можливо, що ця істота старіє навпаки. Щоразу, як ти її бачиш, вона виглядає трохи молодшою."},
    [3335] = {n="Бліде вороквіня", d="Поглянь! Блідий воркін."},
    [3336] = {n="Воркінець-недоросток", d="Він, мабуть, ще підросте. Мабуть."},
    [3338] = {n="Кобальдт", d="Зі спини цієї істоти стирчать гострі кристалічні голки, і все ж вона чомусь хоче, щоб ти її погладив."},
    [3342] = {n="Спірагос", d="Цей малий дракон аж палає завзяттям! Схоже, у нього є чимало справ."},
    [3344] = {n="Самоцвітний сапфіровий дракончик", d="Часом глибоко в самоцвітах, з яких складається ця дивна істота, можна побачити мерехтіння блакитного світла."},
    [3345] = {n="Самоцвітний бурштиновий дракончик", d="Найважче було виліпити дракончику миле кирпате рильце."},
    [3346] = {n="Самоцвітний рубіновий дракончик", d="Торговий принц Ґаллівікс хоче, щоб ти знав: у нього вже є три таких."},
    [3347] = {n="Самоцвітний смарагдовий дракончик", d="У серці цієї істоти спочиває смарагд, насичений магією."},
    [3348] = {n="Первородний штормовик", d="Краплі дощу шмагають навколо цієї істоти з лячною швидкістю, шматуючи все, до чого торкнуться. Знавці кажуть, що найкращий спосіб уникнути ран — дати їй ласощів та трохи попестити."},
    [3350] = {n="Лорд Базілтон", d="Блискучий помічник керівника й учень, лорд Базілтон до того ж полюбляє пхати свого носа в купи всього цікавого."},
    [3351] = {n="Сивохутре ведмежа", d="Ці маленькі ведмеді зазвичай не нападають на людей, але славляться тим, що час від часу цуплять кошики для пікніка."},
    [3352] = {n="Бритвозубе ведмеже", d="Узимку нелегко бути з рудим хутром, зате восени це дуже модно."},
    [3353] = {n="Кам'янопанцир", d="Панцирі цих істот не з каменю в прямому сенсі, але такі міцні, що з тим самим успіхом могли б ним бути."},
    [3354] = {n="Торкнутий штормом оттук", d="Грайливий сплеск від цієї видри добряче тебе шарпне струмом."},
    [3355] = {n="Відлуння печери", d="Породжена необачним застосуванням магії стихій, дрімотна земля пробуджується. І вона розлючена."},
    [3356] = {n="Крейдяна черепаха", d="Попри назву, її панцир насправді набагато міцніший за крейду."},
    [3357] = {n="Лазуровий кристалошип", d="За цими істотами полюють заради гострих кристалів на спині, з яких виготовляють зброю."},
    [3358] = {n="Багряношип", d="Крізь прозорі кристалічні структури, з яких складається тіло багряношипа, тече його кров — саме вона дарує йому неповторне забарвлення."},
    [3359] = {n="Сніголапе ведмежа", d="Дорослий сніголап своїм ревом здатен здригнути цілі дерева. Ведмежаті ж до снаги похитнути хіба невелику гілку."},
    [3360] = {n="Жукогризна черепаха", d="Ця черепаха їсть жуків, як і випливає з її назви, та ти не повіриш, які ті жуки великі."},
    [3361] = {n="Діамантовий краб", d="Вплив магії, мінералів і тиску води зробив цього краба напрочуд гострим на вигляд."},
    [3362] = {n="Сапфіровий краб", d="Ці краби будують собі панцирі з дрібних уламків каменю та самоцвітів."},
    [3364] = {n="Смугастий змієкус", d="Цих створінь вивели для полювання на змій. Завдяки приземкуватому й видовженому тілу змієкуси чудово підходять для того, щоб заганяти змій у їхні ж нори."},
    [3365] = {n="Рожевий стрибунець", d="Більшість яскраво забарвлених жаб неймовірно отруйні. Рожеві стрибунці — інша справа: вони отруйні лише в межах розумного."},
    [3366] = {n="Жаринка", d="Один докучливий маг на ім'я Макґвайр вирішив розвести невелике багаття. Він прикликав полум'я й аж вигукнув: «Воно куди живіше, ніж треба!»"},
    [3367] = {n="Жеврик", d="Температура в осерді жеврика достатньо висока, щоб розчинити будь-що органічне, тож не забудь надягти рукавиці, якщо схочеш його погладити."},
    [3368] = {n="Виплодок тремтливої павутини", d="Хоч як це дивно, та вдача в неї тепла."},
    [3376] = {n="Скалка", d="Народжений із живого каменю. Перекований руками поплічників Вратіона. На жаль, надто крихітний, щоб щось змінити у війні чорних драконів проти джарадинів."},
    [3378] = {n="Магічний гризун", d="Він пробував стримуватися, та магія просто надто смачна."},
    [3379] = {n="Багряне протодраконя", d="Виразне забарвлення цього протодраконяти дуже цінують дресирувальники улюбленців."},
    [3380] = {n="Чорний дрібножук", d="Тижнями ці комахи дошкуляли базовому табору Драконолуски, аж поки Дідусь Вусань не знайшов спосіб ловити їх і використовувати, щоб позбуватися інших, ще набридливіших комах."},
    [3381] = {n="Сірий мармоні", d="За запрошенням і опікою Дока Горішка чимало сірих мармоні стали частими, хоч і не завжди бажаними гостями в базовому таборі експедиції Драконолуски."},
    [3382] = {n="Штормик", d="Ще яйцем цей протодракон дістав удар випадкової блискавки. Минули роки, а блискавка й досі живе в ньому."},
    [3384] = {n="Торкнутий штормом синьопер", d="Дзьоб. Дзьоб. Шок!"},
    [3385] = {n="Торкнутий штормом тупотун", d="Ось чим завжди лякала тебе мати, кажучи, що буде, як ти з'їси траву, у яку влучила блискавка."},
    [3389] = {n="Квакопредок", d="Це не качка твого дідуся! Чи... все ж таки його?"},
    [3390] = {n="Мудре поєднання", d="Крихітна частка могутності титанів і ще менша частка їхнього розміру."},
    [3403] = {n="Синя стрімкокрилка", d="Погана новина — ці комахи хижі. Добра новина — зазвичай вони їдять лише інших комах."},
    [3404] = {n="Поллісвоґ", d="Ці створіння часто покидають свою зграю одразу, щойно навчаються пересуватися суходолом."},
    [3405] = {n="Жива багнюкова маска", d="Найкращий сувенір із драконячого спа у хмарах. От тільки для догляду за обличчям вона вже не дуже годиться."},
    [3406] = {n="Леді Феттерсворт", d="Хай навіть вона запізнюється з шиком, леді Феттерсворт ніколи не пропустить вечірки."},
    [3407] = {n="Розвідник", d="Розвідник прибув на Драконові острови у пошуках пригод і гострих відчуттів. Зустрівши тебе, він отримав і те, й інше."},
    [3408] = {n="Пелюстка", d="Коли клан Кущоборід вирішив справити весілля, саме Пелюстку обрали розсипати квіти. Вона була неперевершена."},
    [3409] = {n="Дух припливу", d="Як хотілося б приплив скорити й хвилі підкорити власній волі. Та в глибині своїй незмінне море нікого не чекає, повне спокою."},
    [3410] = {n="Дух пилу", d="Коли цього духа схопили й прикували до клітки із зачарованого металу, він зумів вигнути й переплавити той метал в обладунок, який носить і донині."},
    [3411] = {n="Дух полум'я", d="Це душа лісової пожежі. Хоч обладунок і тримає її полум'я під контролем, ти час від часу помічаєш, як вона жадібно поглядає на сухостій і висохлий підлісок."},
    [3412] = {n="Дух шквалу", d="Коли цей дух був вітром, він розносив запахи в усі куточки Азероту. Часом від нього й досі можна вловити ледь чутний слід їжі, диму чи бойової різанини."},
    [3414] = {n="Обсидіанове протощеня", d="Знайшовши кладку чорних протощенят, Вратіон узяв їх під своє крило."},
    [3415] = {n="Кабблі", d="Тривала близькість Кабблі до магії часу наділила його силами, що далеко переважають можливості звичайного ведмедя."},
    [3416] = {n="Стривожений фоліант", d="Чи наважишся ти відкрити цю книгу драконячих таємниць?"},
    [3417] = {n="Пінкі", d="Завдяки своєму неповторному забарвленню та бездоганній працьовитості Пінкі піднялася на вершину світу моди довгоступів."},
    [3425] = {n="[DNT] Storm Pet Boss - Rare"},
    [3427] = {n="Блукач", d="Цю істоту зазвичай вважають доволі сумирною, та спробуй лишень тицьнути морквину їй під ніс — і ТИ ТОЧНО перестанеш відчувати свої пальці."},
    [3446] = {n="Вихор", d="Зарозумілий після минулого життя в бурхливих Заборонених Обширах, тужить за добрими старими часами, коли землею правили стихії. Власне, той ще хвалько."},
    [3447] = {n="Тремор", d="Запевняє, що походить із давно загубленого краю, з решток величезного вулкана, та історія ця якась хитка."},
    [3448] = {n="Пожежа", d="Полум'я довкола нього палає сильніше під час бою. Можна навіть сказати, що битви улюбленців його розпалюють."},
    [3449] = {n="Потік", d="Нашорошує вуха, зачувши розмову, бо любить бути в курсі світових подій."},
    [3475] = {n="Нестабільна самохідна скринька з інструментами", d="Нащо пояс з інструментами, коли за тобою може ходити зручний робот! Тільки не штовхай його надто сильно."},
    [3476] = {n="Позолочена механожаба", d="Стара й небезпечна викинута іграшка."},
    [3477] = {n="Калюжострибун", d="Калюжострибуни відомі тим, що поїдають комах майже таких самих завбільшки, як вони самі. За один ковток!"},
    [3478] = {n="Скельна ластівка", d="Скельні ластівки мостять собі гнізда зі зібраних камінців."},
    [3479] = {n="Єллабон", d="Коли ці комахи рухаються роєм, вони скидаються на золотавий туман."},
    [3480] = {n="Кінцекліщ", d="Зазвичай ця істота має брудний вигляд, але часом можна натрапити на таку, що сяє яскраво-червоним."},
    [3481] = {n="Кам'яновус", d="Кажуть, що яскраве світіння вух кам'яновуса — наслідок поїдання магічних сирів. Можливо, цим пояснюється і його вкрай неприємний віддих."},
    [3482] = {n="Бруківкопанцир", d="Слизький, та водночас піщанистий. Поганий би з нього вийшов обід."},
    [3483] = {n="Валуноклик", d="Валуноклики полюбляють влаштовувати затишні гнізда в шафах, черевиках та інших незручних місцях."},
    [3484] = {n="Плитокрил", d="Хоч ці створіння й складаються здебільшого з каменю, вони все одно вміють літати. Дехто пояснює це силою їхніх крил, але більшість погоджується, що це, мабуть, просто магія."},
    [3485] = {n="Порожнистий метелик", d="Не всі метелики прядуть шовк. Ці метелики прядуть брехню."},
    [3486] = {n="Літенґейл", d="Спів літенґейла унікальний серед птахів, бо має наполегливий, рвучкий ритм."},
    [3487] = {n="Скарлапод", d="Оскільки їхні лігва зазвичай розташовані поблизу поселень дроґбарів, ці слимаки і прудкіші, і сильніші за своїх родичів на поверхні."},
    [3488] = {n="Діпріджер", d="У його панцирі палає вогонь, що горить у самому серці світу."},
    [3489] = {n="Сонцесяйна кобра", d="Здається, ніби в її грудях палає крихітне сонце."},
    [3490] = {n="Чорнокрила міль", d="Оскільки їх часто вабить до свічок, ці метелики можуть стати чималою проблемою для кобольдів."},
    [3491] = {n="Арфус", d="Завжди має бути Король Лизання."},
    [3493] = {n="Роланд", d="Якщо Роланд чогось тебе й навчив, то лише того, що дружба має свою ціну.\n\nА ціна ця — гори й гори сиру."},
    [3511] = {n="Блез", d="Наче багаття, тільки воно прагне почухувань."},
    [3512] = {n="Амбре", d="Ніщо не зігрівало серце Амбре, доки воно не знайшло свою ідеальну пару."},
    [3513] = {n="Лазурове своґля", d="Інші жабенята залюбки бавляться, а оце геть засумувало."},
    [3514] = {n="Смарагдове своґля", d="Бути зеленим... не так уже й просто."},
    [3515] = {n="Аннуна", d="Своїм незвичайним забарвленням Аннуна завдячує тому, що харчується самими лише жовтогарячими бабками."},
    [3516] = {n="Багряне своґля", d="Багряних своґлят уважають найученішими з-поміж усіх своґлят, бо ж вони багато читали."},
    [3517] = {n="Бронзове своґля", d="Три роки тому це своґля було цілком дорослою особиною."},
    [3518] = {n="Салат", d="За давніх часів, коли тільки зводили Андермайн, печерних ластівок було вдосталь. Тепер же гоблінське будівництво довело чисельність цих гарних пташок до загрозливо низького рівня."},
    [3519] = {n="Бірн", d="Усередині нього вирує пекельне полум'я. А зовні це щасливе цуценя."},
    [3520] = {n="Нефритовий метушлик", d="Тільки уяви, якими завбільшки мусять бути птахи, що поїдають отаких комах."},
    [3521] = {n="Лорд Стантлі", d="Лорд Стантлі вишукано рано прибуде на будь-яке свято, де подають креветки."},
    [3522] = {n="Дикий лобстрок", d="Насправді він зовсім не дикий, лише трохи буркотливий."},
    [3523] = {n="Чеддер", d="Своє ім'я він дістав через те, що найбільше любить ласувати фондю."},
    [3524] = {n="Лобстрок-пожирач", d="На щастя, пожирає він переважно ласощі для улюбленців."},
    [3525] = {n="Безодній чигун", d="Один чорнокнижник виграв цього малюка на пекельному карнавалі, та він швидко переріс свій акваріум."},
    [3526] = {n="Гострозубий чигун", d="Як і Нелтаріон, ця рибина збожеволіла, дослухаючись до шепоту Стародавніх Тріскунів."},
    [3527] = {n="Чигун Порожнечі", d="Як саме можна плисти крізь порожнечу? Ця істота знає, але не каже."},
    [3528] = {n="Полі", d="Цей різновид жука живиться драконячою лускою. Яскраве забарвлення застерігає хижаків від нападу."},
    [3529] = {n="Ранґо", d="Якби банани росли в печерах, вони були б улюбленою їжею Ранґо."},
    [3530] = {n="Мілог", d="Мілог любить подрімати. А ще смаколики."},
    [3531] = {n="Іржавчик", d="Гострий нюх Іржавчика здатен учути голку в копиці сіна."},
    [3532] = {n="Амадор", d="Амадор має велике серце і любить допомагати людям, особливо дітям і старим. А ще він любить, коли йому чухають живіт."},
    [3533] = {n="Брул", d="Так, це просто камінь, але скільки він може підняти?"},
    [3534] = {n="Джеррі", d="Колись Джеррі був звичайнісінькою кам'яною мишею. Власне, він нею й досі лишається."},
    [3535] = {n="Діамантовий панцир", d="Цих равликів особливо цінують дроґбарські перегонники равликів за швидкість і чудовий вигляд."},
    [3536] = {n="Сором'язко", d="Хоч Сором'язко й не такий прудкий, як деякі інші равлики Печери Заралек, він надолужує це чистою силою."},
    [3537] = {n="Наперсток", d="Подейкують, що він ховає гроші у своїй мушлі."},
    [3538] = {n="Хитрун", d="Через шари кам'янистої шкіри бурштинові панцирники майже невразливі."},
    [3539] = {n="Трояндовий панцир", d="Трояндові панцири славляться неабиякою агресивністю, але прудкістю не вирізняються. Тож якщо зачепиш одного, готуйся, що секунд за п'ять він тебе вкусить."},
    [3540] = {n="Брюле", d="Якимось дивом водночас гарний і огидний."},
    [3541] = {n="Ребристе сланцекрило", d="Як для створіння з каменю, ширяє воно навдивовижу легко."},
    [3542] = {n="Закопчене сланцекрило", d="Ці шкідники відомі своєю буркотливою вдачею та звичкою гніздитися в димарях Андермайну, на превелику досаду місцевих."},
    [3543] = {n="Ненажерливе сланцекрило", d="Це створіння здатне за один прийом їжі з'їсти вдвічі більше за власну вагу."},
    [3544] = {n="Сланцекрило-пожирач", d="Воно навіть не завдає собі клопоту пережовувати їжу."},
    [3545] = {n="Салверун", d="Може, тобі кортить побачити, наскільки змієподібним він буває!"},
    [3546] = {n="Скаарн", d="Скаарн полюбляє згортатися клубком у твоєму рюкзаку."},
    [3547] = {n="Нефритова скельна гадюка", d="Найулюбленіша страва нефритової скельної гадюки — броколі. А втім, вибач. Я це щойно вигадав."},
    [3548] = {n="Аквапо", d="Уся лють моря, вміщена в калюжку."},
    [3549] = {n="Серцешукальна міль", d="Якщо деяких метеликів вабить світло, то цю міль, схоже, притягують теплі й ніжні почуття. Дехто каже, що вислів «метелики в животі» насправді означає навалу серцешукальних молей."},
    [3550] = {n="Глибинна міль", d="Глибинні молі вважаються одними з найрозумніших молей на Азероті. Щоправда, це мало про що говорить."},
    [3551] = {n="Сльозиста міль", d="Усупереч своїй назві, ці молі насправді цілком щасливі."},
    [3552] = {n="Рітро", d="Поки він куняє в кущах, його кривий зуб іноді чіпляється за листок."},
    [3553] = {n="Нелтара", d="Підсилений Чорною Могуттю Адамантії, цей дракончик готовий зустріти будь-який виклик."},
    [3554] = {n="Сенеґа", d="Сенеґа завжди готова поласувати кристалом силових ліній."},
    [3555] = {n="Аксель", d="Аксель полюбляє ганятися за бджолами. Ніхто не знає чому."},
    [3556] = {n="Кромос", d="Кромоса часто можна заскочити за дрімотою в пісочниці."},
    [3557] = {n="Роггі", d="Роггі — той равлик, що ніколи не здається, хай як важко стає."},
    [3578] = {n="Газетяр", d="Газетяр розносить пошту по всіх Драконових островах. Вона така прудка й надійна, що дрібні дірочки на листах, які вона доставляє, нікого не турбують."},
    [3579] = {n="Ісерґл", d="Відома також як Дрімурк, Ісерґл багато довгих років дрімала у Смарагдовому Сні."},
    [3580] = {n="Баа'ліал", d="Відомий також як Володар Брехні, Баа'ліал — справжній майстер ошуканства."},
    [3581] = {n="Частка Назз'уро", d="Світло нової спадщини осяює шлях, який ти прокладаєш."},
    [3582] = {n="Бульк", d="Серце Бульк завжди було більшим за її акваріум, та коли й решта її тіла надто розрослася, їй довелося шукати нову домівку. На щастя, тепер вона може мандрувати з тобою й бачити всі дива світу!"},
    [3588] = {n="Іґґі", d="Міцний і надійний, Іґґі завжди готовий до запеклої битви чи лагідної метафори."},
    [3589] = {n="Рузіона", d="Нова відвага Рузіони означає, що вона може супроводжувати тебе в пригодах! Ніщо в усьому Азероті не здатне її спинити! Навіть качка!"},
    [3590] = {n="Беластраза", d="Бела навчилася трохи смирення, відколи ви познайомилися, тож навряд чи надто командуватиме тобою."},
    [3596] = {n="Каблуй", d="Десять тисяч років, проведених у дрейфі в часовому застої, — це чималенько часу, щоб попрацювати над матеріалом."},
    [3597] = {n="Принцеса Воркістрасза", d="Принцеса Воркістрасза хоче, щоб ти знав: вона цінує те, що ти завітав на її день народження, але твій подарунок її не вразив."},
    [3598] = {n="Жусадорму", d="Тепер, коли Жуса більше не чхає крізь час, він готовий супроводжувати тебе в майбутніх пригодах! Або в минулих пригодах! Або в майбутніх пригодах!"},
    [3599] = {n="Залетгос", d="Залет нетерпляче чекає, коли супроводжуватиме тебе в пригодах. Він уже склав список книжок, які хоче взяти із собою, але Ластак сказав, що можна взяти лише дві."},
    [3600] = {n="Паллібріус", d="Паллібріус — дивовижна книга завдяки своєму багатству арканних знань. А ще завдяки всім рецептам пирогів, які попередній власник нашкрябав на берегах сторінок."},
    [3601] = {n="Посідрісс", d="Посідрісс прагне вирушити з тобою в пригоди, але, може, спершу дати йому подрімати?"},
    [3602] = {n="Сомніус", d="Сомніус славиться своєю здатністю проспати геть усе, окрім вечері."},
    [4253] = {n="Слайві", d="Через швидкість слайвернів ці астральні явища трапляється бачити нечасто. Якщо один із них супроводжує тебе, це добрий знак."},
    [4255] = {n="Колючкоріг-малюк", d="Любить: броколі, гратися й трощити все довкола. Ненавидить: м'ясо, спати й злих охоронців-титанів, які не дають нічого трощити."},
    [4257] = {n="Ґілл'дан", d="Ґілл'дан здобув свою велику силу, випивши кров демона, від чого його луска позеленіла б, якби не була зеленою вже й до того."},
    [4258] = {n="Джиперс", d="Це око бачило незліченні жахіття, а ці ікла, можливо, і самі винні в кількох із них."},
    [4259] = {n="Думрабл", d="Він наче дуже сердитий, але, можливо, просто голодний."},
    [4260] = {n="Вбивчобот 9000", d="ДЕФЕКТНИЙ; ВІДМОВЛЯЄТЬСЯ ВБИВАТИ. ПОЗНАЧИТИ ДО НЕГАЙНОГО ЗНИЩЕННЯ АБО ПРОДАТИ МЕНШ РОЗУМНІЙ ІСТОТІ."},
    [4261] = {n="Обсидіановий військовий дракончик", d="Одержимий війною світ зробив із неї зброю... але зламати її дух їм не вдалося."},
    [4262] = {n="Н'Рубі", d="Ціле життя в служінні Ануб'араку, потім Королю-Лічу, а тепер... тобі!"},
    [4263] = {n="Тобіас", d="З нюхом на таємниці Тобіас готовий стати поруч із найкращими нишпорками."},
    [4264] = {n="Фірн", d="Фірн першим прийде на твоє свято й останнім піде з нього."},
    [4265] = {n="Малюк Морозокрил", d="Відчуй, як холод щипає тебе за пальці ніг! Загроза Азероту, тепер у святковому блакитному кольорі й кишеньковому розмірі!"},
    [4266] = {n="Шквалик", d="Хоч це маля ще не завершило навчання польоту, його грайливість і завзяття вже розквітли сповна."},
    [4267] = {n="Малюк Маґґз", d="Як спадкоємець Володаря Аутленду, Маґґз завжди поділяв родинну любов до насильства та влади. От тільки ласощі для улюбленців він любить ще дужче."},
    [4275] = {n="Пухнатопазур", d="Перше, що ти, мабуть, помітиш у цій істоті, — це її величезні виразні очі. І це помилка. Краще зверни увагу на її гострі, мов лезо, пазурі."},
    [4276] = {n="Фол'я-малюк", d="Тримай його подалі від наплічника, бо інакше він з'їсть усі твої припаси, а потім ляже подрімати."},
    [4277] = {n="Сокогриз", d="Сокогризики завжди готові погратися в хованки з писком."},
    [4278] = {n="Велелінійний олень", d="Це оленятко любить сир, утім, як і більшість оленят."},
    [4279] = {n="Дрімозуб", d="Замолоду цим звіряткам потрібно багато спати. На щастя, наплічники шукачів пригод — чудове місце для дрімоти."},
    [4280] = {n="Смердючок", d="Якщо тобі здається, що скунси Смарагдового Сну смердять огидно, то молися, щоб ніколи не понюхати скунсів Смарагдового Жахіття."},
    [4285] = {n="Сержант Кряколя", d="Коли вороги пролітають над головою, лишається тільки одне — пригнутися."},
    [4286] = {n="Аура", d="Ще змалечку Аура наділа свого чарівного капелюха, узяла кришталевий посох і вирушила назустріч пригодам у незвідане."},
    [4287] = {n="Марення", d="Качка твоєї мрії... а може, й чиєїсь чужої мрії."},
    [4288] = {n="Блулу", d="Якщо колись влаштуєш бенкет просто неба в Смарагдовому Сні, стережися диких блулу. Блулу не вкраде твого кошика для пікніка, зате чемно попросить чогось смачненького."},
    [4289] = {n="Сновидонароджений скарабей", d="Порівняно з дорослим сновидонародженим скарабеєм, цей — менше з двох лих... тобто з двох жуків."},
    [4290] = {n="Сновидокопито", d="Кладучи спати, не забудь покласти трохи трави під подушку, щоб уві сні почастувати цю крихітку смаколиком."},
    [4291] = {n="Плющ", d="Відколи ти врятував її від Лародара, це вдячне оленятко не відходить від тебе ні на крок."},
    [4292] = {n="Меморі", d="Кажуть, що деяким тваринам сняться чорно-білі сни. А цій сняться лише зелені."},
    [4295] = {n="Дрімулько", d="Це створіння проспало б навіть ще один Катаклізм."},
    [4296] = {n="Сонько", d="Колись Сонькові випав вибір: життя у безмежно прекрасних, позачасових снігових полях або життя у теплій домівці зі смаколиками для улюбленців. Ми всі знаємо, що він обрав."},
    [4297] = {n="Кал'анду", d="Цей юний феєричний дракон, врятований від навали Друїдів Полум'я на Смарагдовий Сон, прихилився до тебе -- і до твоєї їжі. Не лишай свої смаколики без нагляду!"},
    [4298] = {n="Зернятко", d="Зернятка зариваються під рослини Смарагдового Сну й гризуть їхнє коріння."},
    [4299] = {n="Пилюк", d="Пилюки порпаються серед коріння великих дерев у пошуках будь-яких дрібних недоїдків."},
    [4300] = {n="Сонливчик", d="Мрій далі. Мрій, доки твоя мрія не справдиться!"},
    [4302] = {n="Блідий дрімозуб", d="Ці створіння живуть у кущах і поблизу дерев, але сплять так міцно, що стають майже невидимими. Якщо хочеш перервати їхні сни, краще приведи друзів."},
    [4303] = {n="Кривозубик", d="Які зубки. Які кривульки."},
    [4304] = {n="Сновидний борсук", d="Бурий сновидний борсук -- рідкісне видовище. А от запах його не такий уже й рідкісний."},
    [4305] = {n="Носик", d="У Носика надприродне чуття на запахи. Воно не краще за звичайне — просто надприродне."},
    [4306] = {n="Елмер", d="Якось Елмер сам-один з'їв цілий торт. До того ж торт був навіть не його."},
    [4307] = {n="Ялина", d="Те, чого Ялині бракує у швидкості, вона надолужує неабиякою впертістю."},
    [4308] = {n="Ялівець", d="Через своє незвичне забарвлення Ялівцю важко ховатися від хижаків у пишному зеленому листі Смарагдового Сну. Тож вона ухвалила мудре рішення — вирушити в мандри з тобою."},
    [4309] = {n="Дрімливий", d="Це равлик? Це сон? А може, це сон сонного равлика?"},
    [4310] = {n="Снорр", d="Дитинчата віверн від природи сонливі. А сни дитинчат віверн — то й поготів."},
    [4311] = {n="Мітці", d="Коли виросте, Мітці хоче правувати санями Великого Батечка Зими, як її славетний тато Мецен. А поки що вона радо вирушає з тобою назустріч пригодам."},
    [4316] = {n="Малий Вратіон", d="Перекажіть їм, що я вільний від батькового божевілля, тож буду вільний і від них. Дайте мені спокій: це моє перше й останнє попередження. — Вратіон"},
    [4402] = {n="Тіле", d="Дід і баба казали Тіле, що то саме вони були мишами, які відкрили Азерот. Ще вони були неперевершеними вигадниками."},
    [4406] = {n="Сержик", d="Коли Сержик не вештається з Гартом Стоунбрю й не виграє змагання в таверні, він залюбки ховається в наплічниках заїжджих шукачів пригод."},
    [4407] = {n="Нелле", d="Хоч дорослі панянки-жуки вміють літати, Нелле для цього ще трохи замала. Та вона однаково радо дріботить поруч із тобою."},
    [4408] = {n="Багсі", d="Селяни часто випускають панянок-жуків, щоб ті боролися зі шкідниками, які загрожують урожаю. Багсі робила це так добре, що вирішила стати справжнім фахівцем."},
    [4409] = {n="Чарівне каченя", d="З усіх відтінків і кольорів каченят, що з'являються навесні, найбільше цінують рожевих. Існує безліч теорій, чому саме так, але річ, певно, просто в тому, що рожевий — це чудово."},
    [4410] = {n="Бітріз", d="Жовтих сонечок часто плутають з іншими жовтими комахами. З Бітріз таке трапляється ще частіше, і вона не розуміє чому."},
    [4411] = {n="Різ", d="Навіть Ніробін, самопроголошений геній найвищого ґатунку, не міг заперечити милоти свого арканного творіння."},
    [4412] = {n="Гап'хе", d="Дивно, як найзарозуміліші й найпихатіші з архіваріусів Азероту примудряються створювати найчарівніших арканних супутників. Можливо, у Ніробіна все ж є м'який бік..."},
    [4421] = {n="Стрибунець", d="Оскільки це її улюблене свято, Стрибунець носить своє вбрання Місячного фестивалю цілий рік."},
    [4425] = {n="Ґламрок", d="Одного дня, після особливо вдалого пограбування, Ґламрок пішов за тобою назад на корабель, відчувши твій гострий хист до пошуку скарбів."},
    [4426] = {n="Бульбашка", d="Звідки беруться всі ці бульбашки? З чого вони зроблені? Можливо, деякі таємниці краще не розгадувати."},
    [4435] = {n="Щасливчик", d="Здається, він не знає, де опинився, але радий тут бути!"},
    [4436] = {n="Покі", d="Голка в оці Покі — не надто зручна мода, але він уже до неї прикутий."},
    [4437] = {n="Глибина", d="Пригнічений усією здобиччю, яку награбував. Він міг би розділити свій тягар, але виявляється, що він трохи скнара."},
    [4450] = {n="Незабутня Річкова Лапа", d="Колись чіпкі й жахливі, річкові лапи без вагань убивали слабших ворогів."},
    [4451] = {n="Незабутній конструкт", d="Зібраний зі шматків і уламків переможених почвар, магії Світла та лише дрібки ностальгії."},
    [4452] = {n="Незабутній виплодок", d="Цей юний дракон — поблякла згадка про оніксійське драконятко, і він вирішив, що хоче піти власними слідами."},
    [4455] = {n="Ниткар Рак-Уш", d="Ой, ну хіба її педипальпи не чарівні?"},
    [4456] = {n="Павукоподібне маля", d="Багатьом павукам після вилуплення доводиться давати собі раду самотужки. На терапії для павуків про це згадують часто."},
    [4457] = {n="Хітиновий землерий", d="Міцні риючі пазурі дають павукам легко пересуватися під землею. Та й нудне ж це життя."},
    [4459] = {n="Моховий стрибун", d="Нарешті спіймав сліпого печерного стрибуна. Двадцять хвилин він безпорадно борсався, а тоді відригнув. Чудовий же з нього супутник!"},
    [4460] = {n="Аратійська курка", d="Цих шовкових курей узяли на борт повітряних кораблів ті, хто покидав Аратійську Імперію, прагнучи здійснити пророче видіння свого імператора."},
    [4461] = {n="Курка Зеленокраю", d="У Голловфоллі важко доглядати курей на вільному вигулі — через усіх цих тіньових чудовиськ і риболюдей."},
    [4462] = {n="Грім", d="Колись його важка хода й люте ревіння справдять його ім'я. А поки що Грім — це згусток милоти й відданості."},
    [4463] = {n="Тиберій", d="Імператорська рись родом із узбережжя далекої Аратійської Імперії, де ці звірі служать громадянам як люті й віддані супутники та їздові тварини."},
    [4464] = {n="Квасолина", d="Пальчики! Ці величезні пухкі подушечки на лапках! Ці величезні подушечки — не для того, щоб їх їсти!"},
    [4465] = {n="Ваніль", d="Ця дорогоцінна рись — затятий прихильник того, щоб нічого не змінювати."},
    [4466] = {n="Аргос", d="Імператорська рись відома впертою й примхливою вдачею, проте надзвичайно віддана тим, із ким встигла заприятелювати."},
    [4467] = {n="Освячений світлячок", d="Сяйво цього освяченого світлячка проганяє темряву — добрий знак для араті, що мешкають у Святолуні."},
    [4469] = {n="Лупас", d="Овва, друже, стривай-но. Ти що, справді хотів прошмигнути повз, навіть не привітавшись?"},
    [4470] = {n="Уп'ладжакс", d="Він трохи лякливий... надто коли йдеться про обличчя."},
    [4471] = {n="Баклажанова рибка-метушунка", d="Це не кальмар і не дитина: рибка-метушунка воліє тримати чорнило при собі, хіба що в найскрутнішу мить."},
    [4472] = {n="Стрибунець тіньоболота", d="Повертати надію тим, хто загубився в темряві, — справа, що має свою заслужену винагороду. Як-от милі друзі-жабенята."},
    [4473] = {n="Пряля", d="Вона спробує закрутитися — це гарний трюк."},
    [4474] = {n="Ануб'Рек'ют", d="Він чує, як тануть маленькі серця. Ану, хутчіш!"},
    [4475] = {n="Тенетник", d="Кулька з павутини! Камінь реальності! Кулька з павутини! Камінь реальності!"},
    [4476] = {n="Свербокус", d="Комаха? Стривай хвильку, ні, це маленький дружній павучок!"},
    [4477] = {n="Зелена рибка-метушунка", d="Така мила за таких розмірів, скромна рибка-метушунка стає справжньою загрозою для кораблів, коли підростає."},
    [4480] = {n="Тіньовий слизнючок", d="Ідеальний улюбленець, якщо ти любиш серед ночі наступити на щось мокре."},
    [4481] = {n="Слиз порожнечі", d="Якщо піднести його до вуха, можна почути шепіт Прадавніх Богів. Достоту як мушлю!"},
    [4482] = {n="Звивистий трансмутаген", d="Хто рано встає, тому черв'як дістається."},
    [4483] = {n="Мерзенний кровокліщ", d="Солодка чорна кров. Вона має смак минулих воєн і воєн прийдешніх."},
    [4484] = {n="Шалений кровокліщ", d="Більшість істот не вважає загуслу кров надто апетитною. А от кровокліщі..."},
    [4485] = {n="Мохуватий слимак", d="Уяви, що повзеш так повільно, аж на спині в тебе виростає мох. Зі мною таке нізащо не сталося б."},
    [4489] = {n="Стрибунка", d="Ой, ну хіба ж не милі ці пухнасті маленькі педипальпи?"},
    [4490] = {n="Пухнастик", d="Наступного разу, коли сидітимеш у темряві й відчуєш, як щось черкнуло тебе по п'яті, не хвилюйся! Це лише Пухнастик."},
    [4491] = {n="Стриб-Стриб", d="Я стрибаю, Джоне. Така вже в мене робота."},
    [4492] = {n="Торочка", d="Якось хтось сплутав Торочку з покладом азериту. Хоча він надто молодий, щоб пам'ятати азерит."},
    [4495] = {n="Стрибунець", d="Поглянь, як Стрибунець плаває, а тоді поглянь, як він бігає. Бездоганна амфібія. Вибачайте, жаби."},
    [4496] = {n="Звивун", d="Цю хитру рибу ще ніколи не ловили на гачок рибалки. Її впіймали зовсім інакше."},
    [4497] = {n="Перевалень", d="Перевальня відштовхнули інші печерні стрибуни, і він провалився крізь щілини, буквально, аж до самого Гарандара. Кажуть, він ходить назирці за тими, кого знайде."},
    [4498] = {n="Чорний плужний черв'як", d="Помітити їх у темряві важко, і ці черви провчили вже не одного шукача пригод, коли той пхав пальці туди, куди не слід."},
    [4499] = {n="Звичайний плужний черв'як", d="Коли ці створіння більші, їх використовують і в бою, і як в'ючних тварин, та такого розміру вони небезпечні хіба що для твоїх кісточок."},
    [4500] = {n="Малий кісткогриз", d="Малий кісткогриз любить тебе, навіть якби ти був черв'яком. Особливо якби ти був черв'яком."},
    [4506] = {n="Фіолетовий спорокус", d="Небезпечні, отруйні спори? А що, як вони ще й фіолетові?!"},
    [4507] = {n="Кровоспора", d="Грибні спори, просочені кров'ю полеглих потвор."},
    [4508] = {n="Смарагдовий спорокус", d="Це скупчення спор зайвого разу вибухнуло в попереднього власника. Можливо, тобі пощастить більше."},
    [4510] = {n="Крилатий арахноїд", d="Це птах! Це гірокоптер! Та ні, постривай, це щось значно гірше. Тікай."},
    [4511] = {n="Отрутокрил", d="Не найоригінальніше ім'я для антигероя. Але обіцяє захопливий кросовер."},
    [4512] = {n="Скедутакс", d="Ця темнопанцирна потвора розкошує в тінях. Саме там до нього приходять найкращі думки."},
    [4513] = {n="Кістковип'я Стовпогнізда", d="Чи можливо пити кістки? Тільки не без позитивного настрою!"},
    [4514] = {n="Світлячок Зів'ялої іскри", d="Зелене сяйво цього світлячка вважають лихим знаком для тих, хто мандрує в темряві."},
    [4515] = {n="Лазурова мерехтлива мушка", d="Кажуть, мерехтіння цих світлячків навіює неприродний і моторошний спокій як мандрівникам, так і хижакам."},
    [4516] = {n="Яскравий світлячок", d="Хоча їхнє світло іноді приймають за сяйво отруйних речовин чи темної магії, і неруби, і араті вважають цих комах моторошно прекрасними."},
    [4517] = {n="Воскогніт", d="Дивом мрій і бажань Воскогніт ожила і злізла з голови кобольда, щоб піти власним шляхом."},
    [4518] = {n="Магмопанцирний повзун", d="Не тримай удома, якщо живеш у дерев'яному будинку."},
    [4519] = {n="Палотрам", d="Стережись! Він суне просто на нас! Поволі!"},
    [4520] = {n="Глибинний п'ядун", d="У глибинах Нескінченного моря чигають дивні морські страхіття. Та не цей хлопчина. Він цілком звичайний."},
    [4521] = {n="Підземна дартожаба", d="Здебільшого живуть під землею, та декотрі віддають перевагу поверхні. Але це вже не моя справа."},
    [4522] = {n="Трогложаба", d="Голос трогложаби, що лунає в глибоких печерах, звучить майже як... регтайм?"},
    [4524] = {n="Стрибунець яскравосмугий", d="Яскраве забарвлення означає: не торкайся. Червоний — це попереджувальне світло природи!"},
    [4525] = {n="Запашне кам'яне ягня", d="Протовівці проводять зими без своїх квітів. Коли змінюються пори року, рівнини сповнюються розмаїттям земляних, солодких пахощів."},
    [4526] = {n="Піщаникова мохововна", d="Ці ягнята залюбки мандрують на пляжі Каз Алґару, щоб спочити в теплому піску."},
    [4527] = {n="Мала Моховинка Рожі", d="Лічить овечок, мріючи про весну."},
    [4529] = {n="Сланцева мохововна", d="Вправні землероджені флористи здатні викладати чудові квіткові візерунки на спинах протовівців."},
    [4530] = {n="Глинистий", d="Найм'якіша і найпухнастіша протовівця з найм'якішого і найпухнастішого ґрунту."},
    [4533] = {n="Кволий кровобатіг", d="Грибні батоги зазвичай люті й хижі. Цей дрібний різновид краще пасує до того, щоб несміливо ляскати кінцівками по такій самій дрібноті."},
    [4534] = {n="Паросток Нічної ферми", d="Ці вкрай руйнівні шкідники відомі тим, що нищать урожай у Голловфолі."},
    [4535] = {n="Загроза примарних капелюшків", d="Привабливі кольори подвійних капелюшків цих грибних створінь принаджують як розумних, так і звіриних жертв."},
    [4536] = {n="Згубопуп'янок", d="Будь ласка, завжди тримайте свій згубопуп'янок на повідку! Вони сумно відомі тим, скільки шкоди можуть завдати незахищеним садам."},
    [4537] = {n="Честер", d="Почасти худа, зла машина для метання свічок. Почасти охочий до пригод вискочень. А загалом — справжній кобольд."},
    [4538] = {n="Кобальтовий рамоліт", d="Величні роги цих звірів викликають заздрість в інших рогатих травоїдних."},
    [4539] = {n="Гранітний рамоліт", d="Земельні скотарі тримають усіляких рогатих звірів задля роботи й товариства. Та жоден із них не такий гордовитий, як рамоліт."},
    [4540] = {n="Алебастровий каменетопт", d="Протобарани лишають по собі кам'яний пил, коли пустують, б'ються чи відпочивають."},
    [4541] = {n="Корінний каменетопт", d="Молоді протобарани полюбляють гратися та вдавати, ніби нападають. А ще полюбляють нападати по-справжньому."},
    [4542] = {n="Худань", d="Обід для одного кобіса — найкращий друг для іншого шукача пригод."},
    [4543] = {n="Сер Шейді Мрргґлтон Молодший", d="Це тіньове створіння ходить за сером Фінлі Мрргґлтоном відтоді, як він натрапив на нього під час однієї зі своїх виправ. Сер Фінлі дуже прихилився до похмурого друга й нелегко з ним розлучиться."},
    [4544] = {n="Тіньова амальгама", d="Ці рої енергії Порожнечі не здатні втриматися у світлі Беледара."},
    [4545] = {n="Глиняний каменетопт", d="Вигнуті роги протобаранів несуть на собі шрами від кожного бойового зіткнення."},
    [4546] = {n="Піщаниковий рамоліт", d="Вони обожнюють пісок. Він шорсткий і лізе геть усюди."},
    [4548] = {n="Маррлок", d="У жилах Маррлока тече прадавня горіанська кров. Наскільки відомо, лише його прагнення довго відпочивати на сонячному пляжі стримує імперські амбіції."},
    [4565] = {n="Триші", d="Вона бачить тебе, коли ти спиш."},
    [4566] = {n="Ворглі Боязкий", d="Може, здатися! Може, скласти зброю!"},
    [4568] = {n="Вупі", d="Доставляє посилки і має чудовий вигляд."},
    [4569] = {n="Малий Манні", d="Як володар усіх лордів кулькових басейнів, Манні править дитячими майданчиками з душею, сповненою забав і пустощів."},
    [4570] = {n="Шкварник Жаротлілля", d="Оце так гостра бджола!"},
    [4571] = {n="Рожевошкірий копач", d="Такий зморшкуватий!! Такий складчастий!!"},
    [4573] = {n="Полохливий нюхач", d="Здатні відчувати коливання й поштовхи майже за кілометр, ці юні кроти зариваються в землю за першої ж ознаки смертельної небезпеки."},
    [4574] = {n="Принюхування", d="Навіть твердий осад не надто складна перешкода для риючих кігтів цих створінь."},
    [4575] = {n="Сніф", d="Має чудовий нюх, щоб усе винюхати!"},
    [4576] = {n="Ґуакамоле", d="Цей нюхач обожнює лайми."},
    [4577] = {n="Жаротлінник Жаромедовий", d="БДЖОЛИ ТЕПЕР У ВОГНІ?"},
    [4579] = {n="Теля Мускусної Лапи", d="Це маленьке яченя набагато лагідніше за більшість своїх родичів. І пахне трохи менш гостро!"},
    [4580] = {n="Зміюшка Астрального Імператора", d="Кажуть, що Астральний Імператор виткав цих створінь із самої матерії зірок. А ще кажуть, що брав він лише наймиліший зоряний пил."},
    [4581] = {n="Рубіноокий оленепанцирник", d="Оленепанцирники прагнуть насильства. Або принаймні вдаваних його зображень."},
    [4582] = {n="Бойовий панцир Рак-Уша", d="Хоч бойові панцирі Рак-Уша вирощували як живі танки для армії Ануб'азала, вони напрочуд ласкаві. Ну хто тут гарний жук?"},
    [4586] = {n="Бурий листоклоп", d="Коли ти розповіси невдалий жарт, він буде поряд, щоб повідомити тобі про це."},
    [4589] = {n="Шквал", d="Грозовий ворон вершника бур не лише граційно мчить крізь шалені вітри, а й здатен прикликати люті бурі, щоб захиститися."},
    [4590] = {n="Спалах", d="Жароворони — найрідкісніші та найагресивніші з воронів-елементалів."},
    [4591] = {n="Тундо", d="Грім дорослого грозового ворона чутно за багато миль. А цвірінькання цієї маленької іскри більше скидається на звук несправного електроприладу."},
    [4592] = {n="Місті", d="На мисі Стренглторну чаїться чимало створінь, які залюбки тебе вбили б. А Місті просто цікаво побачити решту світу."},
    [4593] = {n="Креґлз", d="Це кабанча втекло з Долини Колдрідж у пошуках пригод і, можливо, смачного яблука, якщо пощастить його знайти."},
    [4594] = {n="Даларанська каналізаційна черепаха", d="Це не звичайна черепаха, а справжній герой у напівпанцирі!"},
    [4595] = {n="Малий Полум'єо", d="Малий Полум'єо готовий спопелити дурненьких улюбленців, якщо ті стануть йому на шляху."},
    [4596] = {n="Вірний пес", d="Більше не загублений і не самотній, твій вірний супутник вирішив, що поряд із тобою — найкраще місце на світі."},
    [4597] = {n="Вобблз", d="Ця зачарована воскова фігурка напрочуд жива — її можна сплутати зі справжнім кротом. Якби тільки вона не танула, коли її гладиш."},
    [4598] = {n="Копперз", d="Що для одного героя сміття, те для кобольда — скарб. На жаль, у зворотний бік це не працює."},
    [4599] = {n="Розумохльоб", d="Аж мороз по шкірі, коли уявляєш, на чому засноване це ім'я: на тому, чим він є... чи на тому, що він робить."},
    [4602] = {n="Клавдій", d="Клавдій славиться нещадною прямотою, а ще чудовим співом. Він певен, що твої коштовності мали б кращий вигляд на ньому."},
    [4614] = {n="Ґізмо Чистий", d="За життя Ґізмо й мухи не скривдив. Але після того, як його жорстоко вбили, він тепер замислюється про насильство."},
    [4615] = {n="Паррлок", d="У жилах Паррлока тече прадавня горіанська кров. Наскільки відомо, лише любов до випічки й балачок із друзями стримує його імперські амбіції."},
    [4616] = {n="Зефірка", d="Зефіркові цяцьхробаки мають безліч природних ворогів, адже славляться своєю гумовою текстурою і солодким смаком."},
    [4617] = {n="Шалебот 9000", d="ОСНОВНА ДИРЕКТИВА: ЧИНИТИ ГЕРОЙСТВА.\nБАЖАНІ ГЕРОЙСТВА: ШАЛЕНІ.\nДРУГОРЯДНА ДИРЕКТИВА: СТАТИ ГЕРОЄМ.\nБАЖАНИЙ ГЕРОЙ: ВЕЛИКИЙ."},
    [4618] = {n="Холодобот 9000", d="РЕЖИМ РОЗСЛАБЛЕННЯ: УВІМКНЕНО.\nРІВЕНЬ РОЗСЛАБЛЕННЯ: МАКСИМАЛЬНИЙ.\nВНУТРІШНЯ ТЕМПЕРАТУРА: НИЗЬКА."},
    [4628] = {n="Припливний кролінг", d="Ці малі кролуски, схоже, надають перевагу піщаним мілинам і вологому повітрю численних пляжів островів."},
    [4629] = {n="Бррргл", d="Майстер відволікати увагу, Бррргл може викрасти твоє серце танцем, рибиною чи кількома друзями."},
    [4630] = {n="Ґілл'ел", d="Ґілл'ел склав із себе провід над кланом Морозного Плавця, щоб поєднатися зі стихіями. Його повернення сповнило всіх радості."},
    [4631] = {n="Майстер", d="Залюбки приходить на кожну гулянку з грилем. Йому б тільки смажити, заради всіх ґоблінів!"},
    [4632] = {n="Сплюх", d="Він просто трохи стомився. Він же ще маленький."},
    [4633] = {n="Кудлай", d="Із Кудлаєм треба бути твердим."},
    [4635] = {n="Окуляри", d="Чи потрібні гієнам окуляри? Аж ніяк. Чи має це страшенно крутий вигляд? Неймовірно крутий."},
    [4636] = {n="Дворняга", d="І ще одне... Постався до мого пса з повагою."},
    [4637] = {n="Хвилеріз-мехазавр", d="А потім — вжух! Він вибігає з океану, тупочучи, і як заричить! Раааргх!"},
    [4638] = {n="Багряний мехазавр", d="Він червоний, бо, типу, повбивав стільки лиходіїв! Це все їхня кров! І він ще й палає!"},
    [4639] = {n="Смарагдовий мехазавр", d="Він точно впав у яму з кислотою, але потім повернувся вдесятеро сильнішим! Так круто!!!"},
    [4640] = {n="Міні-Фларендо", d="Та нє! Жовтий — найкрутіший! Він зроблений за зразком оригіналу, який точно віддухопелить ту дурнувату горилу!"},
    [4641] = {n="Ракетокулак", d="І навіть якщо вони дістануться данського пирога, їм нізащо не обійти Ракетокулака!"},
    [4642] = {n="Мега-меха-горила", d="Мега-меха-горила має силу не однієї, а цілих П'ЯТЬОХ горил."},
    [4643] = {n="Крихітка Торк", d="Тато Крихітки Торка ЗАПРОСТО надавав би тату Фларендо."},
    [4644] = {n="Професор Стусан", d="А він такий: Первісний Стусан!!"},
    [4645] = {n="Брухтовоз Брудноводного картелю", d="Купи металобрухту, що тягають брухт."},
    [4646] = {n="Сапер для особистого вжитку", d="Розвага для всієї родини! Робот, що самопідривається, на будь-який випадок!"},
    [4647] = {n="Пан КОПАЧ", d="Спершу його збудував Д-р КОПАЧ, щоб позмагатися з уславленим шукачем скарбів Бранном Бронзобородом. Та з цього нічого путнього не вийшло, тож тепер він просто допомагає."},
    [4648] = {n="Посіпака Парового картелю", d="Нудно тримати горбатого прислужника, що скиглить «так, господарю», коли можна просто завести робота, який робитиме це безкоштовно."},
    [4649] = {n="Бочкотяг Чорноводної компанії", d="Я не проти бути піратом, надто коли маєш отаку штуку, що залюбки носить за тобою грог."},
    [4650] = {n="Представник Венчурної Компанії", d="Так, бос! Так, бос! Так, бос!"},
    [4651] = {n="Хитрий щур", d="Що густіші й довші вуса, то підступніший гризун. Це звичайна біологія."},
    [4652] = {n="Просочений кислотою щур", d="Зупини мене, якщо вже це чув: він упав у чан з радіоактивною кислотою."},
    [4653] = {n="Лабораторний щур", d="Вони не брехали — цей щур таки дістане той клятий сир."},
    [4654] = {n="Підземний тарган", d="Науковці, інженери та гравці Андермайну мусять тримати свої столи чистими, бо інакше до них завітають підземні таргани."},
    [4655] = {n="Хрумкач", d="Ці колючі ніжки! Ці тремтливі вусики! Гаразд, він не милий. Але ж він старається!"},
    [4656] = {n="Краб-бомба", d="Природне середовище цих крабів настільки забруднене й позбавлене мушель, що вони змушені ховатися в покинутих ґоблінських боєприпасах. Чи й далі смітитимеш, дізнавшись про це?"},
    [4657] = {n="Бомба Венчурної Компанії", d="У скруті робітники Венчурної Компанії можуть пускати цих створінь на імпровізований підрив. Второпав? У скруті, бо вони хапаються клешнями?"},
    [4658] = {n="Печерний краб", d="Зариваючись у пісок та намул, ці краби чудово зливаються зі своїм оточенням."},
    [4659] = {n="Каджа-краб", d="Чи він забагато часу провів біля каджаміту? Чи хтось дав йому каджа-колу? Хтозна, але назва — чудовий бренд."},
    [4660] = {n="Краб із блідим панцирем", d="Кажуть, що печерні краби з блідим панцирем — найсмачніший різновид. Можливо, тому їх і найважче знайти."},
    [4661] = {n="Мехаховрах", d="Чи бачиш ти жаль у цих мерехтливих, бездушних очах? Я так і думав, що ні."},
    [4662] = {n="Шкідник MK II", d="До версії MK II Шкідники були жалюгідною подобою набридливого й переускладненого паразита. А тепер? Тепер вони геть нестерпні!"},
    [4663] = {n="Лаймовий робокурчак", d="Кислотно-зелені акценти додають спортивного шику цій нелетючій роботизованій пташиній штукенції."},
    [4664] = {n="Залізна курка", d="Їй байдуже до киплячої олії та одинадцяти таємних трав і спецій. Тільки не знайомте її з іржею."},
    [4666] = {n="Тропічна жаба", d="Нещодавні розкопки в Зулдазарі знищили природне середовище цих створінь, і вони розповзлися по диких краях."},
    [4667] = {n="Пружинний Квакотрон", d="Роботизована жаба може здаватися марною, та щойно на тебе нападе рій механічних мух, ти пошкодуєш, що не маєш такої."},
    [4668] = {n="Ультрастрибун EX", d="Швидший. Сильніший. Та ще й уміє стрибати двічі."},
    [4669] = {n="Блюду", d="Магія Блюду та його вправність в акупунктурі допоможуть кожному, хто потребує розслаблення."},
    [4678] = {n="Малий Думі"},
    [4679] = {n="Малий Каз"},
    [4682] = {n="Ревен", d="Гра почалася! Окрім хвилин, коли час подрімати. А потім — гра знову в розпалі!"},
    [4684] = {n="Дерев'яне небесне змієня", d="Це майже як дерев'яна іграшка, що ожила. Тримай цього улюбленця подалі від дітей."},
    [4686] = {n="Привид", d="Знайдений таунками ще новонародженим цуценям, Привид безмежно відданий. Та він починає виправдовувати своє ім'я, скрадаючись у світ."},
    [4689] = {n="Сифонник Каражану", d="Сифонників рідко вдається спіймати живими — це одні з найнебезпечніших манавирмів. Цей просто відволікся, поки об'їдався особливо смаковитою книгою заклять у бібліотеці Каражану."},
    [4690] = {n="Разеші Б.", d="Разеші Б. відома своїм запальним норовом, гострим розумом і ще гострішими шпильками. Літера «Б.» означає «Бережись краще»."},
    [4691] = {n="Ґранч", d="Краще не питати, як Ґранч роздобув усі ці подарунки, бо ти й сам знаєш — точно не за гарну поведінку."},
    [4692] = {n="Іскроклац", d="Те, що ти прийняв за купу награбованого добра, виявилося обвішаним скарбами панциром Іскроклаца. Випадково почухавши йому спину, ти здобув завзятого супутника, що тепер скрізь ходить за тобою."},
    [4693] = {n="Алхімічний стік", d="Витоки з лабораторії часом небезпечні. Часом — милі. А часом — і те, й інше!"},
    [4694] = {n="Лиховісний подарунок", d="Колишні власники цієї скрині розповідали, що з їхньої колекції зникали інші улюбленці."},
    [4695] = {n="Парлі", d="Парлі — доволі серйозний і буркотливий птах. Якщо тобі дорогі твої очі, краще не питай, чи не хоче Парлі сухарика."},
    [4701] = {n="Плямка", d="Людей часом перетворюють на щурів. Не таке вже й дивне діло."},
    [4702] = {n="Іржавий кролінг", d="Колись захищені густими лісами острова, ці менші й не такі агресивні кролуски мусили швидко пристосуватися до своєї нещодавно вирубаної домівки."},
    [4703] = {n="Печерний кролінг", d="Як і багато видів кролусків, цей різновид, схоже, віддає перевагу мережі підземних печер острова."},
    [4704] = {n="Жива троянда", d="Коли нею милуються, жива троянда випускає прекрасні п'янкі аромати. Коли ж її ігнорують, ці аромати стають по-справжньому отруйними."},
    [4708] = {n="Мармадюк", d="Хоч його й покинули на Острові Сирен, цей старий, але дуже гарний пес доводить, що дещо з віком тільки кращає."},
    [4710] = {n="Пограбований папуга", d="Цей чудовий ара опинився страшенно далеко від дому й шукає товариства супутника, гіднішого за своїх колишніх «господарів»."},
    [4711] = {n="Цуценя ротатого дракона", d="Кажуть, що укус цуценяти ротатого дракона в багато разів сильніший і небезпечніший, ніж у дорослих особин."},
    [4717] = {n="Мандрівник Лю", d="Як і більшість юних меексі, Лю має хист знаходити і халепи, і пригоди. Та на відміну від інших меексі, Лю здатен телепортуватися на величезні відстані в пошуках і того, і іншого."},
    [4718] = {n="Заводний Вуффі", d="З таким милим личком Вуффі певен, що ви неодмінно станете найкращими друзями."},
    [4719] = {n="Заводний гавкун", d="Помах його хвоста завжди викликає усмішку на твоєму обличчі, наче за годинником."},
    [4723] = {n="Скелелазне дитинча", d="Ці маленькі дитинчата настільки ж завзяті, наскільки й лагідні."},
    [4724] = {n="Бойове кабанча", d="Ці молоді кабани, яких від народження суворо муштрують, їдять, б'ються і сплять у своїй броні."},
    [4726] = {n="Тріскорев", d="На це маленьке дитинча вплинули невпинні шторми на острові Сирен. Варто погладити його м'яке хутро, як по руці пробігають іскри статичної електрики."},
    [4727] = {n="Дряпокус", d="Здається, цей кролуск виявляє надзвичайний для свого роду розум, що зблискує в його яскравих червоних очах."},
    [4728] = {n="Приборкувач чайнолистів", d="Приборкувачі чайнолистів із племені мікс полюбляють після довгого лінивого дня відпочивати зі своїми чайнолистами та смакувати чашку містичного чаю."},
    [4729] = {n="Повночерев Котолап", d="Повночереви з племені мікс часто ризикують власною безпекою, варто їм лише занюхати їжу. Ніщо не тішить їх так, як чашка чаю та теплий обід."},
    [4730] = {n="Механодрузка Майя", d="Знайомся зі своєю новою найкращою механодрузкою Майєю. Майя любить, коли її гарненько та міцно заводять, щоб вона могла кинутися в дію."},
    [4731] = {n="Просочений штормом ротатий дракон", d="Дитинчата ротатих драконів, покинуті на узбережжі, просочилися енергіями Бурі Морської Люті, як і інші створіння острова Сирен."},
    [4732] = {n="Ротатий дракон-падальник", d="Кажуть, що ротаті дракони незалежні від батьків від миті, коли вилуплюються, хоча нещодавня виправа до Назжатару, схоже, спростувала цю теорію."},
    [4733] = {n="Веселість", d="Ця істота настільки ж лиха, наскільки й чарівна."},
    [4747] = {n="Око Хаосу", d="Стільки років очі й вуха Матіаса Шоу збирали відомості по всьому Азероту. Тепер принаймні дещиця тих очей повернулася додому."},
    [4748] = {n="Папуга, зранений Порожнечею", d="Через аукціонний дім Торгового кварталу Стормвінда проходить безліч товарів і тварин. Колись папуги Танглторну були дорогою розкішшю. Тепер ті з них, хто опинився поряд, коли владу захопив Н'зот, стали справжньою напастю."},
    [4749] = {n="Скорпід, зранений Порожнечею", d="Істота, яку розбійники цінують за її отруту. Чимало їх жило в численних норах і лабіринтах Завулку, та після падіння ці нові жахіття вийшли назовні, щоб загрожувати тим, хто вцілів."},
    [4750] = {n="Пташеня високоступа, зранене Порожнечею", d="Високоступи, яких рідко вирощують у неволі, надзвичайно ревно бережуть свою територію. Під час полювання знайшли невелику кладку яєць, і таврен-приборкувач привіз їх до Оґриммара, щоб показати всім. Та після падіння вони знову стали смертельно небезпечними. Досі нікому не вдалося опанувати їхні зіпсуті подоби."},
    [4756] = {n="Бич Аспектів", d="Бича Аспектів зжирає лють, і він сповнений жаги поглинати. Його поява — це знак непередбачуваного й хаотичного майбутнього для будь-яких драконідів."},
    [4757] = {n="Фрумпі М'якша", d="Ці буркотливі, надуті мікси, здається, тішаться лише тоді, коли п'ють чай боба з молоком, солоною карамеллю й тістом для печива."},
    [4759] = {n="Крабум", d="Маленький, кусючий, з норовом таким же вибуховим, як і його ім'я. Поводься обережно!"},
    [4761] = {n="Паскаль Чудо-Цуцик", d="PH - Tech was made to allow customizations."},
    [4762] = {n="Ток, годинниковий спанієль", d="Ток, годинниковий спанієль — найкращий сторожовий пес, якого тільки можна побажати."},
    [4790] = {n="Ненажерливий вилупок", d="Зголоднів? Спробуй з'їсти своїх ворогів!"},
    [4791] = {n="Тррртгл", d="Тррртгл цілком задоволений тим, що він не найкращий вибір і навіть не другий за чергою. Тррртгл переконаний, що перше й друге місця — найгірші, а третє — найкраще."},
    [4792] = {n="Ада Найсолодша", d="PH - Tech was made to allow customizations."},
    [4793] = {n="Вічі", d="Вічі обожнює увагу, а що краще привертає увагу, ніж костюм? Просто знайди станцію догляду за улюбленцями біля будь-якого Торгового Посту й причепури цього милого, дивовижного малого приятеля."},
    [4794] = {n="Містер Манс", d="Зважаючи на його буйну вдачу, можна лише припустити, що він просякнув Порожнечею, затіявши бійку. Лишається питання: хто переміг?"},
    [4795] = {n="Плазун Порожнечі", d="Народжений у хаосі та пилі Войдшторму. Він навіть ненавидіти ще не навчився!"},
    [4796] = {n="Благословенний Са'бака", d="За віруваннями тол'вірів, гніздо крокіліска, що вилуплюється під час Свята Сонця, вважається благословенним хранителем річок Са'баком."},
    [4801] = {n="Крихітка", d="Більшість скверноловів люті й ненаситні. Цей, однак, схоже, трохи самотній."},
    [4802] = {n="Кусник", d="Відомий тим, що норовить вкусити свого власника. Гладь обережно."},
    [4803] = {n="Гризунчик", d="Час від часу світиться зеленим."},
    [4804] = {n="Прудколапий", d="Дитинча Полум'якігтя й звитяжний гонець Сяйва Полум'я. Прудколапий служить Священному Полум'ю ще завзятіше, ніж дехто з аратійців."},
    [4806] = {n="Гостра злюка-кулька", d="Оце так гостра, злюща кулька."},
    [4811] = {n="Надієкрил", d="Хоч би куди він прямував, він лишає по собі м'яке сяйво, що пробуджує надію навіть у найтемніших місцях."},
    [4812] = {n="Лиховір'я", d="Він ширяє в повітрі на тінистих крилах, лишаючи по собі шлейф моторошного шепоту."},
    [4813] = {n="Ікстал Спостерженя", d="Ікстал залюбки грає у схованки, коли не розмірковує про те, як Порожнеча поволі пожирає цілі світи."},
    [4816] = {n="Пташеня соколоступа", d="Коли ж пташеня стає підлітком, якщо соколоступи ніколи не вчаться літати?"},
    [4825] = {n="Веридіановий Колючохвіст", d="Найбільше це маля колючохвоста полюбляє хлюпатися в дрібних калюжах."},
    [4826] = {n="Забіякуватий Колючохвіст", d="Це мале колючохвостеня обожнює встрягати в бійки зі своїми найзлішими ворогами — колінними жучками."},
    [4827] = {n="Жахливе Страховидло", d="Перші спроби вписати їх в екосистему скінчилися тим, що кількох особин спопелили поглядом."},
    [4828] = {n="Безсторонній споглядач", d="Нудьга цього споглядача така ж вічна, як боротьба між Світлом і Порожнечею."},
    [4829] = {n="Сутінковий жах", d="Він вичікує й спостерігає з тіней. Тихо. Тихо."},
    [4830] = {n="Рхай'Дар", d="Завжди насторожі, ніколи не кліпає."},
    [4832] = {n="Глядач Ґаз'крет молодший", d="Його ще не вважають достатньо проникливим, щоб стати Споглядачем, та він видивляється тих, із ким міг би поділитися своїм видінням."},
    [4833] = {n="Ксантовий Кліщ-сифон", d="Кліщі-сифони зазвичай живляться енергією світів, що вмирають, але цей цілком задоволений і тим, що його чухають дослідники."},
    [4834] = {n="Джиммі", d="Справжнє ім'я Джиммі — Морґіліто, Поріддя Морґіла, Заклятий Ворог Тазавеша, Пожирач К'ареша… але всі просто звуть його Джиммі."},
    [4835] = {n="Блакитний Кліщ-сифон", d="Як цей кліщ-сифон прокрався до контейнера стазису — годі й здогадатися."},
    [4836] = {n="Їдкий Дюймозмінювач", d="Хто б міг подумати, що ці створіння здатні стільки з'їдати?"},
    [4838] = {n="Палек'ті, Паща Небуття", d="Усе ще замалий, щоб полишити гніздо."},
    [4839] = {n="Мерехтливий Дюймозмінювач", d="Розрахунки показали менш ніж однопроцентний шанс успішної інтеграції, та це створіння надто миле, щоб його знищувати."},
    [4840] = {n="Граційне космічне рохенятко", d="Спроби приборкати найруйнівніші нахили цього виду зробили цей екземпляр сумирнішим за більшість інших, але все одно успіху досягти не вдалося."},
    [4841] = {n="Зоряне сяйво", d="Шукає світло зірок. Навіть удень."},
    [4842] = {n="Сутінковий злодій", d="Тягнеться до блискучих речей. І до темряви. Особливо до темряви."},
    [4843] = {n="Сао'рон", d="Дуже приязна космічна істота. Прямий погляд в очі знищить твою душу."},
    [4844] = {n="Допитливе космічне рохенятко", d="Це космічне рохенятко цікавиться безліччю речей. Не дай йому вскочити в халепу (знову)!"},
    [4845] = {n="Пан Довгоніг", d="Улюбленець якоїсь бідолашної душі ще до падіння К'ареша, знайдений ув'язненим у застиглому стані."},
    [4846] = {n="Гека'Тарнос, Сівач Розбрату", d="Поклику цього винятково галасливого колінника вистачило, щоб і без того хиткі стихії довкола поринули в цілковитий хаос. Тепер твоя черга страждати від цього дзижчання."},
    [4847] = {n="Мідний Колінник", d="До падіння К'ареша колінників високо цінували як свійських улюбленців. Мідні колінники користувалися особливим попитом."},
    [4848] = {n="Лазуровий Колінник", d="Лазурових колінників високо цінували як улюбленців і вважали, що вони приносять удачу."},
    [4849] = {n="Жнець наносу", d="Цих крихітних женців часто посилають уздовж берега під час відпливу, щоб збирати вантажі й деревину, які прибило до суходолу з розбитих кораблів."},
    [4851] = {n="Крихітний сніговий приятель", d="Стільки святкового настрою в одній малесенькій купці снігу — гріх не поділитися ним з усім світом!"},
    [4852] = {n="Малий Даз'ті", d="Колись давні дінаманти вірили, що чисто-білі луски на динозаврах указують на вплив небесних світил. У своєму прагненні рівноваги Лун'алай перейнялися цими повір'ями, намагаючись відродити білого брутозавра."},
    [4853] = {n="Іржокорінь Скверноносий", d="Скверноносі мають дуже гострий нюх. Вони часто підпалюють купи листя, мотлоху чи снігу, щоб знайти траву й насіння."},
    [4854] = {n="Тьмянозуб Скверноносий", d="Темна, просякнута скверною шерсть тьмянозуба дає йому змогу легше ховатися в лісах Скверноліса."},
    [4855] = {n="Затхлохутрий Скверноносий", d="Надзвичайно агресивний скверноносий. Через неприємну вдачу він став ізгоєм серед інших скверноносих."},
    [4856] = {n="Кошлаторіг Скверноносий", d="З-поміж усіх скверноносих цей має найкошлатішу й найтеплішу шерсть. Він дуже приязний, але будь надзвичайно обережний, коли гладиш його."},
    [4858] = {n="Тіньохутрий пивокрадій", d="Якщо в тебе є чай з молоком, пильнуй його. Пивокради люблять вискакувати з тіні й красти чай. Та що гірше — заволодівши ним, вони полюбляють хизуватися щойно поцупленим питвом."},
    [4859] = {n="Зо'я", d="Зо'я хитра й гарна — обидві риси вельми цінують муркуни. Хоч вона й винуватиця багатьох прикрощів, її тепле сяйво дбає про те, щоб їй прощали будь-яку провину."},
    [4860] = {n="Незворушний водолаз", d="Хоча муркуни й мають хист губитися, жоден не був таким обдарованим, як цей. Та, муркочучи без жодних турбот, ця допитлива істота здатна почуватися чудово в будь-якій ситуації."},
    [4862] = {n="Тліюча доблесть", d="Сповнене безмежної енергії та нестримного завзяття, лоша рветься в небо. Можливо, воно ще не готове, та будь обережний, якщо спробуєш його стримати."},
    [4874] = {n="Пташеня акіл", d="З линялого пір'я цих молодих орлів амані роблять зручну постіль."},
    [4875] = {n="Гніздовик корінчиків", d="Молоді гайоповзи полюбляють згортатися клубочком навколо щиколоток своїх захисників, щоб відпочити."},
    [4876] = {n="Багнюшна жабопуголовка", d="Вони НЕ на смак як картопля. Обіцяю."},
    [4877] = {n="Багряне курча", d="Ці чепуристі нелетючі птахи відомі тим, що невпинно чистять собі пір'я. Геть як їхні вершники."},
    [4878] = {n="Чорнокусайчик", d="Ой, кусь!! Ящірка!"},
    [4879] = {n="Пухирчастий повзунчик", d="Можна було б подумати, що з усіма цими шипами він рано чи пізно проштрикне власний пухир. Та ба! Його пухир насправді дуже міцний! Пухир!"},
    [4880] = {n="Болотяний кусач", d="Зачаївся під темними водами з гострими, мов голки, зубами. Та й ти можеш його вкусити й напитися його крові. Це дозволено."},
    [4881] = {n="Викачувачка Нетеру", d="Скрегітлива паща, повна зубів і язиків. Ця бестія напрочуд схожа на азеротських п'явок."},
    [4882] = {n="Блакитний споровий кажан", d="Не плутати зі споровими кажанами, що мешкають на Дреноре й в Аутленді. Це просто збіг."},
    [4883] = {n="Драконосокіл-мохокрил", d="Ці драконосоколи розвинулися в нетрях Зул'Аману, де зелене пір'я й линяння допомагають їм ховатися від мисливців і хижаків."},
    [4884] = {n="Панголіл", d="Він щось замислив. Криво посміхається. Не довіряй йому."},
    [4885] = {n="Похмура ропуха", d="Стриб-бажаю гарного дня!"},
    [4886] = {n="Шовкоповз", d="Точно-точно перетвориться на прекрасне крилате створіння, ага. Просто на це може піти кілька десятків років."},
    [4887] = {n="Дундун", d="[PH]"},
    [4888] = {n="Налокі", d="З бойовим розписом на хутрі й гарчанням у животі Налокі мріє колись заревіти, як Налоракк."},
    [4889] = {n="Фамільяр Нижнього світу", d="Просякнуті арканною магією вирми — улюблені фамільяри магів Лісу Вічної Пісні."},
    [4890] = {n="Яскравий маналінг", d="Після послаблення «Арканного потоку» популяція манавирмів суттєво зросла."},
    [4891] = {n="Гнівний вирм", d="У нього виростають крила! Тікайте!"},
    [4892] = {n="Фамільяр Клинка Розлому", d="Подейкують, що це фамільяр мага рен'дорей, який утік у нетрі Войдшторму й просякнув Порожнечею ще глибше."},
    [4894] = {n="Слухач Сяйва Серця", d="Доброта дарує надії золоті крила, а пір'я Слухача Сяйва Серця супроводжує нас крізь кожну тиху ніч."},
    [4895] = {n="Кусючик", d="Якщо в тебе є риба, Кусючик напевне крутитиметься поруч."},
    [4896] = {n="Слизький Сол", d="Слизький Сол любить ковзати землею чи морем у пошуках риби."},
    [4897] = {n="Торговка рибою Мей", d="На думку Мей, риби багато не буває."},
    [4898] = {n="Рибна паличка Кіт", d="Морожена риба — улюблені ласощі Кіта. Якщо в тебе є морожена риба, ти знайшов нового найкращого друга."},
    [4899] = {n="Святкова Ів", d="Здається, зимові свята йдуть слідом за Ів, хоч би куди вона потрапила."},
    [4900] = {n="Закутаний Боб", d="Колись цей вид тюленів населяв північні землі Східних Королівств, та після того, як під час Другої війни на нього полювали заради м'яса й шкіри, тепер він трапляється лише в Нортренді."},
    [4901] = {n="Супутник молодого вартового", d="Це юне пташеня готове й палко прагне розпочати навчання."},
    [4902] = {n="Сприятливий Піксіу", d="Рідкісний сприятливий звір Пандарії. Бувалі гозени звуть його «портативним підсилювачем удачі»."},
    [4903] = {n="Дракончик зоряного осколка", d="Допитливий і цікавий, цей дракончик із зоряним блиском в очах має великі мрії та бажання дослідити кожен світ усесвіту."},
    [4906] = {n="Кошлатодзьоб", d="Вилупившись із давно забутого яйця, це кошлате орлятко вирішило, що ти його нова зграя, готовий ти до цього чи ні."},
    [4907] = {n="Малий Вуглик", d="Ніхто не знає, звідки Малий Вуглик дістав своє ім'я. Чи то через його чорне серце? Чи то через любов до теплого вогню? Чи просто тому, що один з його батьків був Великим Вугликом. Питати його марно — у відповідь лише лють."},
    [4908] = {n="Мала Попеляна", d="Мала Попеляна тихо вичікує свого часу, доки звільниться трон влади. А діставшись влади, Мала Попеляна принесе всім веселощі, втіху й вогонь!"},
    [4909] = {n="Смарагдове маля", d="Загубившись у самій гущі бою, це пташеня яструбоступа потребує нової домівки."},
    [4910] = {n="До, дитя Філо", d="Як і його батько, До говорить мало, проте є другом майже кожному — окрім тих, хто кривдить невинних."},
    [4911] = {n="Помічник P.O.S.T.", d="Хоч ринки Тазавеша й працюють як добре змащений механізм, служба P.O.S.T. — це вир пергаментів, коробок і норовливої худоби. Залучення помічників P.O.S.T. до поводження з небезпечними матеріалами врятувало від чималого головного болю."},
    [4912] = {n="Мітла Срібномісяччя", d="Магістри полюбляють вмикати свої зачаровані мітли перед виходом на роботу, аби потім знайти їх застряглими в кутку своєї оселі в Срібномісяччі."},
    [4913] = {n="Місячний стрілець", d="Відколи з'явився Амірдрассіл, чимало чарівних драконів знайшли прихисток у Беламеті. Та багато інших і досі вважають Калімдор своєю домівкою."},
    [4914] = {n="Холодоповз", d="Спокійно. Це лише павук."},
    [4927] = {n="Персіваль", d="Цей картопуголовок постійно десь застрягає."},
    [4928] = {n="Драконояструб-крихітка", d="Ця крихітна порода драконояструбів популярна серед тих, хто полюбляє супутників дорожнього розміру. Лише тримай їх подалі від штор."},
    [4929] = {n="Хрумчик", d="Юний гайоповз, якого з любов'ю виплекали гара'ті."},
    [4930] = {n="Малий шукач здобичі", d="Цей змій не може дочекатися, коли виросте великим і сильним, щоб теж полювати на Здобич!"},
    [4942] = {n="Спотворений спогад", d="Збурений спогад, притягнутий до тебе з Розлому Альну."},
    [4943] = {n="Сонечко, щасливий дракон", d="Сонечко щойно вилупилася й готова до пригод. Іноді подрімати — найбільша пригода з усіх."},
    [4944] = {n="Ґуммі, сяйливий змій", d="У Ґуммі, сяйливого змія, безліч природних хижаків, адже він славиться своєю гумовою текстурою та солодким смаком."},
    [4946] = {n="Лінда Щаслива", d="Цей картопуголовок вдячний тобі за допомогу після того, як зазнав впливу Світлоцвіту."},
    [4947] = {n="Помічник ботаніка Листик", d="Помічник ботаніка Листик — знавець із розпізнавання їстівних рослин... а їстівні вони всі."},
    [4948] = {n="Стривожений спорокажан", d="Після того, як його грубо запхали в гарбуз у марних спробах вилікувати ураження Світлоцвітом, цей спорокажан просто радий, що вибрався назовні."},
    [4950] = {n="Фідофікус", d="Піддослідним зразком він був нікудишнім, та, можливо, із нього вийде гарний супутник."},
    [4951] = {n="Булькотливе кусеня", d="Яке ж радісне кусеня!"},
    [4952] = {n="Бліцкрик", d="Розвиток у Войдштормі справді зробив його дрібніших мешканців значно агресивнішими."},
    [4953] = {n="Спорбі", d="«У цьому домі ми не сіємо спори людям у вуха, поки вони сплять, хоч би яким кумедним було їхнє обличчя, коли вони прокидаються.»"},
    [4954] = {n="Зіорґ'фарон", d="Зіорґ'фарон, Посланець Космічного Невідомого, Згубитель Усього, Що Є, Що Було і Що Будь-Коли Буде, або ж Зіґі, як його кличуть друзі, фізично не здатний скривдити навіть муху."},
    [4955] = {n="Кріпа'зойд", d="Воно не кусає. Воно роздирає й шматує."},
    [4956] = {n="Спорміліан", d="Перевальцем сновигає у вічній хмарі спор. Безпечний? Важко сказати — ми досі чекаємо на дослідницьку команду... або на те, що від неї лишилося."},
    [4957] = {n="Загублена зірка", d="Напевне нічого не відомо, хоча дехто вважає, що домівкою їй слугує нічне небо."},
    [4958] = {n="Зловісний Доманус", d="Воістину лихий, безперечно могутній... але понад усе — на диво лінивий."},
    [4959] = {n="Зачаклований кролик", d="Опинився не в тому місці й не в той час."},
    [4960] = {n="Треджа'сака", d="Дивовижний вид, що трапляється лише у скринях зі скарбами. Цілком безпечний, хіба що на тобі є прикраси."},
    [4961] = {n="Гризунчик", d="Дуже нещасний. Завжди цілиться в горло. Якийсь навіть милий."},
    [4963] = {n="Буркотлива мандрагора", d="Увага: може пустити коріння тобі під ноги."},
    [4964] = {n="Пухка мандрагора"},
    [4965] = {n="Щебетлива мандрагора"},
    [4966] = {n="Вересклива мандрагора"},
    [4967] = {n="Ґортам", d="Жива аномалія і найцінніший дослід Касрета, ця рожевошерста істота радісно гасає крізь канали й труби."},
    [4968] = {n="Малий зореніг", d="Зорі ходять поміж нами в подобі малого брутозавра."},
    [4969] = {n="Руфус", d="Руфус готовий підставити лапу для будь-якого будівельного проєкту. Смаколики не обов'язкові, та завжди приємні."},
    [4971] = {n="Лума", d="Лума знає всілякі трюки, як-от «сидіти», «чекати» і «красти»."},
    [4972] = {n="Віллі", d="Цей сміливий ельфійський пес народжений ганятися за манавирмами та всім, що на манавирма скидається... Як-от лишені без нагляду ковбаски."},
    [4974] = {n="Далі", d="Далі, якому набридли дні, проведені в затишку Соларіанської сонячної купелі, шукає світ нового натхнення. Це натхнення — ти, а він принесе барви у твій світ."},
    [4975] = {n="Разеші Ц.", d="Разеші Ц. відома своєю поблажливою вдачею, виваженими відповідями й любов'ю до пліток. Ц. означає «цілковита взірцевість»."},
    [4976] = {n="Волді", d="Іноді поклик Порожнечі ледь чутний, тож йому коряться менші, молодші блукачі Порожнечі."},
    [4977] = {n="Дитинча Жаросхильника", d="Народжений біля поховального вогнища в Урочистій долині, цей юний орел досі носить у бордовому пір'ї запах диму й попелу. Тиха згадка про те, що навіть у втраті щось нове може здійнятися на крило."},
    [4981] = {n="Нова", d="Він коханець, а не вояк."},
    [4982] = {n="Мерехтіння", d="Рідкісне чорношерсте рисеня з Лісу Вічної Пісні, чия шерсть ледь чутно бринить арканною енергією; магістри Сільвермуна вивели його і як супутника, і як провідник для магічних досліджень."},
    [4983] = {n="Кай", d="Породжений прихованими енергіями Якоря Сингулярності, цей бегемот лишатиметься вірним до самого кінця."},
    [4984] = {n="Медуза", d="Вона терпіти не може, коли її гладять по голові, тому й носить колючу броню."},
    [4985] = {n="Принцеса Кровопролиття", d="Удавшись у свою матір, пані Кровопролиття, принцеса озброєна найгострішими кігтями та найпухнастішими вушками."},
    [5003] = {n="Дитинча Сонцекрила", d="Народжене й вирощене в Гнізді Сонцекрилів, це хлоп'я обожнює капостити, щойно приборкувачі відвернуться."},
    [5012] = {n="Сажолап", d="Цього магічного розвідника часто можна застати за порпанням у покидьках давно зниклих шукачів пригод у пошуках арканних ласощів."},
    [5017] = {n="Орля, позначене Порожнечею", d="Орли Зул'Аману — велична порода, та без опіки Акіл'зона вони геть занепали. Особливо жорстоким був клятвопорушник Ґер'лок, який випробовував свою темну магію на юних орлятах."},
    [5019] = {n="Пухтик", d="Розлучений з матір'ю, коли їх обох упіймали. Пухтик сумний, але затятий. Він пишається собою щоразу, коли вдається вкусити за руку своїх наглядачів із Клинка Сутінків під час годівлі."},
    [5020] = {n="Перевантажений Маналеня", d="Суміш арканної магії та магії Порожнечі, якою володіють наги, розтривожила манавирмів довкола Кинджалохребтового мису й зробила їх украй ворожими. Ті нечисленні маналенята, що вціліли після їхнього ритуалу, виявляють незвичні здібності."},
    [5021] = {n="Снепдракон, спотворений Порожнечею", d="Вірні снепдракони — ідеальні супутники для будь-якої наги. Вони добре пристосовуються до середовища, надто коли середовище й само радо пристосовує їх під себе."},
    [5022] = {n="Пташеня, торкнуте Порожнечею", d="Через спустошливе вторгнення наг чимало яструбоступів загинуло в околицях Кинджалохребтового мису. Знайти їхнє пташеня ще живим — велика рідкість."},
    [5023] = {n="Рисеня, торкнуте Порожнечею", d="Це допитливе рисеня вешталося надто близько до ритуальних місць — і то не одного."},
    [5036] = {n="Врятоване пташеня драконояструба", d="Воно зазнало лише незначного впливу енергії Порожнечі, та вже виявляє ознаки нових здібностей Порожнечі. За належного вишколу ці здібності можна тримати під контролем. — Сержант Ворнін"},
    [5037] = {n="Мальок Розумоламача, просочений Порожнечею", d="Розумоламачі — рідкісні створіння глибин. Про їхнє справжнє походження відомо небагато, та сягає воно ще днів Чорної Імперії."},
    [5038] = {n="Звивиста капібара", d="Ці малі живуть у тісних лігвах і пролазять у найвужчі шпарини, інколи навіть у торби з припасами."},
    [5039] = {n="Капі", d="Капі не пощастило стикнутися з безліччю проявів зіпсуття Порожнечею, та він вистояв. Він — одне з небагатьох створінь, що вибралися майже неушкодженими."},
    [5040] = {n="Допитливе рисеня", d="Приказку «цікавість згубила кота» придумали не про вічноспівних рисей, хоча їхні безрозсудні малята таки знаходять дорогу на передову. Дехто з лісничих знайшов вірного супутника на все життя, що сховався у візках із припасами під час походу."},
    [5065] = {n="Ка'бабб", d="Справжній Рибалка Безодні, посвідчений самим глибоководом Джеджу."},
    [298] = {n="Совина дитина"},
    [281] = {n="Гільдійський паж"},
    [282] = {n="Гільдійський герольд"},
}
